{
  "name": "WP API Architect",
  "description": "A visual editor to design WordPress REST APIs, Custom Post Types, and Taxonomies, with automatic OpenAPI spec and PHP code generation."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum FieldType {
  STRING = 'string',
  INTEGER = 'integer',
  NUMBER = 'number',
  BOOLEAN = 'boolean',
  ARRAY = 'array',
}

export interface MetaField {
  id: string;
  key: string;
  label: string;
  type: FieldType;
  description: string;
  required: boolean;
  showInRest: boolean;
}

export interface Taxonomy {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  hierarchical: boolean;
  showInRest: boolean;
  connectedPostTypes: string[]; // CPT slugs
}

export interface CustomPostType {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  description: string;
  icon: string; // Dashicon class or similar
  supports: string[]; // title, editor, thumbnail, etc.
  taxonomies: string[]; // Slugs of connected taxonomies
  metaFields: MetaField[];
  showInRest: boolean;
  restBase: string;
}

export interface ProjectState {
  name: string;
  namespace: string;
  postTypes: CustomPostType[];
  taxonomies: Taxonomy[];
}

export type ViewMode = 'editor' | 'openapi' | 'php' | 'stats';

import { ProjectState, CustomPostType, Taxonomy, MetaField, FieldType } from '../types';

export const generatePHP = (project: ProjectState): string => {
  const { postTypes, taxonomies, namespace } = project;

  const timestamp = new Date().toISOString();

  let php = `<?php
/**
 * Plugin Name: ${project.name}
 * Description: Auto-generated by WP API Architect
 * Version: 1.0.0
 * Author: WP API Architect
 * Generated: ${timestamp}
 */

if ( ! defined( 'ABSPATH' ) ) {
\texit; // Exit if accessed directly.
}

add_action( 'init', '${project.name.toLowerCase().replace(/\s+/g, '_')}_register_content' );

function ${project.name.toLowerCase().replace(/\s+/g, '_')}_register_content() {
`;

  // Register Taxonomies
  taxonomies.forEach((tax) => {
    php += `
\t// Register Taxonomy: ${tax.pluralName}
\tregister_taxonomy( '${tax.slug}', ${JSON.stringify(tax.connectedPostTypes)}, array(
\t\t'labels' => array(
\t\t\t'name' => '${tax.pluralName}',
\t\t\t'singular_name' => '${tax.singularName}',
\t\t),
\t\t'hierarchical' => ${tax.hierarchical ? 'true' : 'false'},
\t\t'show_in_rest' => ${tax.showInRest ? 'true' : 'false'},
\t) );
`;
  });

  // Register Post Types
  postTypes.forEach((cpt) => {
    php += `
\t// Register Custom Post Type: ${cpt.pluralName}
\tregister_post_type( '${cpt.slug}', array(
\t\t'labels' => array(
\t\t\t'name' => '${cpt.pluralName}',
\t\t\t'singular_name' => '${cpt.singularName}',
\t\t),
\t\t'public' => true,
\t\t'has_archive' => true,
\t\t'menu_icon' => 'dashicons-${cpt.icon}',
\t\t'supports' => array( ${cpt.supports.map((s) => `'${s}'`).join(', ')} ),
\t\t'show_in_rest' => ${cpt.showInRest ? 'true' : 'false'},
\t\t'rest_base' => '${cpt.restBase}',
\t) );
`;
  });

  php += `}\n\n`;

  // Register Meta Fields
  php += `add_action( 'init', '${project.name.toLowerCase().replace(/\s+/g, '_')}_register_meta' );\n`;
  php += `function ${project.name.toLowerCase().replace(/\s+/g, '_')}_register_meta() {\n`;

  postTypes.forEach((cpt) => {
    cpt.metaFields.forEach((field) => {
      if (field.showInRest) {
        php += `
\tregister_post_meta( '${cpt.slug}', '${field.key}', array(
\t\t'show_in_rest' => array(
\t\t\t'schema' => array(
\t\t\t\t'type' => '${field.type}',
\t\t\t\t'description' => '${field.description.replace(/'/g, "\\'")}',
\t\t\t),
\t\t),
\t\t'single' => true,
\t\t'type' => '${field.type === FieldType.INTEGER ? 'integer' : field.type === FieldType.NUMBER ? 'number' : 'string'}',
\t) );
`;
      }
    });
  });

  php += `}`;

  return php;
};

export const generateOpenAPI = (project: ProjectState): string => {
  const paths: any = {};
  const schemas: any = {};

  project.postTypes.forEach((cpt) => {
    if (!cpt.showInRest) return;

    // Define Schema
    const properties: any = {
      id: { type: 'integer', readOnly: true },
      date: { type: 'string', format: 'date-time' },
      status: { type: 'string' },
      type: { type: 'string' },
      link: { type: 'string', format: 'uri', readOnly: true },
      title: { 
        type: 'object', 
        properties: { rendered: { type: 'string' } } 
      },
    };

    if (cpt.supports.includes('editor')) {
      properties.content = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    if (cpt.supports.includes('excerpt')) {
      properties.excerpt = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    // Custom Fields
    cpt.metaFields.forEach(field => {
      if (field.showInRest) {
        properties[field.key] = {
          type: field.type,
          description: field.description
        };
      }
    });

    // Associated Taxonomies
    cpt.taxonomies.forEach(taxSlug => {
       properties[taxSlug] = {
         type: 'array',
         items: { type: 'integer' },
         description: `IDs of ${taxSlug} terms assigned to the post.`
       };
    });

    schemas[cpt.singularName] = {
      type: 'object',
      properties: properties
    };

    // Define Paths
    const pathBase = `/wp/v2/${cpt.restBase}`;

    // Collection Endpoint
    paths[pathBase] = {
      get: {
        summary: `Retrieve a list of ${cpt.pluralName}`,
        tags: [cpt.pluralName],
        responses: {
          '200': {
            description: `List of ${cpt.pluralName}`,
            content: {
              'application/json': {
                schema: {
                  type: 'array',
                  items: { $ref: `#/components/schemas/${cpt.singularName}` }
                }
              }
            }
          }
        }
      },
      post: {
        summary: `Create a new ${cpt.singularName}`,
        tags: [cpt.pluralName],
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: { $ref: `#/components/schemas/${cpt.singularName}` }
            }
          }
        },
        responses: {
          '201': {
            description: `${cpt.singularName} created`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      }
    };

    // Single Endpoint
    paths[`${pathBase}/{id}`] = {
      get: {
        summary: `Retrieve a single ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
            description: `A single ${cpt.singularName}`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
      post: {
        summary: `Update a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        requestBody: {
           content: {
             'application/json': {
               schema: { $ref: `#/components/schemas/${cpt.singularName}` }
             }
           }
        },
        responses: {
          '200': {
            description: `${cpt.singularName} updated`,
             content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
       delete: {
        summary: `Delete a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
             description: `${cpt.singularName} deleted`,
          }
        }
      }
    };
  });

  const spec = {
    openapi: '3.0.0',
    info: {
      title: project.name,
      version: '1.0.0',
      description: `Generated REST API for ${project.name}`
    },
    paths: paths,
    components: {
      schemas: schemas
    }
  };

  return JSON.stringify(spec, null, 2);
};

import { GoogleGenAI, Type } from "@google/genai";
import { ProjectState } from '../types';

export const generateProjectStructure = async (prompt: string, currentProject: ProjectState): Promise<Partial<ProjectState>> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemPrompt = `
    You are an expert WordPress Architect.
    Your goal is to interpret a user's natural language request and generate a structured JSON object representing WordPress Custom Post Types (CPTs) and Taxonomies.

    The output must strictly follow the schema provided.
    Ensure "slugs" are snake_case and "names" are Title Case.
    Ensure "supports" includes reasonable defaults like 'title', 'editor', 'thumbnail' if relevant.
    Generate 2-5 relevant meta fields (custom fields) for each post type if appropriate.
    Connect Taxonomies to Post Types via the 'connectedPostTypes' or 'taxonomies' fields logic.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Current Project Name: ${currentProject.name}. User Request: ${prompt}`,
    config: {
      systemInstruction: systemPrompt,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          postTypes: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                slug: { type: Type.STRING },
                singularName: { type: Type.STRING },
                pluralName: { type: Type.STRING },
                description: { type: Type.STRING },
                icon: { type: Type.STRING },
                supports: { type: Type.ARRAY, items: { type: Type.STRING } },
                taxonomies: { type: Type.ARRAY, items: { type: Type.STRING } },
                showInRest: { type: Type.BOOLEAN },
                restBase: { type: Type.STRING },
                metaFields: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      key: { type: Type.STRING },
                      label: { type: Type.STRING },
                      type: { type: Type.STRING, enum: ['string', 'integer', 'number', 'boolean', 'array'] },
                      description: { type: Type.STRING },
                      required: { type: Type.BOOLEAN },
                      showInRest: { type: Type.BOOLEAN },
                    },
                    required: ['key', 'label', 'type', 'description']
                  }
                }
              },
              required: ['slug', 'singularName', 'pluralName', 'supports', 'metaFields']
            }
          },
          taxonomies: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                slug: { type: Type.STRING },
                singularName: { type: Type.STRING },
                pluralName: { type: Type.STRING },
                hierarchical: { type: Type.BOOLEAN },
                showInRest: { type: Type.BOOLEAN },
                connectedPostTypes: { type: Type.ARRAY, items: { type: Type.STRING } }
              },
              required: ['slug', 'singularName', 'pluralName', 'connectedPostTypes']
            }
          }
        }
      }
    }
  });

  if (!response.text) {
    throw new Error("No response from AI");
  }

  const data = JSON.parse(response.text);

  // Post-processing to add IDs since the AI schema doesn't force unique string IDs nicely
  const processedPostTypes = data.postTypes?.map((pt: any) => ({
    ...pt,
    id: `cpt_${Math.random().toString(36).substr(2, 9)}`,
    metaFields: pt.metaFields?.map((mf: any) => ({
      ...mf,
      id: `field_${Math.random().toString(36).substr(2, 9)}`,
    })) || []
  })) || [];

  const processedTaxonomies = data.taxonomies?.map((tx: any) => ({
    ...tx,
    id: `tax_${Math.random().toString(36).substr(2, 9)}`
  })) || [];

  return {
    postTypes: processedPostTypes,
    taxonomies: processedTaxonomies
  };
};

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { ProjectState } from '../types';

interface StatsChartProps {
  project: ProjectState;
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8'];

export const StatsChart: React.FC<StatsChartProps> = ({ project }) => {
  const complexityData = project.postTypes.map(pt => ({
    name: pt.singularName,
    Fields: pt.metaFields.length,
    Taxonomies: pt.taxonomies.length,
    Supports: pt.supports.length
  }));

  const typeDistribution = project.postTypes.reduce((acc, pt) => {
    pt.metaFields.forEach(field => {
      acc[field.type] = (acc[field.type] || 0) + 1;
    });
    return acc;
  }, {} as Record<string, number>);

  const pieData = Object.keys(typeDistribution).map((key) => ({
    name: key,
    value: typeDistribution[key]
  }));

  return (
    <div className="h-full w-full p-6 overflow-y-auto">
      <h2 className="text-2xl font-bold mb-6 text-white">API Complexity Analysis</h2>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-slate-800 p-4 rounded-xl shadow-lg border border-slate-700">
          <h3 className="text-lg font-semibold mb-4 text-slate-300">Resource Composition</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={complexityData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                <XAxis dataKey="name" stroke="#9CA3AF" />
                <YAxis stroke="#9CA3AF" />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1F2937', border: '1px solid #374151', color: '#F3F4F6' }}
                />
                <Legend />
                <Bar dataKey="Fields" fill="#8884d8" />
                <Bar dataKey="Supports" fill="#82ca9d" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-slate-800 p-4 rounded-xl shadow-lg border border-slate-700">
          <h3 className="text-lg font-semibold mb-4 text-slate-300">Data Type Distribution</h3>
          <div className="h-64">
             <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                  outerRadius={80}
                  fill="#8884d8"
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip 
                   contentStyle={{ backgroundColor: '#1F2937', border: '1px solid #374151', color: '#F3F4F6' }}
                />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { generateProjectStructure } from '../services/geminiService';
import { ProjectState } from '../types';
import { Loader2, Sparkles, X } from 'lucide-react';

interface AIAssistantProps {
  project: ProjectState;
  onApply: (newStructure: Partial<ProjectState>) => void;
  onClose: () => void;
}

export const AIAssistant: React.FC<AIAssistantProps> = ({ project, onApply, onClose }) => {
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const result = await generateProjectStructure(prompt, project);
      onApply(result);
      onClose();
    } catch (e: any) {
      setError(e.message || "Failed to generate structure.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50">
      <div className="bg-slate-800 rounded-xl border border-slate-700 w-full max-w-lg p-6 shadow-2xl relative">
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-400 hover:text-white">
          <X size={20} />
        </button>

        <div className="flex items-center gap-2 mb-4 text-purple-400">
          <Sparkles size={24} />
          <h2 className="text-xl font-bold text-white">Gemini Architect</h2>
        </div>

        <p className="text-slate-300 mb-4 text-sm">
          Describe your API needs in plain English. E.g., "Create an Event system with Speakers and Locations."
        </p>

        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="Describe your data model..."
          className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white placeholder-slate-500 focus:ring-2 focus:ring-purple-500 focus:outline-none min-h-[120px]"
        />

        {error && (
          <div className="mt-4 p-3 bg-red-900/50 border border-red-700 rounded text-red-200 text-sm">
            {error}
          </div>
        )}

        <div className="mt-6 flex justify-end gap-3">
          <button 
            onClick={onClose}
            className="px-4 py-2 rounded-lg text-slate-300 hover:bg-slate-700 transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={handleGenerate}
            disabled={loading || !prompt.trim()}
            className="px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg flex items-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed font-medium"
          >
            {loading ? <Loader2 className="animate-spin" size={18} /> : <Sparkles size={18} />}
            Generate
          </button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { CustomPostType, FieldType, MetaField, Taxonomy } from '../types';
import { DEFAULT_SUPPORTS_OPTIONS } from '../constants';
import { Plus, Trash2, Settings } from 'lucide-react';

interface ResourceEditorProps {
  cpt: CustomPostType;
  allTaxonomies: Taxonomy[];
  onChange: (updatedCpt: CustomPostType) => void;
  onDelete: () => void;
}

export const ResourceEditor: React.FC<ResourceEditorProps> = ({ cpt, allTaxonomies, onChange, onDelete }) => {

  const handleFieldChange = (fieldId: string, changes: Partial<MetaField>) => {
    const updatedFields = cpt.metaFields.map(f => f.id === fieldId ? { ...f, ...changes } : f);
    onChange({ ...cpt, metaFields: updatedFields });
  };

  const addField = () => {
    const newField: MetaField = {
      id: `field_${Date.now()}`,
      key: 'new_field',
      label: 'New Field',
      type: FieldType.STRING,
      description: '',
      required: false,
      showInRest: true,
    };
    onChange({ ...cpt, metaFields: [...cpt.metaFields, newField] });
  };

  const removeField = (id: string) => {
    onChange({ ...cpt, metaFields: cpt.metaFields.filter(f => f.id !== id) });
  };

  const toggleSupport = (option: string) => {
    const newSupports = cpt.supports.includes(option)
      ? cpt.supports.filter(s => s !== option)
      : [...cpt.supports, option];
    onChange({ ...cpt, supports: newSupports });
  };

  const toggleTaxonomy = (taxSlug: string) => {
    const newTaxonomies = cpt.taxonomies.includes(taxSlug)
      ? cpt.taxonomies.filter(t => t !== taxSlug)
      : [...cpt.taxonomies, taxSlug];
    onChange({ ...cpt, taxonomies: newTaxonomies });
  };

  return (
    <div className="h-full overflow-y-auto p-8 custom-scrollbar">
      <div className="flex justify-between items-start mb-8">
        <div>
          <h2 className="text-3xl font-bold text-white mb-2">{cpt.singularName}</h2>
          <p className="text-slate-400">Post Type Configuration</p>
        </div>
        <button 
          onClick={onDelete}
          className="text-red-400 hover:text-red-300 hover:bg-red-900/20 px-3 py-2 rounded-lg transition-colors flex items-center gap-2"
        >
          <Trash2 size={18} />
          Delete Resource
        </button>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

        {/* Main Settings */}
        <div className="xl:col-span-2 space-y-8">

          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 space-y-6">
            <h3 className="text-lg font-semibold text-slate-200 flex items-center gap-2">
              <Settings size={20} className="text-indigo-400"/> General Settings
            </h3>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Singular Name</label>
                <input 
                  type="text" 
                  value={cpt.singularName} 
                  onChange={e => onChange({...cpt, singularName: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Plural Name</label>
                <input 
                  type="text" 
                  value={cpt.pluralName} 
                  onChange={e => onChange({...cpt, pluralName: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Slug (Key)</label>
                <input 
                  type="text" 
                  value={cpt.slug} 
                  onChange={e => onChange({...cpt, slug: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white focus:ring-2 focus:ring-indigo-500 outline-none font-mono text-sm"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">REST Base</label>
                <input 
                  type="text" 
                  value={cpt.restBase} 
                  onChange={e => onChange({...cpt, restBase: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white focus:ring-2 focus:ring-indigo-500 outline-none font-mono text-sm"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1">Description</label>
              <textarea 
                value={cpt.description} 
                onChange={e => onChange({...cpt, description: e.target.value})}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white focus:ring-2 focus:ring-indigo-500 outline-none h-20 resize-none"
              />
            </div>
          </div>

          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700">
            <div className="flex justify-between items-center mb-6">
