import React, { useState } from 'react';
import { ProjectState } from '../types';
import { generateOpenAPI, generatePHP } from '../services/wpGenerator';
import { Copy, Check } from 'lucide-react';

interface CodePreviewProps {
  project: ProjectState;
  initialTab?: 'openapi' | 'php';
}

export const CodePreview: React.FC<CodePreviewProps> = ({ project, initialTab = 'openapi' }) => {
  const [tab, setTab] = useState<'openapi' | 'php'>(initialTab);
  const [copied, setCopied] = useState(false);

  const content = tab === 'openapi' ? generateOpenAPI(project) : generatePHP(project);

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e]">
      <div className="flex items-center justify-between px-4 py-2 bg-[#252526] border-b border-[#333]">
        <div className="flex gap-1">
          <button 
            onClick={() => setTab('openapi')}
            className={`px-4 py-2 text-sm rounded-t-lg transition-colors ${tab === 'openapi' ? 'bg-[#1e1e1e] text-blue-400 font-medium' : 'text-slate-400 hover:text-slate-200'}`}
          >
            openapi.json
          </button>
          <button 
             onClick={() => setTab('php')}
             className={`px-4 py-2 text-sm rounded-t-lg transition-colors ${tab === 'php' ? 'bg-[#1e1e1e] text-purple-400 font-medium' : 'text-slate-400 hover:text-slate-200'}`}
          >
            plugin.php
          </button>
        </div>
        <button 
          onClick={handleCopy}
          className="flex items-center gap-2 text-xs text-slate-400 hover:text-white px-3 py-1.5 rounded bg-[#333] hover:bg-[#444] transition-colors"
        >
          {copied ? <Check size={14} className="text-green-500"/> : <Copy size={14} />}
          {copied ? 'Copied' : 'Copy'}
        </button>
      </div>
      <div className="flex-1 overflow-auto p-4 custom-scrollbar">
        <pre className="font-mono text-sm leading-relaxed text-[#d4d4d4]">
          <code>{content}</code>
        </pre>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ProjectState, ViewMode, CustomPostType, Taxonomy } from './types';
import { INITIAL_PROJECT_STATE } from './constants';
import { ResourceEditor } from './components/ResourceEditor';
import { CodePreview } from './components/CodePreview';
import { StatsChart } from './components/StatsChart';
import { AIAssistant } from './components/AIAssistant';
import { 
  Box, 
  Code, 
  LayoutTemplate, 
  Sparkles, 
  PieChart as ChartIcon, 
  Plus, 
  FileJson,
  Database
} from 'lucide-react';

const App = () => {
  const [project, setProject] = useState<ProjectState>(INITIAL_PROJECT_STATE);
  const [currentView, setCurrentView] = useState<ViewMode>('editor');
  const [selectedResourceId, setSelectedResourceId] = useState<string>(project.postTypes[0].id);
  const [isAIModalOpen, setAIModalOpen] = useState(false);

  // When post types change, if selected ID is gone, select the first one
  useEffect(() => {
    const exists = project.postTypes.find(pt => pt.id === selectedResourceId);
    if (!exists && project.postTypes.length > 0) {
      setSelectedResourceId(project.postTypes[0].id);
    }
  }, [project.postTypes, selectedResourceId]);

  const handleUpdateResource = (updatedCpt: CustomPostType) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.map(pt => pt.id === updatedCpt.id ? updatedCpt : pt)
    }));
  };

  const handleAddResource = () => {
    const newId = `cpt_${Date.now()}`;
    const newCpt: CustomPostType = {
      id: newId,
      slug: 'new_type',
      singularName: 'New Type',
      pluralName: 'New Types',
      description: '',
      icon: 'admin-post',
      supports: ['title', 'editor'],
      taxonomies: [],
      metaFields: [],
      showInRest: true,
      restBase: 'new_types'
    };
    setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, newCpt] }));
    setSelectedResourceId(newId);
    setCurrentView('editor');
  };

  const handleDeleteResource = (id: string) => {
    if (project.postTypes.length <= 1) {
      alert("You need at least one Post Type.");
      return;
    }
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.filter(pt => pt.id !== id)
    }));
  };

  const handleAIApply = (partial: Partial<ProjectState>) => {
    setProject(prev => ({
      ...prev,
      postTypes: [...prev.postTypes, ...(partial.postTypes || [])],
      taxonomies: [...prev.taxonomies, ...(partial.taxonomies || [])]
    }));
  };

  const selectedCpt = project.postTypes.find(pt => pt.id === selectedResourceId);

  return (
    <div className="flex h-screen bg-slate-900 text-slate-100 overflow-hidden font-sans">

      {/* Sidebar */}
      <div className="w-64 bg-slate-950 flex flex-col border-r border-slate-800">
        <div className="p-4 border-b border-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center">
            <LayoutTemplate size={18} className="text-white"/>
          </div>
          <span className="font-bold text-lg tracking-tight">WP Architect</span>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-4 mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">Resources</div>
          <div className="space-y-1 px-2">
            {project.postTypes.map(pt => (
              <button
                key={pt.id}
                onClick={() => {
                  setSelectedResourceId(pt.id);
                  setCurrentView('editor');
                }}
                className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${selectedResourceId === pt.id && currentView === 'editor' ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
              >
                <Box size={16} />
                {pt.pluralName}
              </button>
            ))}
            <button 
              onClick={handleAddResource}
              className="w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 text-slate-500 hover:text-indigo-400 hover:bg-slate-900 transition-colors border border-dashed border-slate-800 hover:border-indigo-500/50 mt-2"
            >
              <Plus size={16} /> Add Resource
            </button>
          </div>

          <div className="px-4 mt-8 mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">Project Views</div>
          <div className="space-y-1 px-2">
            <button 
              onClick={() => setCurrentView('openapi')}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentView === 'openapi' ? 'bg-blue-600/20 text-blue-300 border border-blue-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            >
              <FileJson size={16} /> OpenAPI Spec
            </button>
            <button 
              onClick={() => setCurrentView('php')}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentView === 'php' ? 'bg-purple-600/20 text-purple-300 border border-purple-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            >
              <Code size={16} /> PHP Plugin
            </button>
            <button 
              onClick={() => setCurrentView('stats')}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentView === 'stats' ? 'bg-emerald-600/20 text-emerald-300 border border-emerald-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            >
              <ChartIcon size={16} /> Analysis
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800">
          <button 
            onClick={() => setAIModalOpen(true)}
            className="w-full bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white py-2 rounded-lg shadow-lg shadow-purple-900/20 flex items-center justify-center gap-2 font-medium transition-all"
          >
            <Sparkles size={16} /> AI Assistant
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0f111a]">
        {currentView === 'editor' && selectedCpt ? (
          <ResourceEditor 
            cpt={selectedCpt} 
            allTaxonomies={project.taxonomies}
            onChange={handleUpdateResource}
            onDelete={() => handleDeleteResource(selectedCpt.id)}
          />
        ) : currentView === 'openapi' ? (
           <CodePreview project={project} initialTab="openapi" />
        ) : currentView === 'php' ? (
           <CodePreview project={project} initialTab="php" />
        ) : currentView === 'stats' ? (
           <StatsChart project={project} />
        ) : (
          <div className="flex items-center justify-center h-full text-slate-500">
             Select a resource to edit
          </div>
        )}
      </div>

      {isAIModalOpen && (
        <AIAssistant 
          project={project} 
          onApply={handleAIApply} 
          onClose={() => setAIModalOpen(false)} 
        />
      )}
    </div>
  );
};

export default App;

{
  "name": "WP API Architect",
  "description": "Visual designer for WordPress REST APIs: Create Custom Post Types, Taxonomies, and Custom Endpoint Routes mapped to PHP actions and hooks.",
  "requestFramePermissions": []
}

export enum FieldType {
  STRING = 'string',
  INTEGER = 'integer',
  NUMBER = 'number',
  BOOLEAN = 'boolean',
  ARRAY = 'array',
}

export interface MetaField {
  id: string;
  key: string;
  label: string;
  type: FieldType;
  description: string;
  required: boolean;
  showInRest: boolean;
}

export interface Taxonomy {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  hierarchical: boolean;
  showInRest: boolean;
  connectedPostTypes: string[]; // CPT slugs
}

export interface CustomPostType {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  description: string;
  icon: string; // Dashicon class or similar
  supports: string[]; // title, editor, thumbnail, etc.
  taxonomies: string[]; // Slugs of connected taxonomies
  metaFields: MetaField[];
  showInRest: boolean;
  restBase: string;
}

export type EndpointMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';

export interface EndpointParameter {
  id: string;
  key: string;
  required: boolean;
  type: string;
  description: string;
}

export interface CustomEndpoint {
  id: string;
  route: string; // e.g., /checkout/process
  method: EndpointMethod;
  callbackFunction: string;
  description: string;
  parameters: EndpointParameter[];
  hookName?: string; // Optional custom action to fire
}

export interface ProjectState {
  name: string;
  namespace: string;
  postTypes: CustomPostType[];
  taxonomies: Taxonomy[];
  customEndpoints: CustomEndpoint[];
}

export type ViewMode = 'editor' | 'openapi' | 'php' | 'stats';
export type ResourceType = 'postType' | 'endpoint';

import { ProjectState, CustomPostType, Taxonomy, MetaField, FieldType, CustomEndpoint } from '../types';

export const generatePHP = (project: ProjectState): string => {
  const { postTypes, taxonomies, customEndpoints, namespace } = project;
  const projectSlug = project.name.toLowerCase().replace(/\s+/g, '_');
  const timestamp = new Date().toISOString();

  let php = `<?php
/**
 * Plugin Name: ${project.name}
 * Description: Auto-generated by WP API Architect
 * Version: 1.0.0
 * Author: WP API Architect
 * Generated: ${timestamp}
 */

if ( ! defined( 'ABSPATH' ) ) {
\texit; // Exit if accessed directly.
}

// -------------------------------------------------------------------------
// 1. Content Definitions (CPT & Taxonomies)
// -------------------------------------------------------------------------

add_action( 'init', '${projectSlug}_register_content' );

function ${projectSlug}_register_content() {
`;

  // Register Taxonomies
  taxonomies.forEach((tax) => {
    php += `
\t// Register Taxonomy: ${tax.pluralName}
\tregister_taxonomy( '${tax.slug}', ${JSON.stringify(tax.connectedPostTypes)}, array(
\t\t'labels' => array(
\t\t\t'name' => '${tax.pluralName}',
\t\t\t'singular_name' => '${tax.singularName}',
\t\t),
\t\t'hierarchical' => ${tax.hierarchical ? 'true' : 'false'},
\t\t'show_in_rest' => ${tax.showInRest ? 'true' : 'false'},
\t) );
`;
  });

  // Register Post Types
  postTypes.forEach((cpt) => {
    php += `
\t// Register Custom Post Type: ${cpt.pluralName}
\tregister_post_type( '${cpt.slug}', array(
\t\t'labels' => array(
\t\t\t'name' => '${cpt.pluralName}',
\t\t\t'singular_name' => '${cpt.singularName}',
\t\t),
\t\t'public' => true,
\t\t'has_archive' => true,
\t\t'menu_icon' => 'dashicons-${cpt.icon}',
\t\t'supports' => array( ${cpt.supports.map((s) => `'${s}'`).join(', ')} ),
\t\t'show_in_rest' => ${cpt.showInRest ? 'true' : 'false'},
\t\t'rest_base' => '${cpt.restBase}',
\t) );
`;
  });

  php += `}\n\n`;

  // Register Meta Fields
  if (postTypes.some(pt => pt.metaFields.length > 0)) {
    php += `add_action( 'init', '${projectSlug}_register_meta' );\n`;
    php += `function ${projectSlug}_register_meta() {\n`;

    postTypes.forEach((cpt) => {
      cpt.metaFields.forEach((field) => {
        if (field.showInRest) {
          php += `
\tregister_post_meta( '${cpt.slug}', '${field.key}', array(
\t\t'show_in_rest' => array(
\t\t\t'schema' => array(
\t\t\t\t'type' => '${field.type}',
\t\t\t\t'description' => '${field.description.replace(/'/g, "\\'")}',
\t\t\t),
\t\t),
\t\t'single' => true,
\t\t'type' => '${field.type === FieldType.INTEGER ? 'integer' : field.type === FieldType.NUMBER ? 'number' : 'string'}',
\t) );
`;
        }
      });
    });

    php += `}\n\n`;
  }

  // -------------------------------------------------------------------------
  // 2. Custom REST Endpoints
  // -------------------------------------------------------------------------

  if (customEndpoints.length > 0) {
    php += `add_action( 'rest_api_init', '${projectSlug}_register_routes' );\n\n`;
    php += `function ${projectSlug}_register_routes() {\n`;

    customEndpoints.forEach(endpoint => {
      // Clean route to ensure it doesn't start with / if namespace handles it, 
      // but WP register_rest_route expects route to be relative to namespace.
      // E.g. namespace 'v1', route '/books' -> URL .../v1/books
      const cleanRoute = endpoint.route.startsWith('/') ? endpoint.route : '/' + endpoint.route;

      php += `
\tregister_rest_route( '${namespace}', '${cleanRoute}', array(
\t\t'methods' => '${endpoint.method}',
\t\t'callback' => '${endpoint.callbackFunction}',
\t\t'permission_callback' => '__return_true', // @TODO: Update security logic
\t\t'args' => array(
${endpoint.parameters.map(param => `\t\t\t'${param.key}' => array(
\t\t\t\t'required' => ${param.required ? 'true' : 'false'},
\t\t\t\t'type' => '${param.type}',
\t\t\t\t'description' => '${param.description.replace(/'/g, "\\'")}',
\t\t\t),`).join('\n')}
\t\t),
\t) );
`;
    });

    php += `}\n\n`;

    // Generate Callback Stubs
    customEndpoints.forEach(endpoint => {
      php += `/**\n * Callback for ${endpoint.method} ${endpoint.route}\n */\n`;
      php += `function ${endpoint.callbackFunction}( $request ) {\n`;
      php += `\t// Extract parameters\n`;
      endpoint.parameters.forEach(param => {
        php += `\t$${param.key} = $request->get_param( '${param.key}' );\n`;
      });
      php += `\n\t// Business Logic Here\n`;
      if (endpoint.hookName) {
        php += `\tdo_action( '${endpoint.hookName}', $request );\n`;
      }
      php += `\n\treturn new WP_REST_Response( array( 'success' => true, 'message' => 'Logic for ${endpoint.callbackFunction} not implemented yet.' ), 200 );\n`;
      php += `}\n\n`;
    });
  }

  return php;
};

export const generateOpenAPI = (project: ProjectState): string => {
  const paths: any = {};
  const schemas: any = {};

  // 1. CPT Paths
  project.postTypes.forEach((cpt) => {
    if (!cpt.showInRest) return;

    // Define Schema
    const properties: any = {
      id: { type: 'integer', readOnly: true },
      date: { type: 'string', format: 'date-time' },
      status: { type: 'string' },
      type: { type: 'string' },
      link: { type: 'string', format: 'uri', readOnly: true },
      title: { 
        type: 'object', 
        properties: { rendered: { type: 'string' } } 
      },
    };

    if (cpt.supports.includes('editor')) {
      properties.content = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    if (cpt.supports.includes('excerpt')) {
      properties.excerpt = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    // Custom Fields
    cpt.metaFields.forEach(field => {
      if (field.showInRest) {
        properties[field.key] = {
          type: field.type,
          description: field.description
        };
      }
    });

    // Associated Taxonomies
    cpt.taxonomies.forEach(taxSlug => {
       properties[taxSlug] = {
         type: 'array',
         items: { type: 'integer' },
         description: `IDs of ${taxSlug} terms assigned to the post.`
       };
    });

    schemas[cpt.singularName] = {
      type: 'object',
      properties: properties
    };

    // Define Paths
    const pathBase = `/wp/v2/${cpt.restBase}`;

    // Collection Endpoint
    paths[pathBase] = {
      get: {
        summary: `Retrieve a list of ${cpt.pluralName}`,
        tags: [cpt.pluralName],
        responses: {
          '200': {
            description: `List of ${cpt.pluralName}`,
            content: {
              'application/json': {
                schema: {
                  type: 'array',
                  items: { $ref: `#/components/schemas/${cpt.singularName}` }
                }
              }
            }
          }
        }
      },
      post: {
        summary: `Create a new ${cpt.singularName}`,
        tags: [cpt.pluralName],
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: { $ref: `#/components/schemas/${cpt.singularName}` }
            }
          }
        },
        responses: {
          '201': {
            description: `${cpt.singularName} created`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      }
    };

    // Single Endpoint
    paths[`${pathBase}/{id}`] = {
      get: {
        summary: `Retrieve a single ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
            description: `A single ${cpt.singularName}`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
      post: {
        summary: `Update a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        requestBody: {
           content: {
             'application/json': {
               schema: { $ref: `#/components/schemas/${cpt.singularName}` }
             }
           }
        },
        responses: {
          '200': {
            description: `${cpt.singularName} updated`,
             content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
       delete: {
        summary: `Delete a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
             description: `${cpt.singularName} deleted`,
          }
        }
      }
    };
  });

  // 2. Custom Endpoint Paths
  project.customEndpoints.forEach(endpoint => {
    const route = `/${project.namespace}${endpoint.route.startsWith('/') ? endpoint.route : '/' + endpoint.route}`;

    // Initialize path if not exists
    if (!paths[route]) {
      paths[route] = {};
    }

    const parameters = endpoint.parameters.map(p => ({
      name: p.key,
      in: endpoint.method === 'GET' ? 'query' : 'body', // Simplified
      required: p.required,
      description: p.description,
      schema: { type: p.type }
    }));

    paths[route][endpoint.method.toLowerCase()] = {
      summary: endpoint.description || `Custom endpoint for ${endpoint.route}`,
      tags: ['Custom Endpoints'],
      parameters: endpoint.method === 'GET' ? parameters : [],
      requestBody: endpoint.method !== 'GET' && parameters.length > 0 ? {
        content: {
          'application/json': {
            schema: {
              type: 'object',
              properties: endpoint.parameters.reduce((acc: any, p) => {
                acc[p.key] = { type: p.type, description: p.description };
                return acc;
              }, {})
            }
          }
        }
      } : undefined,
      responses: {
        '200': {
          description: 'Successful response',
          content: {
            'application/json': {
              schema: { type: 'object' }
            }
          }
        }
      }
    };
  });

  const spec = {
    openapi: '3.0.0',
    info: {
      title: project.name,
      version: '1.0.0',
      description: `Generated REST API for ${project.name}`
    },
    paths: paths,
    components: {
      schemas: schemas
    }
  };

  return JSON.stringify(spec, null, 2);
};

import React from 'react';
