import React, { useState, useEffect } from 'react';
import { ProjectState, ViewMode, CustomPostType, CustomEndpoint, ResourceType } from './types';
import { INITIAL_PROJECT_STATE } from './constants';
import { ResourceEditor } from './components/ResourceEditor';
import { EndpointEditor } from './components/EndpointEditor';
import { CodePreview } from './components/CodePreview';
import { StatsChart } from './components/StatsChart';
import { AIAssistant } from './components/AIAssistant';
import { 
  Box, 
  Code, 
  LayoutTemplate, 
  Sparkles, 
  PieChart as ChartIcon, 
  Plus, 
  FileJson,
  Network
} from 'lucide-react';

interface SelectionState {
  type: ResourceType;
  id: string;
}

const App = () => {
  const [project, setProject] = useState<ProjectState>(INITIAL_PROJECT_STATE);
  const [currentView, setCurrentView] = useState<ViewMode>('editor');
  const [selection, setSelection] = useState<SelectionState>({ type: 'postType', id: project.postTypes[0].id });
  const [isAIModalOpen, setAIModalOpen] = useState(false);

  // Auto-select if current selection deleted
  useEffect(() => {
    if (selection.type === 'postType') {
      const exists = project.postTypes.find(pt => pt.id === selection.id);
      if (!exists) {
        if (project.postTypes.length > 0) {
          setSelection({ type: 'postType', id: project.postTypes[0].id });
        } else if (project.customEndpoints.length > 0) {
           setSelection({ type: 'endpoint', id: project.customEndpoints[0].id });
        }
      }
    } else {
       const exists = project.customEndpoints.find(ep => ep.id === selection.id);
       if (!exists) {
         if (project.customEndpoints.length > 0) {
           setSelection({ type: 'endpoint', id: project.customEndpoints[0].id });
         } else if (project.postTypes.length > 0) {
            setSelection({ type: 'postType', id: project.postTypes[0].id });
         }
       }
    }
  }, [project.postTypes, project.customEndpoints, selection]);

  const handleUpdateResource = (updatedCpt: CustomPostType) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.map(pt => pt.id === updatedCpt.id ? updatedCpt : pt)
    }));
  };

  const handleUpdateEndpoint = (updatedEndpoint: CustomEndpoint) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.map(ep => ep.id === updatedEndpoint.id ? updatedEndpoint : ep)
    }));
  };

  const handleAddResource = () => {
    const newId = `cpt_${Date.now()}`;
    const newCpt: CustomPostType = {
      id: newId,
      slug: 'new_type',
      singularName: 'New Type',
      pluralName: 'New Types',
      description: '',
      icon: 'admin-post',
      supports: ['title', 'editor'],
      taxonomies: [],
      metaFields: [],
      showInRest: true,
      restBase: 'new_types'
    };
    setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, newCpt] }));
    setSelection({ type: 'postType', id: newId });
    setCurrentView('editor');
  };

  const handleAddEndpoint = () => {
    const newId = `endpoint_${Date.now()}`;
    const newEndpoint: CustomEndpoint = {
       id: newId,
       route: '/new-route',
       method: 'GET',
       callbackFunction: 'my_callback_function',
       description: 'New custom endpoint',
       parameters: []
    };
    setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, newEndpoint] }));
    setSelection({ type: 'endpoint', id: newId });
    setCurrentView('editor');
  };

  const handleDeleteResource = (id: string) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.filter(pt => pt.id !== id)
    }));
  };

  const handleDeleteEndpoint = (id: string) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.filter(ep => ep.id !== id)
    }));
  };

  const handleAIApply = (partial: Partial<ProjectState>) => {
    setProject(prev => ({
      ...prev,
      postTypes: [...prev.postTypes, ...(partial.postTypes || [])],
      taxonomies: [...prev.taxonomies, ...(partial.taxonomies || [])],
      customEndpoints: [...prev.customEndpoints, ...(partial.customEndpoints || [])]
    }));
  };

  const selectedCpt = selection.type === 'postType' ? project.postTypes.find(pt => pt.id === selection.id) : null;
  const selectedEndpoint = selection.type === 'endpoint' ? project.customEndpoints.find(ep => ep.id === selection.id) : null;

  return (
    <div className="flex h-screen bg-slate-900 text-slate-100 overflow-hidden font-sans">

      {/* Sidebar */}
      <div className="w-64 bg-slate-950 flex flex-col border-r border-slate-800">
        <div className="p-4 border-b border-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center">
            <LayoutTemplate size={18} className="text-white"/>
          </div>
          <span className="font-bold text-lg tracking-tight">WP Architect</span>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-4 mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">Content Resources</div>
          <div className="space-y-1 px-2 mb-6">
            {project.postTypes.map(pt => (
              <button
                key={pt.id}
                onClick={() => {
                  setSelection({ type: 'postType', id: pt.id });
                  setCurrentView('editor');
                }}
                className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${selection.id === pt.id && selection.type === 'postType' && currentView === 'editor' ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
              >
                <Box size={16} />
                {pt.pluralName}
              </button>
            ))}
            <button 
              onClick={handleAddResource}
              className="w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 text-slate-500 hover:text-indigo-400 hover:bg-slate-900 transition-colors border border-dashed border-slate-800 hover:border-indigo-500/50 mt-2"
            >
              <Plus size={16} /> Add Resource
            </button>
          </div>

          <div className="px-4 mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">API Routes</div>
           <div className="space-y-1 px-2 mb-6">
            {project.customEndpoints.map(ep => (
              <button
                key={ep.id}
                onClick={() => {
                  setSelection({ type: 'endpoint', id: ep.id });
                  setCurrentView('editor');
                }}
                className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${selection.id === ep.id && selection.type === 'endpoint' && currentView === 'editor' ? 'bg-pink-600/20 text-pink-300 border border-pink-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
              >
                <Network size={16} />
                <span className="truncate">{ep.route}</span>
              </button>
            ))}
            <button 
              onClick={handleAddEndpoint}
              className="w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 text-slate-500 hover:text-pink-400 hover:bg-slate-900 transition-colors border border-dashed border-slate-800 hover:border-pink-500/50 mt-2"
            >
              <Plus size={16} /> Add Route
            </button>
          </div>

          <div className="px-4 mt-auto mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">Project Views</div>
          <div className="space-y-1 px-2">
            <button 
              onClick={() => setCurrentView('openapi')}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentView === 'openapi' ? 'bg-blue-600/20 text-blue-300 border border-blue-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            >
              <FileJson size={16} /> OpenAPI Spec
            </button>
            <button 
              onClick={() => setCurrentView('php')}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentView === 'php' ? 'bg-purple-600/20 text-purple-300 border border-purple-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            >
              <Code size={16} /> PHP Plugin
            </button>
            <button 
              onClick={() => setCurrentView('stats')}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentView === 'stats' ? 'bg-emerald-600/20 text-emerald-300 border border-emerald-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            >
              <ChartIcon size={16} /> Analysis & Plan
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800">
          <button 
            onClick={() => setAIModalOpen(true)}
            className="w-full bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white py-2 rounded-lg shadow-lg shadow-purple-900/20 flex items-center justify-center gap-2 font-medium transition-all"
          >
            <Sparkles size={16} /> AI Architect
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0f111a]">
        {currentView === 'editor' ? (
          selection.type === 'postType' && selectedCpt ? (
            <ResourceEditor 
              cpt={selectedCpt} 
              allTaxonomies={project.taxonomies}
              onChange={handleUpdateResource}
              onDelete={() => handleDeleteResource(selectedCpt.id)}
            />
          ) : selection.type === 'endpoint' && selectedEndpoint ? (
            <EndpointEditor
              endpoint={selectedEndpoint}
              namespace={project.namespace}
              onChange={handleUpdateEndpoint}
              onDelete={() => handleDeleteEndpoint(selectedEndpoint.id)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center h-full text-slate-500">
               <div className="p-8 bg-slate-900/50 rounded-full mb-4">
                 <LayoutTemplate size={48} className="text-slate-700" />
               </div>
               <p className="text-lg font-medium mb-2">Welcome to WP API Architect</p>
               <p className="text-sm">Select a resource or route from the sidebar to begin.</p>
            </div>
          )
        ) : currentView === 'openapi' ? (
           <CodePreview project={project} initialTab="openapi" />
        ) : currentView === 'php' ? (
           <CodePreview project={project} initialTab="php" />
        ) : currentView === 'stats' ? (
           <StatsChart project={project} />
        ) : null}
      </div>

      {isAIModalOpen && (
        <AIAssistant 
          project={project} 
          onApply={handleAIApply} 
          onClose={() => setAIModalOpen(false)} 
        />
      )}
    </div>
  );
};

export default App;

export enum FieldType {
  STRING = 'string',
  INTEGER = 'integer',
  NUMBER = 'number',
  BOOLEAN = 'boolean',
  ARRAY = 'array',
}

export interface MetaField {
  id: string;
  key: string;
  label: string;
  type: FieldType;
  description: string;
  required: boolean;
  showInRest: boolean;
}

export interface Taxonomy {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  hierarchical: boolean;
  showInRest: boolean;
  connectedPostTypes: string[]; // CPT slugs
}

export interface CustomPostType {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  description: string;
  icon: string; // Dashicon class or similar
  supports: string[]; // title, editor, thumbnail, etc.
  taxonomies: string[]; // Slugs of connected taxonomies
  metaFields: MetaField[];
  showInRest: boolean;
  restBase: string;
}

export type EndpointMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';

export interface EndpointParameter {
  id: string;
  key: string;
  required: boolean;
  type: string;
  description: string;
}

export interface StorageMapping {
  enabled: boolean;
  targetCptSlug: string;
  // Maps param.key -> metaField.key
  fieldMapping: Record<string, string>;
}

export interface CustomEndpoint {
  id: string;
  route: string; // e.g., /checkout/process
  method: EndpointMethod;
  callbackFunction: string;
  description: string;
  parameters: EndpointParameter[];
  hookName?: string; // Optional custom action to fire
  storage?: StorageMapping;
}

export interface ProjectState {
  name: string;
  namespace: string;
  postTypes: CustomPostType[];
  taxonomies: Taxonomy[];
  customEndpoints: CustomEndpoint[];
}

export type ViewMode = 'editor' | 'openapi' | 'php' | 'flow';
export type ResourceType = 'postType' | 'endpoint';

import React from 'react';
import { CustomEndpoint, EndpointMethod, EndpointParameter, CustomPostType } from '../types';
import { Trash2, Settings, Plus, Network, Database, ArrowRight } from 'lucide-react';

interface EndpointEditorProps {
  endpoint: CustomEndpoint;
  namespace: string;
  postTypes: CustomPostType[];
  onChange: (updated: CustomEndpoint) => void;
  onDelete: () => void;
}

export const EndpointEditor: React.FC<EndpointEditorProps> = ({ endpoint, namespace, postTypes, onChange, onDelete }) => {

  const handleParamChange = (id: string, changes: Partial<EndpointParameter>) => {
    const updatedParams = endpoint.parameters.map(p => p.id === id ? { ...p, ...changes } : p);
    onChange({ ...endpoint, parameters: updatedParams });
  };

  const addParam = () => {
    const newParam: EndpointParameter = {
      id: `param_${Date.now()}`,
      key: 'new_param',
      type: 'string',
      required: false,
      description: ''
    };
    onChange({ ...endpoint, parameters: [...endpoint.parameters, newParam] });
  };

  const removeParam = (id: string) => {
    onChange({ ...endpoint, parameters: endpoint.parameters.filter(p => p.id !== id) });
  };

  const handleStorageToggle = (enabled: boolean) => {
    onChange({
      ...endpoint,
      storage: {
        enabled,
        targetCptSlug: endpoint.storage?.targetCptSlug || (postTypes[0]?.slug || ''),
        fieldMapping: endpoint.storage?.fieldMapping || {}
      }
    });
  };

  const handleStorageTargetChange = (slug: string) => {
    onChange({
      ...endpoint,
      storage: {
        ...endpoint.storage!,
        targetCptSlug: slug,
        fieldMapping: {} // Reset mapping on target change
      }
    });
  };

  const handleMappingChange = (paramKey: string, metaKey: string) => {
    if (!endpoint.storage) return;
    const newMapping = { ...endpoint.storage.fieldMapping };
    if (metaKey === '') {
      delete newMapping[paramKey];
    } else {
      newMapping[paramKey] = metaKey;
    }
    onChange({
      ...endpoint,
      storage: {
        ...endpoint.storage,
        fieldMapping: newMapping
      }
    });
  };

  const methods: EndpointMethod[] = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'];
  const targetCpt = postTypes.find(pt => pt.slug === endpoint.storage?.targetCptSlug);

  return (
    <div className="h-full overflow-y-auto p-8 custom-scrollbar">
      <div className="flex justify-between items-start mb-8">
        <div>
          <h2 className="text-3xl font-bold text-white mb-2 flex items-center gap-2">
            <Network className="text-pink-500" size={32} />
            {endpoint.route}
          </h2>
          <p className="text-slate-400">Custom REST API Route Definition</p>
        </div>
        <button 
          onClick={onDelete}
          className="text-red-400 hover:text-red-300 hover:bg-red-900/20 px-3 py-2 rounded-lg transition-colors flex items-center gap-2"
        >
          <Trash2 size={18} />
          Delete Endpoint
        </button>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

        {/* Main Route Settings */}
        <div className="xl:col-span-2 space-y-8">

          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 space-y-6">
            <h3 className="text-lg font-semibold text-slate-200 flex items-center gap-2">
              <Settings size={20} className="text-pink-400"/> Route Configuration
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="col-span-1 md:col-span-2">
                <label className="block text-sm font-medium text-slate-400 mb-1">Route Path</label>
                <div className="flex items-center">
                  <span className="bg-slate-700 text-slate-300 px-3 py-2 rounded-l border border-r-0 border-slate-600 font-mono text-sm">
                    /{namespace}/
                  </span>
                  <input 
                    type="text" 
                    value={endpoint.route.startsWith('/') ? endpoint.route.substring(1) : endpoint.route} 
                    onChange={e => onChange({...endpoint, route: '/' + e.target.value})}
                    placeholder="my-resource/action"
                    className="flex-1 bg-slate-900 border border-slate-600 rounded-r px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 outline-none font-mono text-sm"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">HTTP Method</label>
                <div className="flex flex-wrap gap-2">
                  {methods.map(m => (
                    <button
                      key={m}
                      onClick={() => onChange({ ...endpoint, method: m })}
                      className={`px-3 py-1.5 rounded text-xs font-bold transition-all ${endpoint.method === m 
                        ? 'bg-pink-600 text-white shadow-lg shadow-pink-500/30' 
                        : 'bg-slate-700 text-slate-400 hover:bg-slate-600'}`}
                    >
                      {m}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Callback Function</label>
                <input 
                  type="text" 
                  value={endpoint.callbackFunction} 
                  onChange={e => onChange({...endpoint, callbackFunction: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 outline-none font-mono text-sm"
                />
              </div>

              <div className="col-span-1 md:col-span-2">
                <label className="block text-sm font-medium text-slate-400 mb-1">Description</label>
                <input 
                  type="text" 
                  value={endpoint.description} 
                  onChange={e => onChange({...endpoint, description: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 outline-none"
                />
              </div>
            </div>
          </div>

          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-semibold text-slate-200">Request Parameters</h3>
              <button 
                onClick={addParam}
                className="flex items-center gap-1 text-sm bg-pink-600 hover:bg-pink-700 text-white px-3 py-1.5 rounded transition-colors"
              >
                <Plus size={16} /> Add Parameter
              </button>
            </div>

            <div className="space-y-3">
              {endpoint.parameters.length === 0 && (
                 <p className="text-slate-500 text-center py-4 italic">No parameters defined.</p>
              )}
              {endpoint.parameters.map((param) => (
                <div key={param.id} className="bg-slate-900/50 rounded-lg p-4 border border-slate-700 flex gap-4 items-center">
                  <div className="grid grid-cols-12 gap-3 flex-1">
                    <div className="col-span-3">
                       <input 
                         type="text" 
                         placeholder="key"
                         value={param.key}
                         onChange={e => handleParamChange(param.id, { key: e.target.value })}
                         className="w-full bg-slate-800 border border-slate-600 rounded px-2 py-1 text-sm text-white font-mono"
                       />
                    </div>
                    <div className="col-span-2">
                       <select 
                         value={param.type}
                         onChange={e => handleParamChange(param.id, { type: e.target.value })}
                         className="w-full bg-slate-800 border border-slate-600 rounded px-2 py-1 text-sm text-white"
                       >
                         <option value="string">string</option>
                         <option value="integer">integer</option>
                         <option value="boolean">boolean</option>
                       </select>
                    </div>
                    <div className="col-span-5">
                       <input 
                         type="text" 
                         placeholder="Description"
                         value={param.description}
                         onChange={e => handleParamChange(param.id, { description: e.target.value })}
                         className="w-full bg-slate-800 border border-slate-600 rounded px-2 py-1 text-sm text-white"
                       />
                    </div>
                    <div className="col-span-2 flex items-center justify-center">
                        <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-400 select-none">
                       <input 
                         type="checkbox" 
                         checked={param.required}
                         onChange={e => handleParamChange(param.id, { required: e.target.checked })}
                         className="rounded bg-slate-700 border-slate-600 text-pink-500 focus:ring-0"
                       />
                       Required
                     </label>
                    </div>
                  </div>
                   <button 
                      onClick={() => removeParam(param.id)}
                      className="text-slate-500 hover:text-red-400 transition-colors"
                    >
                      <Trash2 size={18} />
                    </button>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Sidebar Settings */}
        <div className="space-y-6">

          {/* Action Hooks */}
          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700">
            <h3 className="text-sm font-bold text-slate-300 uppercase tracking-wider mb-4">Hooks & Actions</h3>
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1">Custom Action Hook</label>
              <input 
                type="text" 
                value={endpoint.hookName || ''} 
                onChange={e => onChange({...endpoint, hookName: e.target.value})}
                placeholder="my_custom_process_action"
                className="w-full bg-slate-900 border border-slate-600 rounded px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 outline-none font-mono text-sm"
              />
            </div>
          </div>

          {/* Logic & Storage Flow */}
          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
               <Database size={100} />
             </div>

             <div className="flex items-center justify-between mb-4">
               <h3 className="text-sm font-bold text-slate-300 uppercase tracking-wider">Storage Flow</h3>
               <label className="relative inline-flex items-center cursor-pointer">
                <input 
                  type="checkbox" 
                  className="sr-only peer" 
                  checked={endpoint.storage?.enabled || false}
                  onChange={e => handleStorageToggle(e.target.checked)}
                />
                <div className="w-9 h-5 bg-slate-600 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-pink-600"></div>
              </label>
             </div>

             {endpoint.storage?.enabled ? (
               <div className="space-y-4">
                  <div>
                    <label className="block text-xs font-medium text-slate-400 mb-1">Target Post Type</label>
                    <select
                      value={endpoint.storage.targetCptSlug}
                      onChange={e => handleStorageTargetChange(e.target.value)}
                      className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1.5 text-sm text-white"
                    >
                      {postTypes.map(pt => (
                        <option key={pt.slug} value={pt.slug}>{pt.singularName}</option>
                      ))}
                    </select>
                  </div>

                  {targetCpt && (
                    <div className="bg-slate-900/50 rounded p-3 border border-slate-700">
                      <p className="text-xs text-slate-400 mb-2 font-semibold">Map Parameters to Fields</p>
                      {endpoint.parameters.map(param => (
                        <div key={param.id} className="flex items-center justify-between gap-2 mb-2 last:mb-0">
                          <span className="text-xs font-mono text-pink-300 w-1/3 truncate" title={param.key}>{param.key}</span>
                          <ArrowRight size={12} className="text-slate-600" />
                          <select
                            value={endpoint.storage?.fieldMapping[param.key] || ''}
                            onChange={e => handleMappingChange(param.key, e.target.value)}
                            className="w-1/2 bg-slate-800 border border-slate-600 rounded px-1 py-1 text-xs text-white"
                          >
                            <option value="">(Ignore)</option>
                            <option value="post_title">Post Title</option>
                            <option value="post_content">Post Content</option>
                            {targetCpt.metaFields.map(mf => (
                              <option key={mf.key} value={mf.key}>{mf.label} ({mf.key})</option>
                            ))}
                          </select>
                        </div>
                      ))}
                    </div>
                  )}
               </div>
             ) : (
               <p className="text-xs text-slate-500">
                 Enable this to automatically save request data into a Custom Post Type.
               </p>
             )}
          </div>

        </div>

      </div>
    </div>
  );
};

import { ProjectState, CustomPostType, Taxonomy, MetaField, FieldType, CustomEndpoint } from '../types';

export const generatePackageJSON = (project: ProjectState): string => {
  const pkg = {
    "name": project.name.toLowerCase().replace(/\s+/g, '-'),
    "version": "1.0.0",
    "description": "WordPress Plugin generated by WP API Architect",
    "scripts": {
      "build": "wp-scripts build",
      "format": "wp-scripts format",
      "lint:css": "wp-scripts lint-style",
      "lint:js": "wp-scripts lint-js",
      "packages-update": "wp-scripts packages-update",
      "plugin-zip": "wp-scripts plugin-zip",
      "start": "wp-scripts start"
    },
    "devDependencies": {
      "@wordpress/scripts": "^26.0.0"
    }
  };
  return JSON.stringify(pkg, null, 2);
};

export const generateComposerJSON = (project: ProjectState): string => {
  const composer = {
    "name": `wp-architect/${project.name.toLowerCase().replace(/\s+/g, '-')}`,
    "description": "WordPress Plugin generated by WP API Architect",
    "type": "wordpress-plugin",
    "license": "GPL-2.0-or-later",
    "authors": [
      {
        "name": "WP API Architect",
        "email": "architect@example.com"
      }
    ],
    "require": {
      "php": ">=7.4"
    }
  };
  return JSON.stringify(composer, null, 2);
};

export const generatePHP = (project: ProjectState): string => {
  const { postTypes, taxonomies, customEndpoints, namespace } = project;
  const projectSlug = project.name.toLowerCase().replace(/\s+/g, '_');
  const timestamp = new Date().toISOString();

  let php = `<?php
/**
 * Plugin Name: ${project.name}
 * Description: Auto-generated by WP API Architect
 * Version: 1.0.0
 * Author: WP API Architect
 * Generated: ${timestamp}
 */

if ( ! defined( 'ABSPATH' ) ) {
\texit; // Exit if accessed directly.
}

// -------------------------------------------------------------------------
// 1. Content Definitions (CPT & Taxonomies)
// -------------------------------------------------------------------------

add_action( 'init', '${projectSlug}_register_content' );

function ${projectSlug}_register_content() {
`;

  // Register Taxonomies
  taxonomies.forEach((tax) => {
    php += `
\t// Register Taxonomy: ${tax.pluralName}
\tregister_taxonomy( '${tax.slug}', ${JSON.stringify(tax.connectedPostTypes)}, array(
\t\t'labels' => array(
\t\t\t'name' => '${tax.pluralName}',
\t\t\t'singular_name' => '${tax.singularName}',
\t\t),
\t\t'hierarchical' => ${tax.hierarchical ? 'true' : 'false'},
\t\t'show_in_rest' => ${tax.showInRest ? 'true' : 'false'},
\t) );
`;
  });

  // Register Post Types
  postTypes.forEach((cpt) => {
    php += `
\t// Register Custom Post Type: ${cpt.pluralName}
\tregister_post_type( '${cpt.slug}', array(
\t\t'labels' => array(
\t\t\t'name' => '${cpt.pluralName}',
\t\t\t'singular_name' => '${cpt.singularName}',
\t\t),
\t\t'public' => true,
\t\t'has_archive' => true,
\t\t'menu_icon' => 'dashicons-${cpt.icon}',
\t\t'supports' => array( ${cpt.supports.map((s) => `'${s}'`).join(', ')} ),
\t\t'show_in_rest' => ${cpt.showInRest ? 'true' : 'false'},
\t\t'rest_base' => '${cpt.restBase}',
\t) );
`;
  });

  php += `}\n\n`;

  // Register Meta Fields
  if (postTypes.some(pt => pt.metaFields.length > 0)) {
    php += `add_action( 'init', '${projectSlug}_register_meta' );\n`;
    php += `function ${projectSlug}_register_meta() {\n`;

    postTypes.forEach((cpt) => {
      cpt.metaFields.forEach((field) => {
        if (field.showInRest) {
          php += `
\tregister_post_meta( '${cpt.slug}', '${field.key}', array(
\t\t'show_in_rest' => array(
\t\t\t'schema' => array(
\t\t\t\t'type' => '${field.type}',
\t\t\t\t'description' => '${field.description.replace(/'/g, "\\'")}',
\t\t\t),
\t\t),
\t\t'single' => true,
\t\t'type' => '${field.type === FieldType.INTEGER ? 'integer' : field.type === FieldType.NUMBER ? 'number' : 'string'}',
\t) );
`;
        }
      });
    });

    php += `}\n\n`;
  }

  // -------------------------------------------------------------------------
  // 2. Custom REST Endpoints
  // -------------------------------------------------------------------------

  if (customEndpoints.length > 0) {
    php += `add_action( 'rest_api_init', '${projectSlug}_register_routes' );\n\n`;
    php += `function ${projectSlug}_register_routes() {\n`;

    customEndpoints.forEach(endpoint => {
      const cleanRoute = endpoint.route.startsWith('/') ? endpoint.route : '/' + endpoint.route;

      php += `
\tregister_rest_route( '${namespace}', '${cleanRoute}', array(
\t\t'methods' => '${endpoint.method}',
\t\t'callback' => '${endpoint.callbackFunction}',
\t\t'permission_callback' => '__return_true', // @TODO: Update security logic
\t\t'args' => array(
${endpoint.parameters.map(param => `\t\t\t'${param.key}' => array(
\t\t\t\t'required' => ${param.required ? 'true' : 'false'},
\t\t\t\t'type' => '${param.type}',
\t\t\t\t'description' => '${param.description.replace(/'/g, "\\'")}',
\t\t\t),`).join('\n')}
\t\t),
\t) );
`;
    });

    php += `}\n\n`;

    // Generate Callback Implementation
    customEndpoints.forEach(endpoint => {
      php += `/**\n * Callback for ${endpoint.method} ${endpoint.route}\n */\n`;
      php += `function ${endpoint.callbackFunction}( $request ) {\n`;
      php += `\t// Extract parameters\n`;
      endpoint.parameters.forEach(param => {
        php += `\t$${param.key} = $request->get_param( '${param.key}' );\n`;
      });

      // Storage Logic Generation
      if (endpoint.storage?.enabled && endpoint.method !== 'GET') {
        php += `\n\t// Auto-Generated Storage Logic\n`;
        php += `\t$post_data = array(\n`;
        php += `\t\t'post_type'   => '${endpoint.storage.targetCptSlug}',\n`;
        php += `\t\t'post_status' => 'publish',\n`;

        // Map native WP fields
        Object.entries(endpoint.storage.fieldMapping).forEach(([paramKey, metaKey]) => {
           if (metaKey === 'post_title') {
             php += `\t\t'post_title'  => $${paramKey},\n`;
           }
           if (metaKey === 'post_content') {
             php += `\t\t'post_content'  => $${paramKey},\n`;
           }
        });
        php += `\t);\n\n`;
        php += `\t$post_id = wp_insert_post( $post_data );\n\n`;

        php += `\tif ( ! is_wp_error( $post_id ) ) {\n`;
        // Map Meta fields
        Object.entries(endpoint.storage.fieldMapping).forEach(([paramKey, metaKey]) => {
           if (metaKey !== 'post_title' && metaKey !== 'post_content') {
             php += `\t\tupdate_post_meta( $post_id, '${metaKey}', $${paramKey} );\n`;
           }
        });
        php += `\t}\n`;
      }

      php += `\n\t// Custom Actions\n`;
      if (endpoint.hookName) {
        // Pass post_id if available, otherwise just request
        const actionArgs = endpoint.storage?.enabled ? `array( 'request' => $request, 'post_id' => $post_id )` : `$request`;
        php += `\tdo_action( '${endpoint.hookName}', ${actionArgs} );\n`;
      }

      php += `\n\treturn new WP_REST_Response( array(\n\t\t'success' => true,\n\t\t'message' => 'Processed ${endpoint.route}',\n`;
      if (endpoint.storage?.enabled) {
         php += `\t\t'created_id' => $post_id\n`;
      }
      php += `\t), 200 );\n`;
      php += `}\n\n`;
    });
  }

  return php;
};

export const generateOpenAPI = (project: ProjectState): string => {
  const paths: any = {};
  const schemas: any = {};

  // 1. CPT Paths
  project.postTypes.forEach((cpt) => {
    if (!cpt.showInRest) return;

    // Define Schema
    const properties: any = {
      id: { type: 'integer', readOnly: true },
      date: { type: 'string', format: 'date-time' },
      status: { type: 'string' },
      type: { type: 'string' },
      link: { type: 'string', format: 'uri', readOnly: true },
      title: { 
        type: 'object', 
        properties: { rendered: { type: 'string' } } 
      },
    };

    if (cpt.supports.includes('editor')) {
      properties.content = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    if (cpt.supports.includes('excerpt')) {
      properties.excerpt = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    // Custom Fields
    cpt.metaFields.forEach(field => {
      if (field.showInRest) {
        properties[field.key] = {
          type: field.type,
          description: field.description
        };
      }
    });

    // Associated Taxonomies
    cpt.taxonomies.forEach(taxSlug => {
       properties[taxSlug] = {
         type: 'array',
         items: { type: 'integer' },
         description: `IDs of ${taxSlug} terms assigned to the post.`
       };
    });

    schemas[cpt.singularName] = {
      type: 'object',
      properties: properties
    };

    // Define Paths
    const pathBase = `/wp/v2/${cpt.restBase}`;

    // Collection Endpoint
    paths[pathBase] = {
      get: {
        summary: `Retrieve a list of ${cpt.pluralName}`,
        tags: [cpt.pluralName],
        responses: {
          '200': {
            description: `List of ${cpt.pluralName}`,
            content: {
              'application/json': {
                schema: {
                  type: 'array',
                  items: { $ref: `#/components/schemas/${cpt.singularName}` }
                }
              }
            }
          }
        }
      },
      post: {
        summary: `Create a new ${cpt.singularName}`,
        tags: [cpt.pluralName],
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: { $ref: `#/components/schemas/${cpt.singularName}` }
            }
          }
        },
        responses: {
          '201': {
            description: `${cpt.singularName} created`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      }
    };

    // Single Endpoint
    paths[`${pathBase}/{id}`] = {
      get: {
        summary: `Retrieve a single ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
            description: `A single ${cpt.singularName}`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
      post: {
        summary: `Update a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        requestBody: {
           content: {
             'application/json': {
               schema: { $ref: `#/components/schemas/${cpt.singularName}` }
             }
           }
        },
        responses: {
          '200': {
            description: `${cpt.singularName} updated`,
             content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
       delete: {
        summary: `Delete a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
             description: `${cpt.singularName} deleted`,
          }
        }
      }
    };
  });

  // 2. Custom Endpoint Paths
  project.customEndpoints.forEach(endpoint => {
    const route = `/${project.namespace}${endpoint.route.startsWith('/') ? endpoint.route : '/' + endpoint.route}`;

    // Initialize path if not exists
    if (!paths[route]) {
      paths[route] = {};
    }

    const parameters = endpoint.parameters.map(p => ({
      name: p.key,
      in: endpoint.method === 'GET' ? 'query' : 'body', // Simplified
      required: p.required,
      description: p.description,
      schema: { type: p.type }
    }));

    paths[route][endpoint.method.toLowerCase()] = {
      summary: endpoint.description || `Custom endpoint for ${endpoint.route}`,
      tags: ['Custom Endpoints'],
      parameters: endpoint.method === 'GET' ? parameters : [],
      requestBody: endpoint.method !== 'GET' && parameters.length > 0 ? {
        content: {
          'application/json': {
            schema: {
              type: 'object',
              properties: endpoint.parameters.reduce((acc: any, p) => {
                acc[p.key] = { type: p.type, description: p.description };
                return acc;
              }, {})
            }
          }
        }
      } : undefined,
      responses: {
        '200': {
          description: 'Successful response',
          content: {
            'application/json': {
              schema: { type: 'object' }
            }
          }
        }
      }
    };
  });

  const spec = {
    openapi: '3.0.0',
    info: {
      title: project.name,
      version: '1.0.0',
      description: `Generated REST API for ${project.name}`
    },
    paths: paths,
    components: {
      schemas: schemas
    }
  };

  return JSON.stringify(spec, null, 2);
};

import React, { useState } from 'react';
import { ProjectState } from '../types';
import { generateOpenAPI, generatePHP, generatePackageJSON, generateComposerJSON } from '../services/wpGenerator';
import { Copy, Check, FileCode, FileJson, Package } from 'lucide-react';

interface CodePreviewProps {
  project: ProjectState;
  initialTab?: 'openapi' | 'php' | 'pkg' | 'composer';
}

export const CodePreview: React.FC<CodePreviewProps> = ({ project, initialTab = 'openapi' }) => {
  const [tab, setTab] = useState<'openapi' | 'php' | 'pkg' | 'composer'>(initialTab);
  const [copied, setCopied] = useState(false);

  let content = "";
  switch(tab) {
    case 'openapi': content = generateOpenAPI(project); break;
    case 'php': content = generatePHP(project); break;
    case 'pkg': content = generatePackageJSON(project); break;
    case 'composer': content = generateComposerJSON(project); break;
  }

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const tabs = [
    { id: 'openapi', label: 'openapi.json', icon: FileJson, color: 'text-blue-400', activeBg: 'bg-blue-500/10 border-blue-500/30' },
    { id: 'php', label: 'plugin.php', icon: FileCode, color: 'text-purple-400', activeBg: 'bg-purple-500/10 border-purple-500/30' },
    { id: 'pkg', label: 'package.json', icon: Package, color: 'text-green-400', activeBg: 'bg-green-500/10 border-green-500/30' },
    { id: 'composer', label: 'composer.json', icon: Package, color: 'text-yellow-400', activeBg: 'bg-yellow-500/10 border-yellow-500/30' },
  ];

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e]">
      <div className="flex items-center justify-between px-4 py-2 bg-[#252526] border-b border-[#333]">
        <div className="flex gap-1 overflow-x-auto">
          {tabs.map(t => (
            <button
              key={t.id}
              onClick={() => setTab(t.id as any)}
              className={`flex items-center gap-2 px-4 py-2 text-xs font-medium rounded-t-lg transition-all border border-transparent ${
                tab === t.id 
                ? `${t.activeBg} ${t.color}` 
                : 'text-slate-400 hover:bg-[#333] hover:text-slate-200'
              }`}
            >
              <t.icon size={14} />
              {t.label}
            </button>
          ))}
        </div>
        <button 
          onClick={handleCopy}
          className="flex items-center gap-2 text-xs text-slate-400 hover:text-white px-3 py-1.5 rounded bg-[#333] hover:bg-[#444] transition-colors"
        >
          {copied ? <Check size={14} className="text-green-500"/> : <Copy size={14} />}
          {copied ? 'Copied' : 'Copy'}
        </button>
      </div>
      <div className="flex-1 overflow-auto p-4 custom-scrollbar">
        <pre className="font-mono text-sm leading-relaxed text-[#d4d4d4]">
          <code>{content}</code>
        </pre>
      </div>
    </div>
  );
};

