export const generatePHP = (project: ProjectState): string => {
  const { postTypes, taxonomies, customEndpoints, namespace } = project;
  const projectSlug = project.name.toLowerCase().replace(/\s+/g, '_');
  const timestamp = new Date().toISOString();

  let php = `<?php
/**
 * Plugin Name: ${project.name}
 * Description: Auto-generated by WP API Architect
 * Version: 1.0.0
 * Author: WP API Architect
 * Generated: ${timestamp}
 */

if ( ! defined( 'ABSPATH' ) ) {
\texit; // Exit if accessed directly.
}

// -------------------------------------------------------------------------
// 1. Content Definitions (CPT & Taxonomies)
// -------------------------------------------------------------------------

add_action( 'init', '${projectSlug}_register_content' );

function ${projectSlug}_register_content() {
`;

  // Register Taxonomies
  taxonomies.forEach((tax) => {
    php += `
\t// Register Taxonomy: ${tax.pluralName}
\tregister_taxonomy( '${tax.slug}', ${JSON.stringify(tax.connectedPostTypes)}, array(
\t\t'labels' => array(
\t\t\t'name' => '${tax.pluralName}',
\t\t\t'singular_name' => '${tax.singularName}',
\t\t),
\t\t'hierarchical' => ${tax.hierarchical ? 'true' : 'false'},
\t\t'show_in_rest' => ${tax.showInRest ? 'true' : 'false'},
\t) );
`;
  });

  // Register Post Types
  postTypes.forEach((cpt) => {
    php += `
\t// Register Custom Post Type: ${cpt.pluralName}
\tregister_post_type( '${cpt.slug}', array(
\t\t'labels' => array(
\t\t\t'name' => '${cpt.pluralName}',
\t\t\t'singular_name' => '${cpt.singularName}',
\t\t),
\t\t'public' => true,
\t\t'has_archive' => true,
\t\t'menu_icon' => 'dashicons-${cpt.icon}',
\t\t'supports' => array( ${cpt.supports.map((s) => `'${s}'`).join(', ')} ),
\t\t'show_in_rest' => ${cpt.showInRest ? 'true' : 'false'},
\t\t'rest_base' => '${cpt.restBase}',
\t) );
`;
  });

  php += `}\n\n`;

  // Register Meta Fields
  if (postTypes.some(pt => pt.metaFields.length > 0)) {
    php += `add_action( 'init', '${projectSlug}_register_meta' );\n`;
    php += `function ${projectSlug}_register_meta() {\n`;

    postTypes.forEach((cpt) => {
      cpt.metaFields.forEach((field) => {
        if (field.showInRest) {
          php += `
\tregister_post_meta( '${cpt.slug}', '${field.key}', array(
\t\t'show_in_rest' => array(
\t\t\t'schema' => array(
\t\t\t\t'type' => '${field.type}',
\t\t\t\t'description' => '${field.description.replace(/'/g, "\\'")}',
\t\t\t),
\t\t),
\t\t'single' => true,
\t\t'type' => '${field.type === FieldType.INTEGER ? 'integer' : field.type === FieldType.NUMBER ? 'number' : 'string'}',
\t) );
`;
        }
      });
    });

    php += `}\n\n`;
  }

  // -------------------------------------------------------------------------
  // 2. Custom REST Endpoints
  // -------------------------------------------------------------------------

  if (customEndpoints.length > 0) {
    php += `add_action( 'rest_api_init', '${projectSlug}_register_routes' );\n\n`;
    php += `function ${projectSlug}_register_routes() {\n`;

    customEndpoints.forEach(endpoint => {
      const cleanRoute = endpoint.route.startsWith('/') ? endpoint.route : '/' + endpoint.route;

      php += `
\tregister_rest_route( '${namespace}', '${cleanRoute}', array(
\t\t'methods' => '${endpoint.method}',
\t\t'callback' => '${endpoint.callbackFunction}',
\t\t'permission_callback' => '__return_true', // @TODO: Update security logic
\t\t'args' => array(
${endpoint.parameters.map(param => `\t\t\t'${param.key}' => array(
\t\t\t\t'required' => ${param.required ? 'true' : 'false'},
\t\t\t\t'type' => '${param.type}',
\t\t\t\t'description' => '${param.description.replace(/'/g, "\\'")}',
\t\t\t),`).join('\n')}
\t\t),
\t) );
`;
    });

    php += `}\n\n`;

    // Generate Callback Implementation
    customEndpoints.forEach(endpoint => {
      php += `/**\n * Callback for ${endpoint.method} ${endpoint.route}\n */\n`;
      php += `function ${endpoint.callbackFunction}( $request ) {\n`;
      php += `\t// Extract parameters\n`;
      endpoint.parameters.forEach(param => {
        php += `\t$${param.key} = $request->get_param( '${param.key}' );\n`;
      });

      // Storage Logic Generation
      if (endpoint.storage?.enabled && endpoint.method !== 'GET') {
        php += `\n\t// Auto-Generated Storage Logic\n`;
        php += `\t$post_data = array(\n`;
        php += `\t\t'post_type'   => '${endpoint.storage.targetCptSlug}',\n`;
        php += `\t\t'post_status' => 'publish',\n`;

        // Map native WP fields
        Object.entries(endpoint.storage.fieldMapping).forEach(([paramKey, metaKey]) => {
           if (metaKey === 'post_title') {
             php += `\t\t'post_title'  => $${paramKey},\n`;
           }
           if (metaKey === 'post_content') {
             php += `\t\t'post_content'  => $${paramKey},\n`;
           }
        });
        php += `\t);\n\n`;
        php += `\t$post_id = wp_insert_post( $post_data );\n\n`;

        php += `\tif ( ! is_wp_error( $post_id ) ) {\n`;
        // Map Meta fields
        Object.entries(endpoint.storage.fieldMapping).forEach(([paramKey, metaKey]) => {
           if (metaKey !== 'post_title' && metaKey !== 'post_content') {
             php += `\t\tupdate_post_meta( $post_id, '${metaKey}', $${paramKey} );\n`;
           }
        });
        php += `\t}\n`;
      }

      php += `\n\t// Custom Actions\n`;
      if (endpoint.hookName) {
        // Pass post_id if available, otherwise just request
        const actionArgs = endpoint.storage?.enabled ? `array( 'request' => $request, 'post_id' => $post_id )` : `$request`;
        php += `\tdo_action( '${endpoint.hookName}', ${actionArgs} );\n`;
      }

      php += `\n\treturn new WP_REST_Response( array(\n\t\t'success' => true,\n\t\t'message' => 'Processed ${endpoint.route}',\n`;
      if (endpoint.storage?.enabled) {
         php += `\t\t'created_id' => $post_id\n`;
      }
      php += `\t), 200 );\n`;
      php += `}\n\n`;
    });
  }

  return php;
};

export const generatePlaygroundBlueprint = (project: ProjectState): string => {
  const phpCode = generatePHP(project);

  // Escape the PHP code for JSON inclusion
  // We use a simplified method to inject the plugin logic into a mu-plugin
  const blueprint = {
    "landingPage": "/wp-admin/plugins.php",
    "steps": [
      {
        "step": "login",
        "username": "admin",
        "password": "password"
      },
      {
        "step": "writeFile",
        "path": `/wordpress/wp-content/plugins/${project.name.toLowerCase().replace(/\s+/g, '-')}/index.php`,
        "data": phpCode
      },
      {
        "step": "activatePlugin",
        "pluginName": project.name.toLowerCase().replace(/\s+/g, '-'),
        "pluginPath": `${project.name.toLowerCase().replace(/\s+/g, '-')}/index.php`
      }
    ]
  };

  return JSON.stringify(blueprint, null, 2);
};

export const generateOpenAPI = (project: ProjectState): string => {
  const paths: any = {};
  const schemas: any = {};

  // 1. CPT Paths
  project.postTypes.forEach((cpt) => {
    if (!cpt.showInRest) return;

    // Define Schema
    const properties: any = {
      id: { type: 'integer', readOnly: true },
      date: { type: 'string', format: 'date-time' },
      status: { type: 'string' },
      type: { type: 'string' },
      link: { type: 'string', format: 'uri', readOnly: true },
      title: { 
        type: 'object', 
        properties: { rendered: { type: 'string' } } 
      },
    };

    if (cpt.supports.includes('editor')) {
      properties.content = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    if (cpt.supports.includes('excerpt')) {
      properties.excerpt = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    // Custom Fields
    cpt.metaFields.forEach(field => {
      if (field.showInRest) {
        properties[field.key] = {
          type: field.type,
          description: field.description
        };
      }
    });

    // Associated Taxonomies
    cpt.taxonomies.forEach(taxSlug => {
       properties[taxSlug] = {
         type: 'array',
         items: { type: 'integer' },
         description: `IDs of ${taxSlug} terms assigned to the post.`
       };
    });

    schemas[cpt.singularName] = {
      type: 'object',
      properties: properties
    };

    // Define Paths
    const pathBase = `/wp/v2/${cpt.restBase}`;

    // Collection Endpoint
    paths[pathBase] = {
      get: {
        summary: `Retrieve a list of ${cpt.pluralName}`,
        tags: [cpt.pluralName],
        responses: {
          '200': {
            description: `List of ${cpt.pluralName}`,
            content: {
              'application/json': {
                schema: {
                  type: 'array',
                  items: { $ref: `#/components/schemas/${cpt.singularName}` }
                }
              }
            }
          }
        }
      },
      post: {
        summary: `Create a new ${cpt.singularName}`,
        tags: [cpt.pluralName],
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: { $ref: `#/components/schemas/${cpt.singularName}` }
            }
          }
        },
        responses: {
          '201': {
            description: `${cpt.singularName} created`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      }
    };

    // Single Endpoint
    paths[`${pathBase}/{id}`] = {
      get: {
        summary: `Retrieve a single ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
            description: `A single ${cpt.singularName}`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
      post: {
        summary: `Update a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        requestBody: {
           content: {
             'application/json': {
               schema: { $ref: `#/components/schemas/${cpt.singularName}` }
             }
           }
        },
        responses: {
          '200': {
            description: `${cpt.singularName} updated`,
             content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
       delete: {
        summary: `Delete a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
             description: `${cpt.singularName} deleted`,
          }
        }
      }
    };
  });

  // 2. Custom Endpoint Paths
  project.customEndpoints.forEach(endpoint => {
    const route = `/${project.namespace}${endpoint.route.startsWith('/') ? endpoint.route : '/' + endpoint.route}`;

    // Initialize path if not exists
    if (!paths[route]) {
      paths[route] = {};
    }

    const parameters = endpoint.parameters.map(p => ({
      name: p.key,
      in: endpoint.method === 'GET' ? 'query' : 'body', // Simplified
      required: p.required,
      description: p.description,
      schema: { type: p.type }
    }));

    paths[route][endpoint.method.toLowerCase()] = {
      summary: endpoint.description || `Custom endpoint for ${endpoint.route}`,
      tags: ['Custom Endpoints'],
      parameters: endpoint.method === 'GET' ? parameters : [],
      requestBody: endpoint.method !== 'GET' && parameters.length > 0 ? {
        content: {
          'application/json': {
            schema: {
              type: 'object',
              properties: endpoint.parameters.reduce((acc: any, p) => {
                acc[p.key] = { type: p.type, description: p.description };
                return acc;
              }, {})
            }
          }
        }
      } : undefined,
      responses: {
        '200': {
          description: 'Successful response',
          content: {
            'application/json': {
              schema: { type: 'object' }
            }
          }
        }
      }
    };
  });

  const spec = {
    openapi: '3.0.0',
    info: {
      title: project.name,
      version: '1.0.0',
      description: `Generated REST API for ${project.name}`
    },
    paths: paths,
    components: {
      schemas: schemas
    }
  };

  return JSON.stringify(spec, null, 2);
};

import React, { useState } from 'react';
import { ProjectState } from '../types';
import { generateOpenAPI, generatePHP, generatePackageJSON, generateComposerJSON, generatePlaygroundBlueprint } from '../services/wpGenerator';
import { Copy, Check, FileCode, FileJson, Package, PlayCircle } from 'lucide-react';

interface CodePreviewProps {
  project: ProjectState;
  initialTab?: 'openapi' | 'php' | 'pkg' | 'composer' | 'blueprint';
}

export const CodePreview: React.FC<CodePreviewProps> = ({ project, initialTab = 'openapi' }) => {
  const [tab, setTab] = useState<'openapi' | 'php' | 'pkg' | 'composer' | 'blueprint'>(initialTab);
  const [copied, setCopied] = useState(false);

  let content = "";
  switch(tab) {
    case 'openapi': content = generateOpenAPI(project); break;
    case 'php': content = generatePHP(project); break;
    case 'pkg': content = generatePackageJSON(project); break;
    case 'composer': content = generateComposerJSON(project); break;
    case 'blueprint': content = generatePlaygroundBlueprint(project); break;
  }

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePlaygroundLaunch = () => {
    const blueprint = generatePlaygroundBlueprint(project);
    const fragment = `#${JSON.stringify(JSON.parse(blueprint))}`;
    window.open(`https://playground.wordpress.net/${fragment}`, '_blank');
  };

  const tabs = [
    { id: 'openapi', label: 'openapi.json', icon: FileJson, color: 'text-blue-400', activeBg: 'bg-blue-500/10 border-blue-500/30' },
    { id: 'php', label: 'plugin.php', icon: FileCode, color: 'text-purple-400', activeBg: 'bg-purple-500/10 border-purple-500/30' },
    { id: 'pkg', label: 'package.json', icon: Package, color: 'text-green-400', activeBg: 'bg-green-500/10 border-green-500/30' },
    { id: 'composer', label: 'composer.json', icon: Package, color: 'text-yellow-400', activeBg: 'bg-yellow-500/10 border-yellow-500/30' },
    { id: 'blueprint', label: 'blueprint.json', icon: PlayCircle, color: 'text-blue-500', activeBg: 'bg-blue-600/10 border-blue-600/30' },
  ];

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e]">
      <div className="flex items-center justify-between px-4 py-2 bg-[#252526] border-b border-[#333]">
        <div className="flex gap-1 overflow-x-auto">
          {tabs.map(t => (
            <button
              key={t.id}
              onClick={() => setTab(t.id as any)}
              className={`flex items-center gap-2 px-4 py-2 text-xs font-medium rounded-t-lg transition-all border border-transparent whitespace-nowrap ${
                tab === t.id 
                ? `${t.activeBg} ${t.color}` 
                : 'text-slate-400 hover:bg-[#333] hover:text-slate-200'
              }`}
            >
              <t.icon size={14} />
              {t.label}
            </button>
          ))}
        </div>
        <div className="flex gap-2">
           {tab === 'blueprint' && (
              <button
                onClick={handlePlaygroundLaunch}
                className="flex items-center gap-2 text-xs text-white bg-blue-600 hover:bg-blue-500 px-3 py-1.5 rounded transition-colors shadow-lg shadow-blue-500/20 font-medium"
              >
                <PlayCircle size={14} />
                Run in Playground
              </button>
           )}
          <button 
            onClick={handleCopy}
            className="flex items-center gap-2 text-xs text-slate-400 hover:text-white px-3 py-1.5 rounded bg-[#333] hover:bg-[#444] transition-colors"
          >
            {copied ? <Check size={14} className="text-green-500"/> : <Copy size={14} />}
            {copied ? 'Copied' : 'Copy'}
          </button>
        </div>
      </div>
      <div className="flex-1 overflow-auto p-4 custom-scrollbar relative">
         {tab === 'blueprint' && (
            <div className="absolute top-4 right-8 bg-[#252526] border border-[#444] p-3 rounded-lg max-w-sm text-xs text-slate-400 z-10 shadow-xl">
               <p className="mb-2"><strong className="text-white">What is this?</strong></p>
               <p>This blueprint allows you to instantly spin up a real WordPress instance in your browser running your generated plugin code.</p>
            </div>
         )}
        <pre className="font-mono text-sm leading-relaxed text-[#d4d4d4]">
          <code>{content}</code>
        </pre>
      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { ProjectState, CustomEndpoint, CustomPostType, ResourceType, ContextMenuState } from '../types';
import { Network, Database, Activity, Box, Edit, Trash2, Copy, Plus } from 'lucide-react';

interface FlowDesignerProps {
  project: ProjectState;
  onSelect: (type: ResourceType, id: string) => void;
  onDelete: (type: ResourceType, id: string) => void;
  onDuplicate: (type: ResourceType, id: string) => void;
  onAdd: (type: ResourceType) => void;
}

export const FlowDesigner: React.FC<FlowDesignerProps> = ({ project, onSelect, onDelete, onDuplicate, onAdd }) => {
  const { postTypes, customEndpoints } = project;
  const [connections, setConnections] = useState<JSX.Element[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);

  // Refs for node positions
  const endpointRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const logicRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const cptRefs = useRef<Record<string, HTMLDivElement | null>>({});

  // Context Menu State
  const [contextMenu, setContextMenu] = useState<ContextMenuState>({
    visible: false, x: 0, y: 0, type: null, id: null
  });

  // Re-calculate connection lines on project change or resize
  useEffect(() => {
    const calculateLines = () => {
      if (!containerRef.current) return;

      const containerRect = containerRef.current.getBoundingClientRect();
      const newConnections: JSX.Element[] = [];

      customEndpoints.forEach(ep => {
        // Line 1: Endpoint -> Logic
        const startEl = endpointRefs.current[ep.id];
        const midEl = logicRefs.current[ep.id];

        if (startEl && midEl) {
           const startRect = startEl.getBoundingClientRect();
           const midRect = midEl.getBoundingClientRect();

           const x1 = startRect.right - containerRect.left;
           const y1 = startRect.top + startRect.height / 2 - containerRect.top;
           const x2 = midRect.left - containerRect.left;
           const y2 = midRect.top + midRect.height / 2 - containerRect.top;

           const cp1x = x1 + (x2 - x1) / 2;
           const cp2x = x2 - (x2 - x1) / 2;

           newConnections.push(
             <path 
               key={`conn_1_${ep.id}`} 
               d={`M ${x1} ${y1} C ${cp1x} ${y1}, ${cp2x} ${y2}, ${x2} ${y2}`} 
               fill="none" 
               stroke="#64748b" 
               strokeWidth="2" 
               className="opacity-40"
             />
           );
        }

        // Line 2: Logic -> CPT (if storage enabled)
        if (ep.storage?.enabled && ep.storage.targetCptSlug) {
           const targetCpt = postTypes.find(pt => pt.slug === ep.storage?.targetCptSlug);
           if (targetCpt) {
             const endEl = cptRefs.current[targetCpt.id];
             if (midEl && endEl) {
                const midRect = midEl.getBoundingClientRect();
                const endRect = endEl.getBoundingClientRect();

                const x1 = midRect.right - containerRect.left;
                const y1 = midRect.top + midRect.height / 2 - containerRect.top;
                const x2 = endRect.left - containerRect.left;
                const y2 = endRect.top + endRect.height / 2 - containerRect.top;

                const cp1x = x1 + (x2 - x1) / 2;
                const cp2x = x2 - (x2 - x1) / 2;

                newConnections.push(
                  <path 
                    key={`conn_2_${ep.id}_${targetCpt.id}`} 
                    d={`M ${x1} ${y1} C ${cp1x} ${y1}, ${cp2x} ${y2}, ${x2} ${y2}`} 
                    fill="none" 
                    stroke="#818cf8" 
                    strokeWidth="2" 
                    strokeDasharray="4 4"
                    className="opacity-60"
                  />
                );
             }
           }
        }
      });
      setConnections(newConnections);
    };

    // Small delay to ensure DOM is rendered
    setTimeout(calculateLines, 100);
    window.addEventListener('resize', calculateLines);
    return () => window.removeEventListener('resize', calculateLines);
  }, [project, postTypes, customEndpoints]);

  // Handle Right Click
  const handleContextMenu = (e: React.MouseEvent, type: ResourceType, id: string) => {
    e.preventDefault();
    setContextMenu({
      visible: true,
      x: e.clientX,
      y: e.clientY,
      type,
      id
    });
  };

  const closeContextMenu = () => {
    setContextMenu({ ...contextMenu, visible: false });
  };

  return (
    <div 
      className="h-full w-full p-8 bg-[#0f111a] overflow-auto custom-scrollbar relative" 
      ref={containerRef}
      onClick={closeContextMenu}
    >
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-5 pointer-events-none"></div>

      {/* SVG Layer for Connections */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none z-0 overflow-visible">
        {connections}
      </svg>

      <div className="flex justify-between items-center mb-10 relative z-10">
        <div>
           <h2 className="text-2xl font-bold text-white mb-2">Architectural Flow Designer</h2>
           <p className="text-slate-400">Visualizing Data Flow: API &rarr; Logic &rarr; Storage</p>
        </div>
        <div className="flex gap-4 text-xs font-mono bg-slate-900/80 p-2 rounded-lg border border-slate-800 backdrop-blur-sm">
           <div className="flex items-center gap-2 text-pink-400"><Network size={14}/> Endpoint</div>
           <div className="flex items-center gap-2 text-yellow-400"><Activity size={14}/> Action Hook</div>
           <div className="flex items-center gap-2 text-indigo-400"><Database size={14}/> Custom Post Type</div>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-32 min-w-[1200px] relative z-10 pb-20">

        {/* Column 1: API Surface */}
        <div className="space-y-8">
          <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-6">
             <h3 className="text-sm font-bold text-pink-500 uppercase tracking-wider">1. API Routes (Input)</h3>
             <button onClick={() => onAdd('endpoint')} className="text-slate-500 hover:text-white p-1 hover:bg-slate-800 rounded">
               <Plus size={16} />
             </button>
          </div>

          {customEndpoints.map(ep => (
            <div 
              key={ep.id} 
              ref={el => endpointRefs.current[ep.id] = el}
              onClick={() => onSelect('endpoint', ep.id)}
              onContextMenu={(e) => handleContextMenu(e, 'endpoint', ep.id)}
              className="relative bg-slate-800/80 backdrop-blur-sm border border-pink-500/30 rounded-lg p-4 shadow-lg group hover:border-pink-500 transition-all cursor-pointer hover:shadow-pink-900/20 hover:-translate-y-1"
            >
              {/* Output Dot */}
              <div className="absolute -right-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-pink-500 z-20"></div>

              <div className="flex items-center justify-between mb-2">
                 <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${ep.method === 'GET' ? 'bg-blue-900 text-blue-300' : 'bg-green-900 text-green-300'}`}>{ep.method}</span>
                 <Network size={16} className="text-pink-400" />
              </div>
              <div className="font-mono text-sm text-slate-200 truncate" title={ep.route}>{ep.route}</div>
              <div className="text-xs text-slate-500 mt-2">{ep.parameters.length} Parameters</div>
            </div>
          ))}
          {customEndpoints.length === 0 && <div className="text-slate-600 italic text-sm border border-dashed border-slate-800 p-8 rounded text-center">No Endpoints defined</div>}
        </div>

        {/* Column 2: Logic Layer */}
        <div className="space-y-8 pt-12"> 
           <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-6">
             <h3 className="text-sm font-bold text-yellow-500 uppercase tracking-wider">2. Business Logic</h3>
           </div>

           {customEndpoints.map(ep => (
             <div 
               key={`logic_${ep.id}`} 
               ref={el => logicRefs.current[ep.id] = el}
               onClick={() => onSelect('endpoint', ep.id)} // Logic is part of endpoint config
               className="relative bg-slate-800/80 backdrop-blur-sm border border-yellow-500/30 rounded-lg p-4 shadow-lg min-h-[100px] flex flex-col justify-center transition-all cursor-pointer hover:border-yellow-500 hover:shadow-yellow-900/20"
             >
                {/* Input Dot */}
                <div className="absolute -left-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-slate-500 z-20"></div>

                {ep.storage?.enabled ? (
                   <div className="mb-2 flex items-center gap-2 text-green-400 text-xs font-mono bg-green-900/20 p-1.5 rounded border border-green-500/20 w-fit">
                     <Database size={12} /> Auto-Save
                   </div>
                ) : (
                  <div className="mb-2 flex items-center gap-2 text-slate-500 text-xs font-mono border border-slate-700 p-1.5 rounded w-fit">
                     <Code size={12} /> Custom Logic
                   </div>
                )}

                <div className="flex items-center gap-2">
                   <Activity size={16} className="text-yellow-400" />
                   <div className="text-sm font-mono text-yellow-100">{ep.hookName || '(No Action Hook)'}</div>
                </div>

                {ep.storage?.enabled && (
                  /* Output Dot for Storage */
                  <div className="absolute -right-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-indigo-500 z-20"></div>
                )}
             </div>
           ))}
        </div>

        {/* Column 3: Storage Layer */}
        <div className="space-y-8">
           <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-6">
             <h3 className="text-sm font-bold text-indigo-500 uppercase tracking-wider">3. Data Storage (CPT)</h3>
             <button onClick={() => onAdd('postType')} className="text-slate-500 hover:text-white p-1 hover:bg-slate-800 rounded">
               <Plus size={16} />
             </button>
           </div>

           {postTypes.map(pt => {
             const linkedEndpoints = customEndpoints.filter(ep => ep.storage?.targetCptSlug === pt.slug && ep.storage.enabled);
             return (
               <div 
                 key={pt.id} 
                 ref={el => cptRefs.current[pt.id] = el}
                 onClick={() => onSelect('postType', pt.id)}
                 onContextMenu={(e) => handleContextMenu(e, 'postType', pt.id)}
                 className="relative bg-slate-800/80 backdrop-blur-sm border border-indigo-500/30 rounded-lg p-4 shadow-lg transition-all cursor-pointer hover:border-indigo-500 hover:shadow-indigo-900/20 hover:-translate-y-1"
               >
                  {/* Input Dot */}
                  {linkedEndpoints.length > 0 && <div className="absolute -left-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-indigo-500 z-20"></div>}

                  <div className="flex items-center justify-between mb-3">
                    <h4 className="font-bold text-indigo-300 flex items-center gap-2">
                      <Box size={18} /> {pt.singularName}
                    </h4>
                    <span className="text-[10px] bg-slate-700 px-1.5 py-0.5 rounded text-slate-300">{pt.slug}</span>
                  </div>

                  <div className="space-y-1 mb-4">
                     {pt.metaFields.slice(0, 3).map(mf => (
                       <div key={mf.id} className="text-xs text-slate-500 flex justify-between border-b border-slate-800/50 pb-1">
                         <span>{mf.key}</span>
                         <span className="text-slate-600">{mf.type}</span>
                       </div>
                     ))}
                     {pt.metaFields.length > 3 && <div className="text-xs text-slate-600 italic">+{pt.metaFields.length - 3} more fields</div>}
                  </div>

                  {linkedEndpoints.length > 0 && (
                    <div className="bg-indigo-900/20 rounded p-2 border border-indigo-500/20">
                      <p className="text-[10px] text-indigo-300 mb-1">Fed by:</p>
                      <div className="flex flex-wrap gap-1">
                        {linkedEndpoints.map(ep => (
                          <span key={ep.id} className="text-[10px] bg-indigo-500/20 px-1 rounded border border-indigo-500/30 text-indigo-200">
                            {ep.route}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
               </div>
             );
           })}
        </div>

      </div>

      {/* Context Menu */}
      {contextMenu.visible && (
        <div 
          className="fixed bg-[#252526] border border-[#444] rounded-lg shadow-2xl py-1 z-50 min-w-[160px]"
          style={{ top: contextMenu.y, left: contextMenu.x }}
          onClick={(e) => e.stopPropagation()}
        >
          <button 
            onClick={() => { onSelect(contextMenu.type!, contextMenu.id!); closeContextMenu(); }}
            className="w-full text-left px-4 py-2 text-sm text-slate-200 hover:bg-blue-600 hover:text-white flex items-center gap-2"
          >
            <Edit size={14} /> Edit
          </button>
          <button 
             onClick={() => { onDuplicate(contextMenu.type!, contextMenu.id!); closeContextMenu(); }}
             className="w-full text-left px-4 py-2 text-sm text-slate-200 hover:bg-blue-600 hover:text-white flex items-center gap-2"
          >
            <Copy size={14} /> Duplicate
          </button>
          <div className="h-px bg-[#444] my-1"></div>
          <button 
             onClick={() => { onDelete(contextMenu.type!, contextMenu.id!); closeContextMenu(); }}
             className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-red-900/50 flex items-center gap-2"
          >
            <Trash2 size={14} /> Delete
          </button>
        </div>
      )}
    </div>
  );
};

