import React, { useState, useEffect } from 'react';
import { ProjectState, ViewMode, CustomPostType, CustomEndpoint, ResourceType } from './types';
import { INITIAL_PROJECT_STATE } from './constants';
import { ResourceEditor } from './components/ResourceEditor';
import { EndpointEditor } from './components/EndpointEditor';
import { CodePreview } from './components/CodePreview';
import { FlowDesigner } from './components/FlowDesigner';
import { AIAssistant } from './components/AIAssistant';
import { 
  Box, 
  Code, 
  LayoutTemplate, 
  Sparkles, 
  GitBranch, 
  Plus, 
  FileJson,
  Network
} from 'lucide-react';

interface SelectionState {
  type: ResourceType;
  id: string;
}

const App = () => {
  const [project, setProject] = useState<ProjectState>(INITIAL_PROJECT_STATE);
  const [currentView, setCurrentView] = useState<ViewMode>('editor');
  const [selection, setSelection] = useState<SelectionState>({ type: 'postType', id: project.postTypes[0].id });
  const [isAIModalOpen, setAIModalOpen] = useState(false);

  // Auto-select if current selection deleted
  useEffect(() => {
    if (selection.type === 'postType') {
      const exists = project.postTypes.find(pt => pt.id === selection.id);
      if (!exists) {
        if (project.postTypes.length > 0) {
          setSelection({ type: 'postType', id: project.postTypes[0].id });
        } else if (project.customEndpoints.length > 0) {
           setSelection({ type: 'endpoint', id: project.customEndpoints[0].id });
        }
      }
    } else {
       const exists = project.customEndpoints.find(ep => ep.id === selection.id);
       if (!exists) {
         if (project.customEndpoints.length > 0) {
           setSelection({ type: 'endpoint', id: project.customEndpoints[0].id });
         } else if (project.postTypes.length > 0) {
            setSelection({ type: 'postType', id: project.postTypes[0].id });
         }
       }
    }
  }, [project.postTypes, project.customEndpoints, selection]);

  const handleUpdateResource = (updatedCpt: CustomPostType) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.map(pt => pt.id === updatedCpt.id ? updatedCpt : pt)
    }));
  };

  const handleUpdateEndpoint = (updatedEndpoint: CustomEndpoint) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.map(ep => ep.id === updatedEndpoint.id ? updatedEndpoint : ep)
    }));
  };

  const handleAddResource = () => {
    const newId = `cpt_${Date.now()}`;
    const newCpt: CustomPostType = {
      id: newId,
      slug: 'new_type',
      singularName: 'New Type',
      pluralName: 'New Types',
      description: '',
      icon: 'admin-post',
      supports: ['title', 'editor'],
      taxonomies: [],
      metaFields: [],
      showInRest: true,
      restBase: 'new_types'
    };
    setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, newCpt] }));
    setSelection({ type: 'postType', id: newId });
    setCurrentView('editor');
  };

  const handleAddEndpoint = () => {
    const newId = `endpoint_${Date.now()}`;
    const newEndpoint: CustomEndpoint = {
       id: newId,
       route: '/new-route',
       method: 'GET',
       callbackFunction: 'my_callback_function',
       description: 'New custom endpoint',
       parameters: []
    };
    setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, newEndpoint] }));
    setSelection({ type: 'endpoint', id: newId });
    setCurrentView('editor');
  };

  const handleDeleteResource = (id: string) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.filter(pt => pt.id !== id)
    }));
  };

  const handleDeleteEndpoint = (id: string) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.filter(ep => ep.id !== id)
    }));
  };

  const handleDuplicate = (type: ResourceType, id: string) => {
    if (type === 'postType') {
       const original = project.postTypes.find(pt => pt.id === id);
       if (original) {
         const newId = `cpt_${Date.now()}`;
         const copy = { ...original, id: newId, slug: `${original.slug}_copy`, singularName: `${original.singularName} Copy`, pluralName: `${original.pluralName} Copy` };
         setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, copy] }));
       }
    } else {
      const original = project.customEndpoints.find(ep => ep.id === id);
      if (original) {
        const newId = `endpoint_${Date.now()}`;
        const copy = { ...original, id: newId, route: `${original.route}-copy` };
        setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, copy] }));
      }
    }
  };

  const handleAIApply = (partial: Partial<ProjectState>) => {
    setProject(prev => ({
      ...prev,
      postTypes: [...prev.postTypes, ...(partial.postTypes || [])],
      taxonomies: [...prev.taxonomies, ...(partial.taxonomies || [])],
      customEndpoints: [...prev.customEndpoints, ...(partial.customEndpoints || [])]
    }));
  };

  // Flow Designer Handlers
  const handleFlowSelect = (type: ResourceType, id: string) => {
    setSelection({ type, id });
    setCurrentView('editor');
  };

  const handleFlowDelete = (type: ResourceType, id: string) => {
    if (type === 'postType') handleDeleteResource(id);
    else handleDeleteEndpoint(id);
  };

  const handleFlowAdd = (type: ResourceType) => {
    if (type === 'postType') handleAddResource();
    else handleAddEndpoint();
  };

  const selectedCpt = selection.type === 'postType' ? project.postTypes.find(pt => pt.id === selection.id) : null;
  const selectedEndpoint = selection.type === 'endpoint' ? project.customEndpoints.find(ep => ep.id === selection.id) : null;

  return (
    <div className="flex h-screen bg-slate-900 text-slate-100 overflow-hidden font-sans">

      {/* Sidebar */}
      <div className="w-64 bg-slate-950 flex flex-col border-r border-slate-800">
        <div className="p-4 border-b border-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <LayoutTemplate size={18} className="text-white"/>
          </div>
          <span className="font-bold text-lg tracking-tight">WP Architect</span>
        </div>

        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-4 mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">Content Models</div>
          <div className="space-y-1 px-2 mb-6">
            {project.postTypes.map(pt => (
              <button
                key={pt.id}
                onClick={() => {
                  setSelection({ type: 'postType', id: pt.id });
                  setCurrentView('editor');
                }}
                className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${selection.id === pt.id && selection.type === 'postType' && currentView === 'editor' ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
              >
                <Box size={16} />
                {pt.pluralName}
              </button>
            ))}
            <button 
              onClick={handleAddResource}
              className="w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 text-slate-500 hover:text-indigo-400 hover:bg-slate-900 transition-colors border border-dashed border-slate-800 hover:border-indigo-500/50 mt-2"
            >
              <Plus size={16} /> Add Model
            </button>
          </div>

          <div className="px-4 mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">API Routes</div>
           <div className="space-y-1 px-2 mb-6">
            {project.customEndpoints.map(ep => (
              <button
                key={ep.id}
                onClick={() => {
                  setSelection({ type: 'endpoint', id: ep.id });
                  setCurrentView('editor');
                }}
                className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${selection.id === ep.id && selection.type === 'endpoint' && currentView === 'editor' ? 'bg-pink-600/20 text-pink-300 border border-pink-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
              >
                <Network size={16} />
                <span className="truncate">{ep.route}</span>
              </button>
            ))}
            <button 
              onClick={handleAddEndpoint}
              className="w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 text-slate-500 hover:text-pink-400 hover:bg-slate-900 transition-colors border border-dashed border-slate-800 hover:border-pink-500/50 mt-2"
            >
              <Plus size={16} /> Add Route
            </button>
          </div>

          <div className="px-4 mt-auto mb-2 text-xs font-semibold text-slate-500 uppercase tracking-wider">Design & Build</div>
          <div className="space-y-1 px-2">
            <button 
              onClick={() => setCurrentView('flow')}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentView === 'flow' ? 'bg-emerald-600/20 text-emerald-300 border border-emerald-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            >
              <GitBranch size={16} /> Flow Designer
            </button>
            <button 
              onClick={() => setCurrentView('openapi')}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentView === 'openapi' ? 'bg-blue-600/20 text-blue-300 border border-blue-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            >
              <FileJson size={16} /> OpenAPI Spec
            </button>
            <button 
              onClick={() => setCurrentView('php')}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentView === 'php' ? 'bg-purple-600/20 text-purple-300 border border-purple-500/30' : 'text-slate-400 hover:bg-slate-900 hover:text-slate-200'}`}
            >
              <Code size={16} /> Build (PHP/Pkg)
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800">
          <button 
            onClick={() => setAIModalOpen(true)}
            className="w-full bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white py-2 rounded-lg shadow-lg shadow-purple-900/20 flex items-center justify-center gap-2 font-medium transition-all"
          >
            <Sparkles size={16} /> AI Architect
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0f111a]">
        {currentView === 'editor' ? (
          selection.type === 'postType' && selectedCpt ? (
            <ResourceEditor 
              cpt={selectedCpt} 
              allTaxonomies={project.taxonomies}
              onChange={handleUpdateResource}
              onDelete={() => handleDeleteResource(selectedCpt.id)}
            />
          ) : selection.type === 'endpoint' && selectedEndpoint ? (
            <EndpointEditor
              endpoint={selectedEndpoint}
              namespace={project.namespace}
              postTypes={project.postTypes}
              onChange={handleUpdateEndpoint}
              onDelete={() => handleDeleteEndpoint(selectedEndpoint.id)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center h-full text-slate-500">
               <div className="p-8 bg-slate-900/50 rounded-full mb-4">
                 <LayoutTemplate size={48} className="text-slate-700" />
               </div>
               <p className="text-lg font-medium mb-2">Welcome to WP API Architect</p>
               <p className="text-sm">Select a resource or route from the sidebar to begin.</p>
            </div>
          )
        ) : currentView === 'openapi' ? (
           <CodePreview project={project} initialTab="openapi" />
        ) : currentView === 'php' ? (
           <CodePreview project={project} initialTab="php" />
        ) : currentView === 'flow' ? (
           <FlowDesigner 
             project={project} 
             onSelect={handleFlowSelect}
             onDelete={handleFlowDelete}
             onDuplicate={handleDuplicate}
             onAdd={handleFlowAdd}
           />
        ) : null}
      </div>

      {isAIModalOpen && (
        <AIAssistant 
          project={project} 
          onApply={handleAIApply} 
          onClose={() => setAIModalOpen(false)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { ProjectState, CustomEndpoint, CustomPostType, ResourceType, ContextMenuState } from '../types';
import { Network, Database, Activity, Box, Edit, Trash2, Copy, Plus } from 'lucide-react';

interface FlowDesignerProps {
  project: ProjectState;
  onSelect: (type: ResourceType, id: string) => void;
  onDelete: (type: ResourceType, id: string) => void;
  onDuplicate: (type: ResourceType, id: string) => void;
  onAdd: (type: ResourceType) => void;
}

export const FlowDesigner: React.FC<FlowDesignerProps> = ({ project, onSelect, onDelete, onDuplicate, onAdd }) => {
  const { postTypes, customEndpoints } = project;
  const [connections, setConnections] = useState<React.ReactElement[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);

  // Refs for node positions
  const endpointRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const logicRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const cptRefs = useRef<Record<string, HTMLDivElement | null>>({});

  // Context Menu State
  const [contextMenu, setContextMenu] = useState<ContextMenuState>({
    visible: false, x: 0, y: 0, type: null, id: null
  });

  // Re-calculate connection lines on project change or resize
  useEffect(() => {
    const calculateLines = () => {
      if (!containerRef.current) return;

      const containerRect = containerRef.current.getBoundingClientRect();
      const newConnections: React.ReactElement[] = [];

      customEndpoints.forEach(ep => {
        // Line 1: Endpoint -> Logic
        const startEl = endpointRefs.current[ep.id];
        const midEl = logicRefs.current[ep.id];

        if (startEl && midEl) {
           const startRect = startEl.getBoundingClientRect();
           const midRect = midEl.getBoundingClientRect();

           const x1 = startRect.right - containerRect.left;
           const y1 = startRect.top + startRect.height / 2 - containerRect.top;
           const x2 = midRect.left - containerRect.left;
           const y2 = midRect.top + midRect.height / 2 - containerRect.top;

           const cp1x = x1 + (x2 - x1) / 2;
           const cp2x = x2 - (x2 - x1) / 2;

           newConnections.push(
             <path 
               key={`conn_1_${ep.id}`} 
               d={`M ${x1} ${y1} C ${cp1x} ${y1}, ${cp2x} ${y2}, ${x2} ${y2}`} 
               fill="none" 
               stroke="#64748b" 
               strokeWidth="2" 
               className="opacity-40"
             />
           );
        }

        // Line 2: Logic -> CPT (if storage enabled)
        if (ep.storage?.enabled && ep.storage.targetCptSlug) {
           const targetCpt = postTypes.find(pt => pt.slug === ep.storage?.targetCptSlug);
           if (targetCpt) {
             const endEl = cptRefs.current[targetCpt.id];
             if (midEl && endEl) {
                const midRect = midEl.getBoundingClientRect();
                const endRect = endEl.getBoundingClientRect();

                const x1 = midRect.right - containerRect.left;
                const y1 = midRect.top + midRect.height / 2 - containerRect.top;
                const x2 = endRect.left - containerRect.left;
                const y2 = endRect.top + endRect.height / 2 - containerRect.top;

                const cp1x = x1 + (x2 - x1) / 2;
                const cp2x = x2 - (x2 - x1) / 2;

                newConnections.push(
                  <path 
                    key={`conn_2_${ep.id}_${targetCpt.id}`} 
                    d={`M ${x1} ${y1} C ${cp1x} ${y1}, ${cp2x} ${y2}, ${x2} ${y2}`} 
                    fill="none" 
                    stroke="#818cf8" 
                    strokeWidth="2" 
                    strokeDasharray="4 4"
                    className="opacity-60"
                  />
                );
             }
           }
        }
      });
      setConnections(newConnections);
    };

    // Small delay to ensure DOM is rendered
    setTimeout(calculateLines, 100);
    window.addEventListener('resize', calculateLines);
    return () => window.removeEventListener('resize', calculateLines);
  }, [project, postTypes, customEndpoints]);

  // Handle Right Click
  const handleContextMenu = (e: React.MouseEvent, type: ResourceType, id: string) => {
    e.preventDefault();
    setContextMenu({
      visible: true,
      x: e.clientX,
      y: e.clientY,
      type,
      id
    });
  };

  const closeContextMenu = () => {
    setContextMenu({ ...contextMenu, visible: false });
  };

  return (
    <div 
      className="h-full w-full p-8 bg-[#0f111a] overflow-auto custom-scrollbar relative" 
      ref={containerRef}
      onClick={closeContextMenu}
    >
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-5 pointer-events-none"></div>

      {/* SVG Layer for Connections */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none z-0 overflow-visible">
        {connections}
      </svg>

      <div className="flex justify-between items-center mb-10 relative z-10">
        <div>
           <h2 className="text-2xl font-bold text-white mb-2">Architectural Flow Designer</h2>
           <p className="text-slate-400">Visualizing Data Flow: API &rarr; Logic &rarr; Storage</p>
        </div>
        <div className="flex gap-4 text-xs font-mono bg-slate-900/80 p-2 rounded-lg border border-slate-800 backdrop-blur-sm">
           <div className="flex items-center gap-2 text-pink-400"><Network size={14}/> Endpoint</div>
           <div className="flex items-center gap-2 text-yellow-400"><Activity size={14}/> Action Hook</div>
           <div className="flex items-center gap-2 text-indigo-400"><Database size={14}/> Custom Post Type</div>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-32 min-w-[1200px] relative z-10 pb-20">

        {/* Column 1: API Surface */}
        <div className="space-y-8">
          <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-6">
             <h3 className="text-sm font-bold text-pink-500 uppercase tracking-wider">1. API Routes (Input)</h3>
             <button onClick={() => onAdd('endpoint')} className="text-slate-500 hover:text-white p-1 hover:bg-slate-800 rounded">
               <Plus size={16} />
             </button>
          </div>

          {customEndpoints.map(ep => (
            <div 
              key={ep.id} 
              ref={el => endpointRefs.current[ep.id] = el}
              onClick={() => onSelect('endpoint', ep.id)}
              onContextMenu={(e) => handleContextMenu(e, 'endpoint', ep.id)}
              className="relative bg-slate-800/80 backdrop-blur-sm border border-pink-500/30 rounded-lg p-4 shadow-lg group hover:border-pink-500 transition-all cursor-pointer hover:shadow-pink-900/20 hover:-translate-y-1"
            >
              {/* Output Dot */}
              <div className="absolute -right-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-pink-500 z-20"></div>

              <div className="flex items-center justify-between mb-2">
                 <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${ep.method === 'GET' ? 'bg-blue-900 text-blue-300' : 'bg-green-900 text-green-300'}`}>{ep.method}</span>
                 <Network size={16} className="text-pink-400" />
              </div>
              <div className="font-mono text-sm text-slate-200 truncate" title={ep.route}>{ep.route}</div>
              <div className="text-xs text-slate-500 mt-2">{ep.parameters.length} Parameters</div>
            </div>
          ))}
          {customEndpoints.length === 0 && <div className="text-slate-600 italic text-sm border border-dashed border-slate-800 p-8 rounded text-center">No Endpoints defined</div>}
        </div>

        {/* Column 2: Logic Layer */}
        <div className="space-y-8 pt-12"> 
           <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-6">
             <h3 className="text-sm font-bold text-yellow-500 uppercase tracking-wider">2. Business Logic</h3>
           </div>

           {customEndpoints.map(ep => (
             <div 
               key={`logic_${ep.id}`} 
               ref={el => logicRefs.current[ep.id] = el}
               onClick={() => onSelect('endpoint', ep.id)} // Logic is part of endpoint config
               className="relative bg-slate-800/80 backdrop-blur-sm border border-yellow-500/30 rounded-lg p-4 shadow-lg min-h-[100px] flex flex-col justify-center transition-all cursor-pointer hover:border-yellow-500 hover:shadow-yellow-900/20"
             >
                {/* Input Dot */}
                <div className="absolute -left-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-slate-500 z-20"></div>

                {ep.storage?.enabled ? (
                   <div className="mb-2 flex items-center gap-2 text-green-400 text-xs font-mono bg-green-900/20 p-1.5 rounded border border-green-500/20 w-fit">
                     <Database size={12} /> Auto-Save
                   </div>
                ) : (
                  <div className="mb-2 flex items-center gap-2 text-slate-500 text-xs font-mono border border-slate-700 p-1.5 rounded w-fit">
                     <Code size={12} /> Custom Logic
                   </div>
                )}

                <div className="flex items-center gap-2">
                   <Activity size={16} className="text-yellow-400" />
                   <div className="text-sm font-mono text-yellow-100">{ep.hookName || '(No Action Hook)'}</div>
                </div>

                {ep.storage?.enabled && (
                  /* Output Dot for Storage */
                  <div className="absolute -right-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-indigo-500 z-20"></div>
                )}
             </div>
           ))}
        </div>

        {/* Column 3: Storage Layer */}
        <div className="space-y-8">
           <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-6">
             <h3 className="text-sm font-bold text-indigo-500 uppercase tracking-wider">3. Data Storage (CPT)</h3>
             <button onClick={() => onAdd('postType')} className="text-slate-500 hover:text-white p-1 hover:bg-slate-800 rounded">
               <Plus size={16} />
             </button>
           </div>

           {postTypes.map(pt => {
             const linkedEndpoints = customEndpoints.filter(ep => ep.storage?.targetCptSlug === pt.slug && ep.storage.enabled);
             return (
               <div 
                 key={pt.id} 
                 ref={el => cptRefs.current[pt.id] = el}
                 onClick={() => onSelect('postType', pt.id)}
                 onContextMenu={(e) => handleContextMenu(e, 'postType', pt.id)}
                 className="relative bg-slate-800/80 backdrop-blur-sm border border-indigo-500/30 rounded-lg p-4 shadow-lg transition-all cursor-pointer hover:border-indigo-500 hover:shadow-indigo-900/20 hover:-translate-y-1"
               >
                  {/* Input Dot */}
                  {linkedEndpoints.length > 0 && <div className="absolute -left-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-indigo-500 z-20"></div>}

                  <div className="flex items-center justify-between mb-3">
                    <h4 className="font-bold text-indigo-300 flex items-center gap-2">
                      <Box size={18} /> {pt.singularName}
                    </h4>
                    <span className="text-[10px] bg-slate-700 px-1.5 py-0.5 rounded text-slate-300">{pt.slug}</span>
                  </div>

                  <div className="space-y-1 mb-4">
                     {pt.metaFields.slice(0, 3).map(mf => (
                       <div key={mf.id} className="text-xs text-slate-500 flex justify-between border-b border-slate-800/50 pb-1">
                         <span>{mf.key}</span>
                         <span className="text-slate-600">{mf.type}</span>
                       </div>
                     ))}
                     {pt.metaFields.length > 3 && <div className="text-xs text-slate-600 italic">+{pt.metaFields.length - 3} more fields</div>}
                  </div>

                  {linkedEndpoints.length > 0 && (
                    <div className="bg-indigo-900/20 rounded p-2 border border-indigo-500/20">
                      <p className="text-[10px] text-indigo-300 mb-1">Fed by:</p>
                      <div className="flex flex-wrap gap-1">
                        {linkedEndpoints.map(ep => (
                          <span key={ep.id} className="text-[10px] bg-indigo-500/20 px-1 rounded border border-indigo-500/30 text-indigo-200">
                            {ep.route}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
               </div>
             );
           })}
        </div>

      </div>

      {/* Context Menu */}
      {contextMenu.visible && (
        <div 
          className="fixed bg-[#252526] border border-[#444] rounded-lg shadow-2xl py-1 z-50 min-w-[160px]"
          style={{ top: contextMenu.y, left: contextMenu.x }}
          onClick={(e) => e.stopPropagation()}
        >
          <button 
            onClick={() => { onSelect(contextMenu.type!, contextMenu.id!); closeContextMenu(); }}
            className="w-full text-left px-4 py-2 text-sm text-slate-200 hover:bg-blue-600 hover:text-white flex items-center gap-2"
          >
            <Edit size={14} /> Edit
          </button>
          <button 
             onClick={() => { onDuplicate(contextMenu.type!, contextMenu.id!); closeContextMenu(); }}
             className="w-full text-left px-4 py-2 text-sm text-slate-200 hover:bg-blue-600 hover:text-white flex items-center gap-2"
          >
            <Copy size={14} /> Duplicate
          </button>
          <div className="h-px bg-[#444] my-1"></div>
          <button 
             onClick={() => { onDelete(contextMenu.type!, contextMenu.id!); closeContextMenu(); }}
             className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-red-900/50 flex items-center gap-2"
          >
            <Trash2 size={14} /> Delete
          </button>
        </div>
      )}
    </div>
  );
};

// Simple Icon component for local use if needed
const Code = ({ size }: { size: number }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="16 18 22 12 16 6"></polyline><polyline points="8 6 2 12 8 18"></polyline></svg>
);

export enum FieldType {
  STRING = 'string',
  INTEGER = 'integer',
  NUMBER = 'number',
  BOOLEAN = 'boolean',
  ARRAY = 'array',
}

export interface MetaField {
  id: string;
  key: string;
  label: string;
  type: FieldType;
  description: string;
  required: boolean;
  showInRest: boolean;
}

export interface Taxonomy {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  hierarchical: boolean;
  showInRest: boolean;
  connectedPostTypes: string[]; // CPT slugs
}

export interface CustomPostType {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  description: string;
  icon: string; // Dashicon class or similar
  supports: string[]; // title, editor, thumbnail, etc.
  taxonomies: string[]; // Slugs of connected taxonomies
  metaFields: MetaField[];
  showInRest: boolean;
  restBase: string;
}

export type EndpointMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';

export interface EndpointParameter {
  id: string;
  key: string;
  required: boolean;
  type: string;
  description: string;
}

export interface StorageMapping {
  enabled: boolean;
  targetCptSlug: string;
  // Maps param.key -> metaField.key
  fieldMapping: Record<string, string>;
}

export interface CustomEndpoint {
  id: string;
  route: string; // e.g., /checkout/process
  method: EndpointMethod;
  callbackFunction: string;
  description: string;
  parameters: EndpointParameter[];
  hookName?: string; // Optional custom action to fire
