export enum FieldType {
  STRING = 'string',
  INTEGER = 'integer',
  NUMBER = 'number',
  BOOLEAN = 'boolean',
  ARRAY = 'array',
}

export interface MetaField {
  id: string;
  key: string;
  label: string;
  type: FieldType;
  description: string;
  required: boolean;
  showInRest: boolean;
}

export interface Taxonomy {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  hierarchical: boolean;
  showInRest: boolean;
  connectedPostTypes: string[]; // CPT slugs
}

export interface CustomPostType {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  description: string;
  icon: string; // Dashicon class or similar
