import React, { useState, useEffect } from 'react';
import { ProjectState, ViewMode, CustomPostType, CustomEndpoint, ResourceType, AppSettings, AIProvider } from './types';
import { INITIAL_PROJECT_STATE } from './constants';
import { ResourceEditor } from './components/ResourceEditor';
import { EndpointEditor } from './components/EndpointEditor';
import { CodePreview } from './components/CodePreview';
import { FlowDesigner } from './components/FlowDesigner';
import { BlueprintView } from './components/BlueprintView';
import { AIAssistant } from './components/AIAssistant';
import { SettingsScreen } from './components/SettingsScreen';
import { Terminal } from './components/Terminal';
import { Sidebar } from './components/Sidebar';
import { logger } from './utils/logger';
import { LayoutTemplate } from 'lucide-react';

interface SelectionState {
  type: ResourceType;
  id: string;
}

const DEFAULT_SETTINGS: AppSettings = {
  provider: AIProvider.GEMINI,
  apiKey: '', // Empty means use process.env
  model: 'gemini-3-flash-preview',
  temperature: 0.7
};

const App = () => {
  const [project, setProject] = useState<ProjectState>(INITIAL_PROJECT_STATE);
  const [currentView, setCurrentView] = useState<ViewMode>('editor');
  const [selection, setSelection] = useState<SelectionState>({ type: 'postType', id: project.postTypes[0].id });
  const [isAIModalOpen, setAIModalOpen] = useState(false);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [isTerminalOpen, setIsTerminalOpen] = useState(false);

  // Auto-select if current selection deleted
  useEffect(() => {
    if (selection.type === 'postType') {
      const exists = project.postTypes.find(pt => pt.id === selection.id);
      if (!exists) {
        if (project.postTypes.length > 0) {
          setSelection({ type: 'postType', id: project.postTypes[0].id });
        } else if (project.customEndpoints.length > 0) {
           setSelection({ type: 'endpoint', id: project.customEndpoints[0].id });
        }
      }
    } else {
       const exists = project.customEndpoints.find(ep => ep.id === selection.id);
       if (!exists) {
         if (project.customEndpoints.length > 0) {
           setSelection({ type: 'endpoint', id: project.customEndpoints[0].id });
         } else if (project.postTypes.length > 0) {
            setSelection({ type: 'postType', id: project.postTypes[0].id });
         }
       }
    }
  }, [project.postTypes, project.customEndpoints, selection]);

  const handleUpdateResource = (updatedCpt: CustomPostType) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.map(pt => pt.id === updatedCpt.id ? updatedCpt : pt)
    }));
    logger.info(`Updated Post Type: ${updatedCpt.slug}`);
  };

  const handleUpdateEndpoint = (updatedEndpoint: CustomEndpoint) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.map(ep => ep.id === updatedEndpoint.id ? updatedEndpoint : ep)
    }));
    logger.info(`Updated Endpoint: ${updatedEndpoint.route}`);
  };

  const handleAddResource = () => {
    const newId = `cpt_${Date.now()}`;
    const newCpt: CustomPostType = {
      id: newId,
      slug: 'new_type',
      singularName: 'New Type',
      pluralName: 'New Types',
      description: '',
      icon: 'admin-post',
      supports: ['title', 'editor'],
      taxonomies: [],
      metaFields: [],
      showInRest: true,
      restBase: 'new_types'
    };
    setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, newCpt] }));
    setSelection({ type: 'postType', id: newId });
    setCurrentView('editor');
    logger.success('Added new Post Type');
  };

  const handleAddEndpoint = () => {
    const newId = `endpoint_${Date.now()}`;
    const newEndpoint: CustomEndpoint = {
       id: newId,
       route: '/new-route',
       method: 'GET',
       callbackFunction: 'my_callback_function',
       description: 'New custom endpoint',
       parameters: []
    };
    setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, newEndpoint] }));
    setSelection({ type: 'endpoint', id: newId });
    setCurrentView('editor');
    logger.success('Added new Endpoint');
  };

  const handleDeleteResource = (id: string) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.filter(pt => pt.id !== id)
    }));
    logger.info(`Deleted Resource ID: ${id}`);
  };

  const handleDeleteEndpoint = (id: string) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.filter(ep => ep.id !== id)
    }));
    logger.info(`Deleted Endpoint ID: ${id}`);
  };

  const handleDuplicate = (type: ResourceType, id: string) => {
    if (type === 'postType') {
       const original = project.postTypes.find(pt => pt.id === id);
       if (original) {
         const newId = `cpt_${Date.now()}`;
         const copy = { ...original, id: newId, slug: `${original.slug}_copy`, singularName: `${original.singularName} Copy`, pluralName: `${original.pluralName} Copy` };
         setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, copy] }));
         logger.success(`Duplicated Post Type: ${original.slug}`);
       }
    } else {
      const original = project.customEndpoints.find(ep => ep.id === id);
      if (original) {
        const newId = `endpoint_${Date.now()}`;
        const copy = { ...original, id: newId, route: `${original.route}-copy` };
        setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, copy] }));
        logger.success(`Duplicated Endpoint: ${original.route}`);
      }
    }
  };

  const handleAIApply = (partial: Partial<ProjectState>) => {
    setProject(prev => ({
      ...prev,
      postTypes: [...prev.postTypes, ...(partial.postTypes || [])],
      taxonomies: [...prev.taxonomies, ...(partial.taxonomies || [])],
      customEndpoints: [...prev.customEndpoints, ...(partial.customEndpoints || [])]
    }));
    logger.success('Applied AI generated structure');
  };

  const handleViewChange = (view: ViewMode) => {
    setCurrentView(view);
  };

  const handleSelect = (type: ResourceType, id: string) => {
    setSelection({ type, id });
    setCurrentView('editor');
  };

  // Flow Designer Handlers
  const handleFlowSelect = (type: ResourceType, id: string) => {
    setSelection({ type, id });
    setCurrentView('editor');
  };

  const handleFlowDelete = (type: ResourceType, id: string) => {
    if (type === 'postType') handleDeleteResource(id);
    else handleDeleteEndpoint(id);
  };

  const handleFlowAdd = (type: ResourceType) => {
    if (type === 'postType') handleAddResource();
    else handleAddEndpoint();
  };

  const selectedCpt = selection.type === 'postType' ? project.postTypes.find(pt => pt.id === selection.id) : null;
  const selectedEndpoint = selection.type === 'endpoint' ? project.customEndpoints.find(ep => ep.id === selection.id) : null;

  return (
    <div className="flex h-screen bg-slate-900 text-slate-100 overflow-hidden font-sans">

      <Sidebar 
        project={project}
        currentView={currentView}
        selection={selection}
        isTerminalOpen={isTerminalOpen}
        onSelect={handleSelect}
        onViewChange={handleViewChange}
        onAddResource={handleAddResource}
        onAddEndpoint={handleAddEndpoint}
        onToggleTerminal={() => setIsTerminalOpen(!isTerminalOpen)}
        onOpenAI={() => setAIModalOpen(true)}
      />

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0f111a] relative">
        {currentView === 'editor' ? (
          selection.type === 'postType' && selectedCpt ? (
            <ResourceEditor 
              cpt={selectedCpt} 
              allTaxonomies={project.taxonomies}
              onChange={handleUpdateResource}
              onDelete={() => handleDeleteResource(selectedCpt.id)}
            />
          ) : selection.type === 'endpoint' && selectedEndpoint ? (
            <EndpointEditor
              endpoint={selectedEndpoint}
              namespace={project.namespace}
              postTypes={project.postTypes}
              onChange={handleUpdateEndpoint}
              onDelete={() => handleDeleteEndpoint(selectedEndpoint.id)}
            />
          ) : (
             <div className="flex flex-col items-center justify-center h-full text-slate-500">
               <div className="p-8 bg-slate-900/50 rounded-full mb-4">
                 <LayoutTemplate size={48} className="text-slate-700" />
               </div>
               <p className="text-lg font-medium mb-2">Welcome to WP API Architect</p>
               <p className="text-sm">Select a resource or route from the sidebar to begin.</p>
            </div>
          )
        ) : currentView === 'openapi' ? (
           <CodePreview project={project} initialTab="openapi" />
        ) : currentView === 'php' ? (
           <CodePreview project={project} initialTab="php" />
        ) : currentView === 'flow' ? (
           <FlowDesigner 
             project={project} 
             onSelect={handleFlowSelect}
             onDelete={handleFlowDelete}
             onDuplicate={handleDuplicate}
             onAdd={handleFlowAdd}
           />
        ) : currentView === 'blueprint' ? (
           <BlueprintView project={project} />
        ) : currentView === 'settings' ? (
           <SettingsScreen settings={settings} onSave={setSettings} />
        ) : null}

        {isTerminalOpen && <Terminal onClose={() => setIsTerminalOpen(false)} />}
      </div>

      {isAIModalOpen && (
        <AIAssistant 
          project={project}
          settings={settings}
          onApply={handleAIApply} 
          onClose={() => setAIModalOpen(false)} 
        />
      )}
    </div>
  );
};

export default App;

