          project={project}
          settings={settings}
          onApply={handleAIApply} 
          onClose={() => setAIModalOpen(false)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { ProjectState, CustomEndpoint, CustomPostType, ResourceType, ContextMenuState } from '../types';
import { Network, Database, Activity, Box, Edit, Trash2, Copy, Plus, Code } from 'lucide-react';

interface FlowDesignerProps {
  project: ProjectState;
  onSelect: (type: ResourceType, id: string) => void;
  onDelete: (type: ResourceType, id: string) => void;
  onDuplicate: (type: ResourceType, id: string) => void;
  onAdd: (type: ResourceType) => void;
}

export const FlowDesigner: React.FC<FlowDesignerProps> = ({ project, onSelect, onDelete, onDuplicate, onAdd }) => {
  const { postTypes, customEndpoints } = project;
  const [connections, setConnections] = useState<React.ReactElement[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);

  // Refs for node positions
  const endpointRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const logicRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const cptRefs = useRef<Record<string, HTMLDivElement | null>>({});

  // Context Menu State
  const [contextMenu, setContextMenu] = useState<ContextMenuState>({
    visible: false, x: 0, y: 0, type: null, id: null
  });

  // Re-calculate connection lines on project change or resize
  useEffect(() => {
    const calculateLines = () => {
      if (!containerRef.current) return;

      const containerRect = containerRef.current.getBoundingClientRect();
      const newConnections: React.ReactElement[] = [];

      customEndpoints.forEach(ep => {
        // Line 1: Endpoint -> Logic
        const startEl = endpointRefs.current[ep.id];
        const midEl = logicRefs.current[ep.id];

        if (startEl && midEl) {
           const startRect = startEl.getBoundingClientRect();
           const midRect = midEl.getBoundingClientRect();

           const x1 = startRect.right - containerRect.left;
           const y1 = startRect.top + startRect.height / 2 - containerRect.top;
           const x2 = midRect.left - containerRect.left;
           const y2 = midRect.top + midRect.height / 2 - containerRect.top;

           const cp1x = x1 + (x2 - x1) / 2;
           const cp2x = x2 - (x2 - x1) / 2;

           newConnections.push(
             <path 
               key={`conn_1_${ep.id}`} 
               d={`M ${x1} ${y1} C ${cp1x} ${y1}, ${cp2x} ${y2}, ${x2} ${y2}`} 
               fill="none" 
               stroke="#64748b" 
               strokeWidth="2" 
               className="opacity-40"
             />
           );
        }

        // Line 2: Logic -> CPT (if storage enabled)
        if (ep.storage?.enabled && ep.storage.targetCptSlug) {
           const targetCpt = postTypes.find(pt => pt.slug === ep.storage?.targetCptSlug);
           if (targetCpt) {
             const endEl = cptRefs.current[targetCpt.id];
             if (midEl && endEl) {
                const midRect = midEl.getBoundingClientRect();
                const endRect = endEl.getBoundingClientRect();

                const x1 = midRect.right - containerRect.left;
                const y1 = midRect.top + midRect.height / 2 - containerRect.top;
                const x2 = endRect.left - containerRect.left;
                const y2 = endRect.top + endRect.height / 2 - containerRect.top;

                const cp1x = x1 + (x2 - x1) / 2;
                const cp2x = x2 - (x2 - x1) / 2;

                newConnections.push(
                  <path 
                    key={`conn_2_${ep.id}_${targetCpt.id}`} 
                    d={`M ${x1} ${y1} C ${cp1x} ${y1}, ${cp2x} ${y2}, ${x2} ${y2}`} 
                    fill="none" 
                    stroke="#818cf8" 
                    strokeWidth="2" 
                    strokeDasharray="4 4"
                    className="opacity-60"
                  />
                );
             }
           }
        }
      });
      setConnections(newConnections);
    };

    // Small delay to ensure DOM is rendered
    setTimeout(calculateLines, 100);
    window.addEventListener('resize', calculateLines);
    return () => window.removeEventListener('resize', calculateLines);
  }, [project, postTypes, customEndpoints]);

  // Handle Right Click
  const handleContextMenu = (e: React.MouseEvent, type: ResourceType, id: string) => {
    e.preventDefault();
    setContextMenu({
      visible: true,
      x: e.clientX,
      y: e.clientY,
      type,
      id
    });
  };

  const closeContextMenu = () => {
    setContextMenu({ ...contextMenu, visible: false });
  };

  return (
    <div 
      className="h-full w-full p-8 bg-[#0f111a] overflow-auto custom-scrollbar relative" 
      ref={containerRef}
      onClick={closeContextMenu}
    >
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-5 pointer-events-none"></div>

      {/* SVG Layer for Connections */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none z-0 overflow-visible">
        {connections}
      </svg>

      <div className="flex justify-between items-center mb-10 relative z-10">
        <div>
           <h2 className="text-2xl font-bold text-white mb-2">Architectural Flow Designer</h2>
           <p className="text-slate-400">Visualizing Data Flow: API &rarr; Logic &rarr; Storage</p>
        </div>
        <div className="flex gap-4 text-xs font-mono bg-slate-900/80 p-2 rounded-lg border border-slate-800 backdrop-blur-sm">
           <div className="flex items-center gap-2 text-pink-400"><Network size={14}/> Endpoint</div>
           <div className="flex items-center gap-2 text-yellow-400"><Activity size={14}/> Action Hook</div>
           <div className="flex items-center gap-2 text-indigo-400"><Database size={14}/> Custom Post Type</div>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-32 min-w-[1200px] relative z-10 pb-20">

        {/* Column 1: API Surface */}
        <div className="space-y-8">
          <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-6">
             <h3 className="text-sm font-bold text-pink-500 uppercase tracking-wider">1. API Routes (Input)</h3>
             <button onClick={() => onAdd('endpoint')} className="text-slate-500 hover:text-white p-1 hover:bg-slate-800 rounded">
               <Plus size={16} />
             </button>
          </div>

          {customEndpoints.map(ep => (
            <div 
              key={ep.id} 
              ref={el => endpointRefs.current[ep.id] = el}
              onClick={() => onSelect('endpoint', ep.id)}
              onContextMenu={(e) => handleContextMenu(e, 'endpoint', ep.id)}
              className="relative bg-slate-800/80 backdrop-blur-sm border border-pink-500/30 rounded-lg p-4 shadow-lg group hover:border-pink-500 transition-all cursor-pointer hover:shadow-pink-900/20 hover:-translate-y-1"
            >
              {/* Output Dot */}
              <div className="absolute -right-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-pink-500 z-20"></div>

              <div className="flex items-center justify-between mb-2">
                 <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${ep.method === 'GET' ? 'bg-blue-900 text-blue-300' : 'bg-green-900 text-green-300'}`}>{ep.method}</span>
                 <Network size={16} className="text-pink-400" />
              </div>
              <div className="font-mono text-sm text-slate-200 truncate" title={ep.route}>{ep.route}</div>
              <div className="text-xs text-slate-500 mt-2">{ep.parameters.length} Parameters</div>
            </div>
          ))}
          {customEndpoints.length === 0 && <div className="text-slate-600 italic text-sm border border-dashed border-slate-800 p-8 rounded text-center">No Endpoints defined</div>}
        </div>

        {/* Column 2: Logic Layer */}
        <div className="space-y-8 pt-12"> 
           <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-6">
             <h3 className="text-sm font-bold text-yellow-500 uppercase tracking-wider">2. Business Logic</h3>
           </div>

           {customEndpoints.map(ep => (
             <div 
               key={`logic_${ep.id}`} 
               ref={el => logicRefs.current[ep.id] = el}
               onClick={() => onSelect('endpoint', ep.id)} // Logic is part of endpoint config
               className="relative bg-slate-800/80 backdrop-blur-sm border border-yellow-500/30 rounded-lg p-4 shadow-lg min-h-[100px] flex flex-col justify-center transition-all cursor-pointer hover:border-yellow-500 hover:shadow-yellow-900/20"
             >
                {/* Input Dot */}
                <div className="absolute -left-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-slate-500 z-20"></div>

                {ep.storage?.enabled ? (
                   <div className="mb-2 flex items-center gap-2 text-green-400 text-xs font-mono bg-green-900/20 p-1.5 rounded border border-green-500/20 w-fit">
                     <Database size={12} /> Auto-Save
                   </div>
                ) : (
                  <div className="mb-2 flex items-center gap-2 text-slate-500 text-xs font-mono border border-slate-700 p-1.5 rounded w-fit">
                     <Code size={12} /> Custom Logic
                   </div>
                )}

                <div className="flex items-center gap-2">
                   <Activity size={16} className="text-yellow-400" />
                   <div className="text-sm font-mono text-yellow-100">{ep.hookName || '(No Action Hook)'}</div>
                </div>

                {ep.storage?.enabled && (
                  /* Output Dot for Storage */
                  <div className="absolute -right-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-indigo-500 z-20"></div>
                )}
             </div>
           ))}
        </div>

        {/* Column 3: Storage Layer */}
        <div className="space-y-8">
           <div className="flex items-center justify-between border-b border-slate-800 pb-2 mb-6">
             <h3 className="text-sm font-bold text-indigo-500 uppercase tracking-wider">3. Data Storage (CPT)</h3>
             <button onClick={() => onAdd('postType')} className="text-slate-500 hover:text-white p-1 hover:bg-slate-800 rounded">
               <Plus size={16} />
             </button>
           </div>

           {postTypes.map(pt => {
             const linkedEndpoints = customEndpoints.filter(ep => ep.storage?.targetCptSlug === pt.slug && ep.storage.enabled);
             return (
               <div 
                 key={pt.id} 
                 ref={el => cptRefs.current[pt.id] = el}
                 onClick={() => onSelect('postType', pt.id)}
                 onContextMenu={(e) => handleContextMenu(e, 'postType', pt.id)}
                 className="relative bg-slate-800/80 backdrop-blur-sm border border-indigo-500/30 rounded-lg p-4 shadow-lg transition-all cursor-pointer hover:border-indigo-500 hover:shadow-indigo-900/20 hover:-translate-y-1"
               >
                  {/* Input Dot */}
                  {linkedEndpoints.length > 0 && <div className="absolute -left-1.5 top-1/2 -mt-[3px] w-3 h-3 rounded-full bg-slate-900 border-2 border-indigo-500 z-20"></div>}

                  <div className="flex items-center justify-between mb-3">
                    <h4 className="font-bold text-indigo-300 flex items-center gap-2">
                      <Box size={18} /> {pt.singularName}
                    </h4>
                    <span className="text-[10px] bg-slate-700 px-1.5 py-0.5 rounded text-slate-300">{pt.slug}</span>
                  </div>

                  <div className="space-y-1 mb-4">
                     {pt.metaFields.slice(0, 3).map(mf => (
                       <div key={mf.id} className="text-xs text-slate-500 flex justify-between border-b border-slate-800/50 pb-1">
                         <span>{mf.key}</span>
                         <span className="text-slate-600">{mf.type}</span>
                       </div>
                     ))}
                     {pt.metaFields.length > 3 && <div className="text-xs text-slate-600 italic">+{pt.metaFields.length - 3} more fields</div>}
                  </div>

                  {linkedEndpoints.length > 0 && (
                    <div className="bg-indigo-900/20 rounded p-2 border border-indigo-500/20">
                      <p className="text-[10px] text-indigo-300 mb-1">Fed by:</p>
                      <div className="flex flex-wrap gap-1">
                        {linkedEndpoints.map(ep => (
                          <span key={ep.id} className="text-[10px] bg-indigo-500/20 px-1 rounded border border-indigo-500/30 text-indigo-200">
                            {ep.route}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
               </div>
             );
           })}
        </div>

      </div>

      {/* Context Menu */}
      {contextMenu.visible && (
        <div 
          className="fixed bg-[#252526] border border-[#444] rounded-lg shadow-2xl py-1 z-50 min-w-[160px]"
          style={{ top: contextMenu.y, left: contextMenu.x }}
          onClick={(e) => e.stopPropagation()}
        >
          <button 
            onClick={() => { onSelect(contextMenu.type!, contextMenu.id!); closeContextMenu(); }}
            className="w-full text-left px-4 py-2 text-sm text-slate-200 hover:bg-blue-600 hover:text-white flex items-center gap-2"
          >
            <Edit size={14} /> Edit
          </button>
          <button 
             onClick={() => { onDuplicate(contextMenu.type!, contextMenu.id!); closeContextMenu(); }}
             className="w-full text-left px-4 py-2 text-sm text-slate-200 hover:bg-blue-600 hover:text-white flex items-center gap-2"
          >
            <Copy size={14} /> Duplicate
          </button>
          <div className="h-px bg-[#444] my-1"></div>
          <button 
             onClick={() => { onDelete(contextMenu.type!, contextMenu.id!); closeContextMenu(); }}
             className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-red-900/50 flex items-center gap-2"
          >
            <Trash2 size={14} /> Delete
          </button>
        </div>
      )}
    </div>
  );
};

