import React, { useState, useEffect } from 'react';
import { ProjectState, ViewMode, CustomPostType, CustomEndpoint, ResourceType, AppSettings, AIProvider } from './types';
import { INITIAL_PROJECT_STATE } from './constants';
import { ResourceEditor } from './components/ResourceEditor';
import { EndpointEditor } from './components/EndpointEditor';
import { CodePreview } from './components/CodePreview';
import { FlowDesigner } from './components/FlowDesigner';
import { BlueprintView } from './components/BlueprintView';
import { AIAssistant } from './components/AIAssistant';
import { SettingsScreen } from './components/SettingsScreen';
import { Terminal } from './components/Terminal';
import { Sidebar } from './components/Sidebar';
import { EditorModal } from './components/EditorModal';
import { logger } from './utils/logger';
import { LayoutTemplate } from 'lucide-react';

interface SelectionState {
  type: ResourceType;
  id: string;
}

const DEFAULT_SETTINGS: AppSettings = {
  provider: AIProvider.GEMINI,
  apiKey: '', 
  model: 'gemini-3-flash-preview',
  temperature: 0.7
};

const App = () => {
  const [project, setProject] = useState<ProjectState>(INITIAL_PROJECT_STATE);
  const [currentView, setCurrentView] = useState<ViewMode>('flow'); // Default to Flow for better visual start
  const [selection, setSelection] = useState<SelectionState | null>(null);
  const [isAIModalOpen, setAIModalOpen] = useState(false);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [isTerminalOpen, setIsTerminalOpen] = useState(false);

  // State for the Editor Modal
  const [editingResource, setEditingResource] = useState<SelectionState | null>(null);

  const handleUpdateResource = (updatedCpt: CustomPostType) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.map(pt => pt.id === updatedCpt.id ? updatedCpt : pt)
    }));
    logger.info(`Updated Post Type: ${updatedCpt.slug}`);
  };

  const handleUpdateEndpoint = (updatedEndpoint: CustomEndpoint) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.map(ep => ep.id === updatedEndpoint.id ? updatedEndpoint : ep)
    }));
    logger.info(`Updated Endpoint: ${updatedEndpoint.route}`);
  };

  const handleAddResource = () => {
    const newId = `cpt_${Date.now()}`;
    const newCpt: CustomPostType = {
      id: newId,
      slug: 'new_type',
      singularName: 'New Type',
      pluralName: 'New Types',
      description: '',
      icon: 'admin-post',
      supports: ['title', 'editor'],
      taxonomies: [],
      metaFields: [],
      showInRest: true,
      restBase: 'new_types'
    };
    setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, newCpt] }));
    setEditingResource({ type: 'postType', id: newId });
    logger.success('Added new Post Type');
  };

  const handleAddEndpoint = () => {
    const newId = `endpoint_${Date.now()}`;
    const newEndpoint: CustomEndpoint = {
       id: newId,
       route: '/new-route',
       method: 'POST',
       callbackFunction: 'my_callback_function',
       description: 'New custom endpoint',
       parameters: []
    };
    setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, newEndpoint] }));
    setEditingResource({ type: 'endpoint', id: newId });
    logger.success('Added new Endpoint');
  };

  const handleDeleteResource = (id: string) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.filter(pt => pt.id !== id)
    }));
    if (editingResource?.id === id) setEditingResource(null);
    logger.info(`Deleted Resource ID: ${id}`);
  };

  const handleDeleteEndpoint = (id: string) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.filter(ep => ep.id !== id)
    }));
    if (editingResource?.id === id) setEditingResource(null);
    logger.info(`Deleted Endpoint ID: ${id}`);
  };

  const handleDuplicate = (type: ResourceType, id: string) => {
    if (type === 'postType') {
       const original = project.postTypes.find(pt => pt.id === id);
       if (original) {
         const newId = `cpt_${Date.now()}`;
         const copy = { ...original, id: newId, slug: `${original.slug}_copy`, singularName: `${original.singularName} Copy`, pluralName: `${original.pluralName} Copy` };
         setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, copy] }));
         setEditingResource({ type: 'postType', id: newId });
         logger.success(`Duplicated Post Type: ${original.slug}`);
       }
    } else {
      const original = project.customEndpoints.find(ep => ep.id === id);
      if (original) {
        const newId = `endpoint_${Date.now()}`;
        const copy = { ...original, id: newId, route: `${original.route}-copy` };
        setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, copy] }));
        setEditingResource({ type: 'endpoint', id: newId });
        logger.success(`Duplicated Endpoint: ${original.route}`);
      }
    }
  };

  const handleAIApply = (partial: Partial<ProjectState>) => {
    setProject(prev => ({
      ...prev,
      postTypes: [...prev.postTypes, ...(partial.postTypes || [])],
      taxonomies: [...prev.taxonomies, ...(partial.taxonomies || [])],
      customEndpoints: [...prev.customEndpoints, ...(partial.customEndpoints || [])]
    }));
    logger.success('Applied AI generated structure');
  };

  const handleViewChange = (view: ViewMode) => {
    setCurrentView(view);
  };

  const handleSelect = (type: ResourceType, id: string) => {
    setEditingResource({ type, id });
  };

  const renderMainContent = () => {
    switch (currentView) {
      case 'editor':
        // Legacy fallback or landing
        return (
          <div className="flex flex-col items-center justify-center h-full text-slate-500">
             <div className="p-8 bg-slate-900/50 rounded-full mb-4">
               <LayoutTemplate size={48} className="text-slate-700" />
             </div>
             <p className="text-lg font-medium mb-2">Editor Viewport</p>
             <p className="text-sm">Quick editing is now available via modals in Flow and Blueprint views.</p>
          </div>
        );
      case 'openapi':
        return <CodePreview project={project} initialTab="openapi" />;
      case 'php':
        return <CodePreview project={project} initialTab="php" />;
      case 'flow':
        return (
           <FlowDesigner 
             project={project} 
             onSelect={handleSelect}
             onDelete={handleFlowDelete}
             onDuplicate={handleDuplicate}
             onAdd={(type) => type === 'postType' ? handleAddResource() : handleAddEndpoint()}
           />
        );
      case 'blueprint':
        return <BlueprintView project={project} />;
      case 'settings':
        return <SettingsScreen settings={settings} onSave={setSettings} />;
      default:
        return null;
    }
  };

  const handleFlowDelete = (type: ResourceType, id: string) => {
    if (type === 'postType') handleDeleteResource(id);
    else handleDeleteEndpoint(id);
  };

  const editingCpt = editingResource?.type === 'postType' ? project.postTypes.find(pt => pt.id === editingResource.id) : null;
  const editingEndpoint = editingResource?.type === 'endpoint' ? project.customEndpoints.find(ep => ep.id === editingResource.id) : null;

  return (
    <div className="flex h-screen bg-slate-900 text-slate-100 overflow-hidden font-sans">

      <Sidebar 
        project={project}
        currentView={currentView}
        selection={editingResource || { type: 'postType', id: '' }}
        isTerminalOpen={isTerminalOpen}
        onSelect={handleSelect}
        onViewChange={handleViewChange}
        onAddResource={handleAddResource}
        onAddEndpoint={handleAddEndpoint}
        onToggleTerminal={() => setIsTerminalOpen(!isTerminalOpen)}
        onOpenAI={() => setAIModalOpen(true)}
      />

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0f111a] relative">
        {renderMainContent()}
        {isTerminalOpen && <Terminal onClose={() => setIsTerminalOpen(false)} />}
      </div>

      {/* Editor Modal Overlay */}
      <EditorModal 
        isOpen={!!editingResource} 
        onClose={() => setEditingResource(null)}
        title={editingCpt ? `Edit Model: ${editingCpt.singularName}` : editingEndpoint ? `Edit Route: ${editingEndpoint.route}` : "Editor"}
      >
        {editingCpt && (
          <ResourceEditor 
            cpt={editingCpt} 
            allTaxonomies={project.taxonomies}
            onChange={handleUpdateResource}
            onDelete={() => handleDeleteResource(editingCpt.id)}
          />
        )}
        {editingEndpoint && (
          <EndpointEditor
            endpoint={editingEndpoint}
            namespace={project.namespace}
            postTypes={project.postTypes}
            onChange={handleUpdateEndpoint}
            onDelete={() => handleDeleteEndpoint(editingEndpoint.id)}
          />
        )}
      </EditorModal>

      {isAIModalOpen && (
        <AIAssistant 
          project={project}
          settings={settings}
          onApply={handleAIApply} 
          onClose={() => setAIModalOpen(false)} 
        />
      )}
    </div>
  );
};

export default App;

export enum FieldType {
  STRING = 'string',
  INTEGER = 'integer',
  NUMBER = 'number',
  BOOLEAN = 'boolean',
  ARRAY = 'array',
  RELATIONSHIP = 'relationship',
}

export interface MetaField {
  id: string;
  key: string;
  label: string;
  type: FieldType;
  description: string;
  required: boolean;
  showInRest: boolean;
  targetPostType?: string; // For relationship types
}

export interface Taxonomy {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  hierarchical: boolean;
  showInRest: boolean;
  connectedPostTypes: string[]; // CPT slugs
}

export interface CustomPostType {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  description: string;
  icon: string; // Dashicon class or similar
  supports: string[]; // title, editor, thumbnail, etc.
  taxonomies: string[]; // Slugs of connected taxonomies
  metaFields: MetaField[];
  showInRest: boolean;
  restBase: string;
}

export type EndpointMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';

export interface EndpointParameter {
  id: string;
  key: string;
  required: boolean;
  type: string;
  description: string;
}

export interface StorageMapping {
  enabled: boolean;
  targetCptSlug: string;
  // Maps param.key -> metaField.key
  fieldMapping: Record<string, string>;
}

export interface CustomEndpoint {
  id: string;
  route: string; // e.g., /checkout/process
  method: EndpointMethod;
  callbackFunction: string;
  description: string;
  parameters: EndpointParameter[];
  hookName?: string; // Optional custom action to fire
  storage?: StorageMapping;
  customPhp?: string; // Custom execution logic
}

export interface ProjectState {
  name: string;
  namespace: string;
  postTypes: CustomPostType[];
  taxonomies: Taxonomy[];
  customEndpoints: CustomEndpoint[];
}

export type ViewMode = 'editor' | 'openapi' | 'php' | 'flow' | 'settings' | 'blueprint';
export type ResourceType = 'postType' | 'endpoint' | 'taxonomy';

// For UI Context Menus
