export const generateOpenAPI = (project: ProjectState): string => {
  const paths: any = {};
  const schemas: any = {};

  // 1. CPT Paths
  project.postTypes.forEach((cpt) => {
    if (!cpt.showInRest) return;

    // Define Schema
    const properties: any = {
      id: { type: 'integer', readOnly: true },
      date: { type: 'string', format: 'date-time' },
      status: { type: 'string' },
      type: { type: 'string' },
      link: { type: 'string', format: 'uri', readOnly: true },
      title: { 
        type: 'object', 
        properties: { rendered: { type: 'string' } } 
      },
    };

    if (cpt.supports.includes('editor')) {
      properties.content = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    if (cpt.supports.includes('excerpt')) {
      properties.excerpt = { 
        type: 'object', 
        properties: { rendered: { type: 'string' }, protected: { type: 'boolean' } } 
      };
    }

    // Custom Fields
    cpt.metaFields.forEach(field => {
      if (field.showInRest) {
        properties[field.key] = {
          type: field.type === FieldType.RELATIONSHIP ? 'integer' : field.type,
          description: field.description
        };
      }
    });

    // Associated Taxonomies
    cpt.taxonomies.forEach(taxSlug => {
       properties[taxSlug] = {
         type: 'array',
         items: { type: 'integer' },
         description: `IDs of ${taxSlug} terms assigned to the post.`
       };
    });

    schemas[cpt.singularName] = {
      type: 'object',
      properties: properties
    };

    // Define Paths
    const pathBase = `/wp/v2/${cpt.restBase}`;

    // Collection Endpoint
    paths[pathBase] = {
      get: {
        summary: `Retrieve a list of ${cpt.pluralName}`,
        tags: [cpt.pluralName],
        responses: {
          '200': {
            description: `List of ${cpt.pluralName}`,
            content: {
              'application/json': {
                schema: {
                  type: 'array',
                  items: { $ref: `#/components/schemas/${cpt.singularName}` }
                }
              }
            }
          }
        }
      },
      post: {
        summary: `Create a new ${cpt.singularName}`,
        tags: [cpt.pluralName],
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: { $ref: `#/components/schemas/${cpt.singularName}` }
            }
          }
        },
        responses: {
          '201': {
            description: `${cpt.singularName} created`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      }
    };

    // Single Endpoint
    paths[`${pathBase}/{id}`] = {
      get: {
        summary: `Retrieve a single ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
            description: `A single ${cpt.singularName}`,
            content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
      post: {
        summary: `Update a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        requestBody: {
           content: {
             'application/json': {
               schema: { $ref: `#/components/schemas/${cpt.singularName}` }
             }
           }
        },
        responses: {
          '200': {
            description: `${cpt.singularName} updated`,
             content: {
              'application/json': {
                schema: { $ref: `#/components/schemas/${cpt.singularName}` }
              }
            }
          }
        }
      },
       delete: {
        summary: `Delete a ${cpt.singularName}`,
        tags: [cpt.pluralName],
        parameters: [{
          name: 'id',
          in: 'path',
          required: true,
          schema: { type: 'integer' }
        }],
        responses: {
          '200': {
             description: `${cpt.singularName} deleted`,
          }
        }
      }
    };
  });

  // 2. Custom Endpoint Paths
  project.customEndpoints.forEach(endpoint => {
    const route = `/${project.namespace}${endpoint.route.startsWith('/') ? endpoint.route : '/' + endpoint.route}`;

    // Initialize path if not exists
    if (!paths[route]) {
      paths[route] = {};
    }

    const parameters = endpoint.parameters.map(p => ({
      name: p.key,
      in: endpoint.method === 'GET' ? 'query' : 'body', // Simplified
      required: p.required,
      description: p.description,
      schema: { type: p.type }
    }));

    paths[route][endpoint.method.toLowerCase()] = {
      summary: endpoint.description || `Custom endpoint for ${endpoint.route}`,
      tags: ['Custom Endpoints'],
      parameters: endpoint.method === 'GET' ? parameters : [],
      requestBody: endpoint.method !== 'GET' && parameters.length > 0 ? {
        content: {
          'application/json': {
            schema: {
              type: 'object',
              properties: endpoint.parameters.reduce((acc: any, p) => {
                acc[p.key] = { type: p.type, description: p.description };
                return acc;
              }, {})
            }
          }
        }
      } : undefined,
      responses: {
        '200': {
          description: 'Successful response',
          content: {
            'application/json': {
              schema: { type: 'object' }
            }
          }
        }
      }
    };
  });

  const spec = {
    openapi: '3.0.0',
    info: {
      title: project.name,
      version: '1.0.0',
      description: `Generated REST API for ${project.name}`
    },
    paths: paths,
    components: {
      schemas: schemas
    }
  };

  return JSON.stringify(spec, null, 2);
};

export enum FieldType {
  STRING = 'string',
  INTEGER = 'integer',
  NUMBER = 'number',
  BOOLEAN = 'boolean',
  ARRAY = 'array',
  RELATIONSHIP = 'relationship',
  REPEATER = 'repeater',
}

export interface MetaField {
  id: string;
  key: string;
  label: string;
  type: FieldType;
  description: string;
  required: boolean;
  showInRest: boolean;
  targetPostType?: string; // For relationship types
  subFields?: MetaField[]; // For repeater types
}

export interface Taxonomy {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  hierarchical: boolean;
  showInRest: boolean;
  connectedPostTypes: string[]; // CPT slugs
  ui?: { x: number; y: number };
}

export interface CustomPostType {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  description: string;
  icon: string; 
  supports: string[];
  taxonomies: string[]; 
  metaFields: MetaField[];
  showInRest: boolean;
  restBase: string;
  ui?: { x: number; y: number };
}

export type EndpointMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';

export interface EndpointParameter {
  id: string;
  key: string;
  required: boolean;
  type: string;
  description: string;
}

export interface StorageMapping {
  enabled: boolean;
  targetCptSlug: string;
  fieldMapping: Record<string, string>;
}

export interface CustomEndpoint {
  id: string;
  route: string;
  method: EndpointMethod;
  callbackFunction: string;
  description: string;
  parameters: EndpointParameter[];
  hookName?: string;
  storage?: StorageMapping;
  customPhp?: string;
  ui?: { x: number; y: number };
}

export interface GlobalHelper {
  id: string;
  name: string;
  parameters: string[];
  phpCode: string;
}

export interface ProjectState {
  name: string;
  namespace: string;
  postTypes: CustomPostType[];
  taxonomies: Taxonomy[];
  customEndpoints: CustomEndpoint[];
  globalHelpers?: GlobalHelper[];
}

export type ViewMode = 'editor' | 'openapi' | 'php' | 'flow' | 'settings' | 'blueprint';
export type ResourceType = 'postType' | 'endpoint' | 'taxonomy' | 'helper';

export interface ContextMenuState {
  visible: boolean;
  x: number;
  y: number;
  type: ResourceType | null;
  id: string | null;
}

export enum AIProvider {
  GEMINI = 'gemini',
  CHROME_LOCAL = 'chrome_local'
}

export interface AppSettings {
  provider: AIProvider;
  apiKey: string;
  model: string;
  temperature: number;
}

export type LogLevel = 'info' | 'success' | 'warning' | 'error';

export interface LogEntry {
  id: string;
  timestamp: Date;
  level: LogLevel;
  message: string;
  details?: any;
}

