          className="flex-1 w-full bg-[#1e1e1e] text-blue-100 font-mono text-sm p-4 outline-none resize-none custom-scrollbar leading-relaxed"
          placeholder="// Enter custom PHP logic here..."
          spellCheck={false}
        />
      </div>

      {/* Context Sidebar */}
      <div className="w-64 bg-[#252526] border-l border-slate-700 flex flex-col">
        <div className="p-3 border-b border-slate-700 font-semibold text-xs text-slate-300 uppercase tracking-wider">
