                    <button
                        key={param.id}
                        onClick={() => insertSnippet(`$${param.key} = $request->get_param('${param.key}');`)}
                        className="w-full text-left text-xs font-mono text-pink-300 hover:bg-slate-700 p-1.5 rounded truncate transition-colors group"
                        title={`Click to insert $${param.key}`}
                    >
                        <span className="text-pink-500">$</span>{param.key}
                    </button>
                ))}
                {parameters.length === 0 && <span className="text-xs text-slate-600 italic px-2">No parameters</span>}
            </div>

            {/* Storage Context */}
            {targetCpt && (
                <div>
                    <div className="text-[10px] text-slate-500 mb-2 font-bold flex items-center gap-1">
                        <Box size={10} /> TARGET OBJECT ({targetCpt.slug})
                    </div>
                    <button
                        onClick={() => insertSnippet(`$post_id = $created_id; // ID of the created ${targetCpt.singularName}`)}
                        className="w-full text-left text-xs font-mono text-indigo-300 hover:bg-slate-700 p-1.5 rounded truncate transition-colors"
                    >
                        <span className="text-indigo-500">$</span>post_id
                    </button>
                    {targetCpt.metaFields.map(field => (
                        <button
                            key={field.id}
                            onClick={() => insertSnippet(`update_post_meta($post_id, '${field.key}', $value);`)}
                            className="w-full text-left text-xs font-mono text-slate-400 hover:bg-slate-700 p-1.5 rounded truncate transition-colors"
                        >
                            meta: {field.key}
                        </button>
                    ))}
                </div>
            )}

            {/* Snippets */}
            <div>
                <div className="text-[10px] text-slate-500 mb-2 font-bold flex items-center gap-1">
                    <Play size={10} /> SNIPPETS
                </div>
                <button
                    onClick={() => insertSnippet(`if ( is_wp_error( $result ) ) {\n    return new WP_Error( 'error', 'Message', array( 'status' => 500 ) );\n}`)}
                    className="w-full text-left text-xs text-slate-300 hover:bg-slate-700 p-1.5 rounded transition-colors mb-1"
                >
                    Error Handling
                </button>
                <button
                    onClick={() => insertSnippet(`$user_id = get_current_user_id();`)}
                    className="w-full text-left text-xs text-slate-300 hover:bg-slate-700 p-1.5 rounded transition-colors"
                >
                    Get User ID
                </button>
            </div>

        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { CustomEndpoint, EndpointMethod, EndpointParameter, CustomPostType } from '../types';
import { Trash2, Settings, Plus, Network, Database, ArrowRight } from 'lucide-react';
import { CodeEditor } from './CodeEditor';

interface EndpointEditorProps {
  endpoint: CustomEndpoint;
  namespace: string;
  postTypes: CustomPostType[];
  onChange: (updated: CustomEndpoint) => void;
  onDelete: () => void;
}

export const EndpointEditor: React.FC<EndpointEditorProps> = ({ endpoint, namespace, postTypes, onChange, onDelete }) => {

  const handleParamChange = (id: string, changes: Partial<EndpointParameter>) => {
    const updatedParams = endpoint.parameters.map(p => p.id === id ? { ...p, ...changes } : p);
    onChange({ ...endpoint, parameters: updatedParams });
  };

  const addParam = () => {
    const newParam: EndpointParameter = {
      id: `param_${Date.now()}`,
      key: 'new_param',
      type: 'string',
      required: false,
      description: ''
    };
    onChange({ ...endpoint, parameters: [...endpoint.parameters, newParam] });
  };

  const removeParam = (id: string) => {
    onChange({ ...endpoint, parameters: endpoint.parameters.filter(p => p.id !== id) });
  };

  const handleStorageToggle = (enabled: boolean) => {
    onChange({
      ...endpoint,
      storage: {
        enabled,
        targetCptSlug: endpoint.storage?.targetCptSlug || (postTypes[0]?.slug || ''),
        fieldMapping: endpoint.storage?.fieldMapping || {}
      }
    });
  };

  const handleMappingChange = (paramKey: string, metaKey: string) => {
    if (!endpoint.storage) return;
    const newMapping = { ...endpoint.storage.fieldMapping };
    if (metaKey === '') {
      delete newMapping[paramKey];
    } else {
      newMapping[paramKey] = metaKey;
    }
    onChange({
      ...endpoint,
      storage: {
        ...endpoint.storage,
        fieldMapping: newMapping
      }
    });
  };

  const methods: EndpointMethod[] = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'];
  const targetCpt = postTypes.find(pt => pt.slug === endpoint.storage?.targetCptSlug);

  return (
    <div className="h-full overflow-y-auto p-8 custom-scrollbar">
      <div className="flex justify-between items-start mb-8">
        <div>
          <h2 className="text-3xl font-bold text-white mb-2 flex items-center gap-2">
            <Network className="text-pink-500" size={32} />
            {endpoint.route}
          </h2>
          <p className="text-slate-400">Custom REST API Route Definition</p>
        </div>
        <button 
          onClick={onDelete}
          className="text-red-400 hover:text-red-300 hover:bg-red-900/20 px-3 py-2 rounded-lg transition-colors flex items-center gap-2"
        >
          <Trash2 size={18} />
          Delete Endpoint
        </button>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

        {/* Main Route Settings */}
        <div className="xl:col-span-2 space-y-8">

          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 space-y-6">
            <h3 className="text-lg font-semibold text-slate-200 flex items-center gap-2">
              <Settings size={20} className="text-pink-400"/> Route Configuration
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="col-span-1 md:col-span-2">
                <label className="block text-sm font-medium text-slate-400 mb-1">Route Path</label>
                <div className="flex items-center">
                  <span className="bg-slate-700 text-slate-300 px-3 py-2 rounded-l border border-r-0 border-slate-600 font-mono text-sm">
                    /{namespace}/
                  </span>
                  <input 
                    type="text" 
                    value={endpoint.route.startsWith('/') ? endpoint.route.substring(1) : endpoint.route} 
                    onChange={e => onChange({...endpoint, route: '/' + e.target.value})}
                    placeholder="my-resource/action"
                    className="flex-1 bg-slate-900 border border-slate-600 rounded-r px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 outline-none font-mono text-sm"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">HTTP Method</label>
                <div className="flex flex-wrap gap-2">
                  {methods.map(m => (
                    <button
                      key={m}
                      onClick={() => onChange({ ...endpoint, method: m })}
                      className={`px-3 py-1.5 rounded text-xs font-bold transition-all ${endpoint.method === m 
                        ? 'bg-pink-600 text-white shadow-lg shadow-pink-500/30' 
                        : 'bg-slate-700 text-slate-400 hover:bg-slate-600'}`}
                    >
                      {m}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Callback Function</label>
                <input 
                  type="text" 
                  value={endpoint.callbackFunction} 
                  onChange={e => onChange({...endpoint, callbackFunction: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 outline-none font-mono text-sm"
                />
              </div>

              <div className="col-span-1 md:col-span-2">
                <label className="block text-sm font-medium text-slate-400 mb-1">Description</label>
                <input 
                  type="text" 
                  value={endpoint.description} 
                  onChange={e => onChange({...endpoint, description: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 outline-none"
                />
              </div>
            </div>
          </div>

          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700">
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-lg font-semibold text-slate-200">Request Parameters</h3>
               <button 
                 onClick={addParam}
                 className="flex items-center gap-1 text-sm bg-pink-600 hover:bg-pink-700 text-white px-3 py-1.5 rounded transition-colors"
               >
                 <Plus size={16} /> Add Parameter
               </button>
             </div>

             <div className="space-y-3">
               {endpoint.parameters.length === 0 && (
                  <p className="text-slate-500 text-center py-4 italic">No parameters defined.</p>
               )}
               {endpoint.parameters.map((param) => (
                 <div key={param.id} className="bg-slate-900/50 rounded-lg p-3 border border-slate-700 flex gap-4 items-center">
                   <div className="grid grid-cols-12 gap-3 flex-1">
                     <div className="col-span-3">
                        <input 
                          type="text" 
                          placeholder="key"
                          value={param.key}
                          onChange={e => handleParamChange(param.id, { key: e.target.value })}
                          className="w-full bg-slate-800 border border-slate-600 rounded px-2 py-1 text-sm text-white font-mono"
                        />
                     </div>
                     <div className="col-span-2">
                        <select 
                          value={param.type}
                          onChange={e => handleParamChange(param.id, { type: e.target.value })}
                          className="w-full bg-slate-800 border border-slate-600 rounded px-2 py-1 text-sm text-white"
                        >
                          <option value="string">string</option>
                          <option value="integer">integer</option>
                          <option value="boolean">boolean</option>
                        </select>
                     </div>
                     <div className="col-span-5">
                        <input 
                          type="text" 
                          placeholder="Description"
                          value={param.description}
                          onChange={e => handleParamChange(param.id, { description: e.target.value })}
                          className="w-full bg-slate-800 border border-slate-600 rounded px-2 py-1 text-sm text-white"
                        />
                     </div>
                     <div className="col-span-2 flex items-center justify-center">
                         <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-400 select-none">
                        <input 
                          type="checkbox" 
                          checked={param.required}
                          onChange={e => handleParamChange(param.id, { required: e.target.checked })}
                          className="rounded bg-slate-700 border-slate-600 text-pink-500 focus:ring-0"
                        />
                        Required
                      </label>
                     </div>
                   </div>
                    <button 
                       onClick={() => removeParam(param.id)}
                       className="text-slate-500 hover:text-red-400 transition-colors"
                     >
                       <Trash2 size={18} />
                     </button>
                 </div>
               ))}
             </div>
          </div>

          <CodeEditor 
            value={endpoint.customPhp || ''}
            onChange={(val) => onChange({...endpoint, customPhp: val})}
            parameters={endpoint.parameters}
            targetCptSlug={endpoint.storage?.enabled ? endpoint.storage.targetCptSlug : undefined}
            postTypes={postTypes}
          />
        </div>

        {/* Sidebar Settings */}
        <div className="space-y-6">

          {/* Action Hooks */}
          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700">
            <h3 className="text-sm font-bold text-slate-300 uppercase tracking-wider mb-4">Hooks & Actions</h3>
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1">Custom Action Hook</label>
              <input 
                type="text" 
                value={endpoint.hookName || ''} 
                onChange={e => onChange({...endpoint, hookName: e.target.value})}
                placeholder="my_custom_process_action"
                className="w-full bg-slate-900 border border-slate-600 rounded px-3 py-2 text-white focus:ring-2 focus:ring-pink-500 outline-none font-mono text-sm"
              />
            </div>
          </div>

          {/* Logic & Storage Flow */}
          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
               <Database size={100} />
             </div>

             <div className="flex items-center justify-between mb-4">
               <h3 className="text-sm font-bold text-slate-300 uppercase tracking-wider">Storage Flow</h3>
               <label className="relative inline-flex items-center cursor-pointer">
                <input 
                  type="checkbox" 
                  className="sr-only peer" 
                  checked={endpoint.storage?.enabled || false}
                  onChange={e => handleStorageToggle(e.target.checked)}
                />
                <div className="w-9 h-5 bg-slate-600 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-pink-600"></div>
              </label>
             </div>

             {endpoint.storage?.enabled ? (
               <div className="space-y-4">
                  <div>
                    <label className="block text-xs font-medium text-slate-400 mb-1">Target Post Type</label>
                    <select
                      value={endpoint.storage.targetCptSlug}
                      onChange={e => onChange({
                          ...endpoint,
                          storage: {
                              ...endpoint.storage!,
                              targetCptSlug: e.target.value,
                              fieldMapping: {}
                          }
                      })}
                      className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1.5 text-sm text-white"
                    >
                      {postTypes.map(pt => (
                        <option key={pt.slug} value={pt.slug}>{pt.singularName}</option>
                      ))}
                    </select>
                  </div>

                  {targetCpt && (
                    <div className="bg-slate-900/50 rounded p-3 border border-slate-700">
                      <p className="text-xs text-slate-400 mb-2 font-semibold">Map Parameters to Fields</p>
                      {endpoint.parameters.map(param => (
                        <div key={param.id} className="flex items-center justify-between gap-2 mb-2 last:mb-0">
                          <span className="text-xs font-mono text-pink-300 w-1/3 truncate" title={param.key}>{param.key}</span>
                          <ArrowRight size={12} className="text-slate-600" />
                          <select
                            value={endpoint.storage?.fieldMapping[param.key] || ''}
                            onChange={e => handleMappingChange(param.key, e.target.value)}
                            className="w-1/2 bg-slate-800 border border-slate-600 rounded px-1 py-1 text-xs text-white"
                          >
                            <option value="">(Ignore)</option>
                            <option value="post_title">Post Title</option>
                            <option value="post_content">Post Content</option>
                            {targetCpt.metaFields.map(mf => (
                              <option key={mf.key} value={mf.key}>{mf.label} ({mf.key})</option>
                            ))}
                          </select>
                        </div>
                      ))}
                    </div>
                  )}
               </div>
             ) : (
               <p className="text-xs text-slate-500">
                 Enable this to automatically save request data into a Custom Post Type.
               </p>
             )}
          </div>

        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { CustomPostType, FieldType, MetaField, Taxonomy } from '../types';
import { DEFAULT_SUPPORTS_OPTIONS } from '../constants';
import { Plus, Trash2, Settings, Link as LinkIcon, Layers, ChevronRight, ChevronDown } from 'lucide-react';

interface ResourceEditorProps {
  cpt: CustomPostType;
  allTaxonomies: Taxonomy[];
  allPostTypes?: CustomPostType[];
  onChange: (updatedCpt: CustomPostType) => void;
  onDelete: () => void;
}

export const ResourceEditor: React.FC<ResourceEditorProps> = ({ cpt, allTaxonomies, allPostTypes = [], onChange, onDelete }) => {
  const [expandedRepeater, setExpandedRepeater] = useState<string | null>(null);

  const handleFieldChange = (fieldId: string, changes: Partial<MetaField>) => {
    const updateFieldsRecursive = (fields: MetaField[]): MetaField[] => {
      return fields.map(f => {
        if (f.id === fieldId) return { ...f, ...changes };
        if (f.subFields) return { ...f, subFields: updateFieldsRecursive(f.subFields) };
        return f;
      });
    };
    onChange({ ...cpt, metaFields: updateFieldsRecursive(cpt.metaFields) });
  };

  const addField = (parentFieldId?: string) => {
    const newField: MetaField = {
      id: `field_${Date.now()}`,
      key: 'new_field',
      label: 'New Field',
      type: FieldType.STRING,
      description: '',
      required: false,
      showInRest: true,
      subFields: [],
    };

    if (parentFieldId) {
       // Add to subfields
       const addSubField = (fields: MetaField[]): MetaField[] => {
         return fields.map(f => {
           if (f.id === parentFieldId) {
             return { ...f, subFields: [...(f.subFields || []), newField] };
           }
           if (f.subFields) return { ...f, subFields: addSubField(f.subFields) };
           return f;
         });
       };
       onChange({ ...cpt, metaFields: addSubField(cpt.metaFields) });
    } else {
       onChange({ ...cpt, metaFields: [...cpt.metaFields, newField] });
    }
  };

  const removeField = (id: string) => {
    const removeRecursive = (fields: MetaField[]): MetaField[] => {
      return fields.filter(f => f.id !== id).map(f => ({
        ...f,
        subFields: f.subFields ? removeRecursive(f.subFields) : undefined
      }));
    };
    onChange({ ...cpt, metaFields: removeRecursive(cpt.metaFields) });
  };

  const toggleSupport = (option: string) => {
    const newSupports = cpt.supports.includes(option)
      ? cpt.supports.filter(s => s !== option)
      : [...cpt.supports, option];
    onChange({ ...cpt, supports: newSupports });
  };

  const toggleTaxonomy = (taxSlug: string) => {
    const newTaxonomies = cpt.taxonomies.includes(taxSlug)
      ? cpt.taxonomies.filter(t => t !== taxSlug)
      : [...cpt.taxonomies, taxSlug];
    onChange({ ...cpt, taxonomies: newTaxonomies });
  };

  const renderFields = (fields: MetaField[], level = 0) => {
    return fields.map((field) => (
        <div key={field.id} className={`bg-slate-900/50 rounded-lg p-4 border border-slate-700 group hover:border-slate-600 transition-colors mb-3 ${level > 0 ? 'ml-8 border-l-4 border-l-indigo-500/50' : ''}`}>
          <div className="flex gap-4 items-start">
            <div className="flex-1 grid grid-cols-12 gap-4">
              <div className="col-span-3">
                 <label className="text-xs text-slate-500 block mb-1">Key</label>
                 <input 
                   type="text" 
                   value={field.key}
                   onChange={e => handleFieldChange(field.id, { key: e.target.value })}
                   className="w-full bg-slate-800 border border-slate-600 rounded px-2 py-1 text-sm text-white font-mono"
                 />
              </div>
              <div className="col-span-3">
                 <label className="text-xs text-slate-500 block mb-1">Type</label>
                 <select 
                   value={field.type}
                   onChange={e => handleFieldChange(field.id, { type: e.target.value as FieldType })}
                   className="w-full bg-slate-800 border border-slate-600 rounded px-2 py-1 text-sm text-white"
                 >
                   {Object.values(FieldType).map(t => <option key={t} value={t}>{t}</option>)}
                 </select>
              </div>

              {field.type === FieldType.RELATIONSHIP && (
                <div className="col-span-3 animate-in fade-in">
                   <label className="text-xs text-indigo-400 block mb-1 flex items-center gap-1">
                     <LinkIcon size={10} /> Target CPT
                   </label>
                   <select 
                     value={field.targetPostType || ''}
                     onChange={e => handleFieldChange(field.id, { targetPostType: e.target.value })}
                     className="w-full bg-indigo-900/20 border border-indigo-500/30 rounded px-2 py-1 text-sm text-indigo-200"
                   >
                     <option value="">Select Target...</option>
                     {allPostTypes.filter(p => p.id !== cpt.id).map(p => (
                       <option key={p.slug} value={p.slug}>{p.singularName}</option>
                     ))}
                   </select>
                </div>
              )}

              <div className={field.type === FieldType.RELATIONSHIP ? "col-span-3" : "col-span-6"}>
                 <label className="text-xs text-slate-500 block mb-1">Description</label>
                 <input 
                   type="text" 
                   value={field.description}
                   onChange={e => handleFieldChange(field.id, { description: e.target.value })}
                   className="w-full bg-slate-800 border border-slate-600 rounded px-2 py-1 text-sm text-white"
                 />
              </div>
            </div>
            <button 
              onClick={() => removeField(field.id)}
              className="mt-6 text-slate-500 hover:text-red-400 transition-colors"
            >
              <Trash2 size={18} />
            </button>
          </div>

          <div className="mt-3 flex items-center justify-between">
            <div className="flex items-center gap-4">
                <label className="flex items-center gap-2 cursor-pointer text-sm text-slate-400 select-none">
                <input 
                    type="checkbox" 
                    checked={field.required}
                    onChange={e => handleFieldChange(field.id, { required: e.target.checked })}
                    className="rounded bg-slate-700 border-slate-600 text-indigo-500 focus:ring-0"
                />
                Required
                </label>
                <label className="flex items-center gap-2 cursor-pointer text-sm text-slate-400 select-none">
                <input 
                    type="checkbox" 
                    checked={field.showInRest}
                    onChange={e => handleFieldChange(field.id, { showInRest: e.target.checked })}
                    className="rounded bg-slate-700 border-slate-600 text-indigo-500 focus:ring-0"
                />
                Show in REST API
                </label>
            </div>

            {field.type === FieldType.REPEATER && (
                <button 
                  onClick={() => setExpandedRepeater(expandedRepeater === field.id ? null : field.id)}
                  className="text-xs flex items-center gap-1 text-indigo-400 hover:text-indigo-300"
                >
                    <Layers size={14} /> 
                    {expandedRepeater === field.id ? 'Collapse Sub-fields' : `Manage Sub-fields (${field.subFields?.length || 0})`}
                    {expandedRepeater === field.id ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                </button>
            )}
          </div>

          {/* Repeater Subfields Area */}
          {field.type === FieldType.REPEATER && expandedRepeater === field.id && (
             <div className="mt-4 pt-4 border-t border-slate-800 bg-black/20 -mx-4 px-4 pb-2">
                 <div className="flex items-center justify-between mb-2">
                    <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Sub-Fields for {field.label}</span>
                    <button onClick={() => addField(field.id)} className="text-xs bg-indigo-600 px-2 py-1 rounded text-white flex items-center gap-1">
                        <Plus size={12}/> Add Sub-field
                    </button>
                 </div>
                 {renderFields(field.subFields || [], level + 1)}
             </div>
          )}
        </div>
      ));
  }

  return (
    <div className="h-full overflow-y-auto p-8 custom-scrollbar">
      <div className="flex justify-between items-start mb-8">
        <div>
          <h2 className="text-3xl font-bold text-white mb-2">{cpt.singularName}</h2>
          <p className="text-slate-400">Post Type Configuration</p>
        </div>
        <button 
          onClick={onDelete}
          className="text-red-400 hover:text-red-300 hover:bg-red-900/20 px-3 py-2 rounded-lg transition-colors flex items-center gap-2"
        >
          <Trash2 size={18} />
          Delete Resource
        </button>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">

        {/* Main Settings */}
        <div className="xl:col-span-2 space-y-8">

          <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 space-y-6">
            <h3 className="text-lg font-semibold text-slate-200 flex items-center gap-2">
              <Settings size={20} className="text-indigo-400"/> General Settings
            </h3>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-1">Singular Name</label>
                <input 
                  type="text" 
                  value={cpt.singularName} 
                  onChange={e => onChange({...cpt, singularName: e.target.value})}
