import React, { useRef, useEffect, useState } from 'react';
import { ProjectState, ResourceType, ContextMenuState, FieldType } from '../types';
import { Network, Database, Activity, Box, Edit, Trash2, Copy, Plus, Code, Link as LinkIcon, Move } from 'lucide-react';

interface FlowDesignerProps {
  project: ProjectState;
  onSelect: (type: ResourceType, id: string) => void;
  onDelete: (type: ResourceType, id: string) => void;
  onDuplicate: (type: ResourceType, id: string) => void;
  onAdd: (type: ResourceType) => void;
}

// Helper for curved lines
const getBezierPath = (x1: number, y1: number, x2: number, y2: number) => {
  const dx = Math.abs(x2 - x1);
  const curvature = Math.min(dx * 0.5, 150); // Dynamic curvature
  return `M ${x1} ${y1} C ${x1 + curvature} ${y1}, ${x2 - curvature} ${y2}, ${x2} ${y2}`;
};

export const FlowDesigner: React.FC<FlowDesignerProps> = ({ project, onSelect, onDelete, onDuplicate, onAdd }) => {
  const { postTypes, customEndpoints } = project;
  const containerRef = useRef<HTMLDivElement>(null);

  // Canvas State
  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDraggingCanvas, setIsDraggingCanvas] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // Node Dragging State
  const [draggingNode, setDraggingNode] = useState<{ type: ResourceType, id: string } | null>(null);
  const [nodePositions, setNodePositions] = useState<Record<string, { x: number, y: number }>>({});

  // Context Menu
  const [contextMenu, setContextMenu] = useState<ContextMenuState>({ visible: false, x: 0, y: 0, type: null, id: null });

  // Initialize positions if not present
  useEffect(() => {
    const newPositions = { ...nodePositions };
    let hasChanges = false;

    // Grid layout for initialization
    customEndpoints.forEach((ep, i) => {
      if (!newPositions[ep.id]) {
        newPositions[ep.id] = { x: 100, y: 100 + (i * 150) };
        hasChanges = true;
      }
    });

    postTypes.forEach((pt, i) => {
      if (!newPositions[pt.id]) {
        newPositions[pt.id] = { x: 800, y: 100 + (i * 200) };
        hasChanges = true;
      }
    });

    if (hasChanges) setNodePositions(newPositions);
  }, [project.postTypes.length, project.customEndpoints.length]);

  // Canvas Drag Handlers
  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.target === containerRef.current || (e.target as HTMLElement).tagName === 'svg') {
      setIsDraggingCanvas(true);
      setDragStart({ x: e.clientX - offset.x, y: e.clientY - offset.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDraggingCanvas) {
      setOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
    } else if (draggingNode) {
      // Calculate delta in canvas space
      const rect = containerRef.current?.getBoundingClientRect();
      if (!rect) return;

      const newX = (e.clientX - rect.left - offset.x) / scale;
      const newY = (e.clientY - rect.top - offset.y) / scale;

      setNodePositions(prev => ({
        ...prev,
        [draggingNode.id]: { x: newX - 100, y: newY - 40 } // Center offset approximation
      }));
    }
  };

  const handleMouseUp = () => {
    setIsDraggingCanvas(false);
    setDraggingNode(null);
  };

  const handleWheel = (e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
       e.preventDefault();
       const s = Math.min(Math.max(0.5, scale + e.deltaY * -0.001), 2);
       setScale(s);
    }
  };

  // Node Drag Start
  const startDragNode = (e: React.MouseEvent, type: ResourceType, id: string) => {
    e.stopPropagation();
    setDraggingNode({ type, id });
  };

  // Render Connections
  const renderConnections = () => {
    const lines: React.ReactElement[] = [];

    // Endpoint -> Storage Logic -> CPT
    customEndpoints.forEach(ep => {
      const startPos = nodePositions[ep.id];
      if (!startPos) return;

      const endpointRight = { x: startPos.x + 280, y: startPos.y + 50 }; // approx width/height center

      // 1. Endpoint -> Logic (Internal visual only, maybe just a small stub if not connecting to storage)

      // 2. Endpoint -> CPT (Storage)
      if (ep.storage?.enabled && ep.storage.targetCptSlug) {
        const targetCpt = postTypes.find(pt => pt.slug === ep.storage?.targetCptSlug);
        if (targetCpt && nodePositions[targetCpt.id]) {
           const targetPos = nodePositions[targetCpt.id];
           const targetLeft = { x: targetPos.x, y: targetPos.y + 60 };

           lines.push(
             <g key={`flow_${ep.id}_${targetCpt.id}`}>
               <path 
                 d={getBezierPath(endpointRight.x, endpointRight.y, targetLeft.x, targetLeft.y)}
                 fill="none"
                 stroke="#10b981" // Green
                 strokeWidth="3"
                 className="opacity-60 animate-pulse"
                 strokeDasharray="5,5"
               />
               <circle cx={targetLeft.x} cy={targetLeft.y} r="4" fill="#10b981" />
             </g>
           );
        }
      }
    });

    // CPT Relationships (Post-to-Post)
    postTypes.forEach(pt => {
        const startPos = nodePositions[pt.id];
        if (!startPos) return;

        pt.metaFields.forEach(field => {
            if (field.type === FieldType.RELATIONSHIP && field.targetPostType) {
                const targetCpt = postTypes.find(p => p.slug === field.targetPostType);
                if (targetCpt && nodePositions[targetCpt.id] && targetCpt.id !== pt.id) {
                    const targetPos = nodePositions[targetCpt.id];
                    const startRight = { x: startPos.x + 250, y: startPos.y + 50 };
                    const targetLeft = { x: targetPos.x, y: targetPos.y + 50 };

                    lines.push(
                        <g key={`rel_${pt.id}_${targetCpt.id}`}>
                            <path 
                                d={getBezierPath(startRight.x, startRight.y, targetLeft.x, targetLeft.y)}
                                fill="none"
                                stroke="#06b6d4" // Cyan
                                strokeWidth="2"
                                className="opacity-40"
                            />
                            <circle cx={startRight.x} cy={startRight.y} r="3" fill="#06b6d4" />
                        </g>
                    );
                }
            }
        });
    });

    return lines;
  };

  return (
    <div 
      className="h-full w-full bg-[#09090b] relative overflow-hidden select-none cursor-grab active:cursor-grabbing" 
      ref={containerRef}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      onClick={() => setContextMenu({ ...contextMenu, visible: false })}
    >
      {/* Background Grid */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-20"
        style={{
           backgroundImage: 'radial-gradient(#4b5563 1px, transparent 1px)',
           backgroundSize: `${20 * scale}px ${20 * scale}px`,
           backgroundPosition: `${offset.x}px ${offset.y}px`
        }}
      />

      {/* Floating Controls */}
      <div className="absolute top-4 left-4 z-50 flex gap-2">
         <div className="bg-slate-800/80 backdrop-blur border border-slate-700 rounded-lg p-2 flex gap-4 text-xs font-mono text-slate-300 shadow-lg">
             <div className="flex items-center gap-2"><Network size={14} className="text-pink-500"/> Route</div>
             <div className="flex items-center gap-2"><Box size={14} className="text-indigo-500"/> Model</div>
             <div className="flex items-center gap-2"><LinkIcon size={14} className="text-cyan-500"/> Relation</div>
             <div className="flex items-center gap-2"><Activity size={14} className="text-green-500"/> Logic Flow</div>
         </div>
      </div>

      <div className="absolute top-4 right-4 z-50 flex flex-col gap-2">
          <button onClick={() => onAdd('endpoint')} className="bg-slate-800 p-2 rounded-lg hover:bg-pink-900/50 text-pink-400 border border-slate-700 shadow-lg" title="Add Endpoint">
            <Network size={20} />
          </button>
          <button onClick={() => onAdd('postType')} className="bg-slate-800 p-2 rounded-lg hover:bg-indigo-900/50 text-indigo-400 border border-slate-700 shadow-lg" title="Add CPT">
            <Box size={20} />
          </button>
          <div className="h-px bg-slate-700 my-1"/>
          <button onClick={() => { setScale(1); setOffset({x:0,y:0}); }} className="bg-slate-800 p-2 rounded-lg hover:bg-slate-700 text-slate-400 border border-slate-700 shadow-lg" title="Reset View">
            <Move size={20} />
          </button>
      </div>

      {/* Canvas Layer */}
      <div 
        className="absolute inset-0 origin-top-left"
        style={{
            transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`
        }}
      >
         <svg className="absolute inset-0 overflow-visible w-full h-full pointer-events-none z-0">
             {renderConnections()}
         </svg>

         {/* Nodes Layer */}
         <div className="relative z-10">

            {/* Endpoints */}
            {customEndpoints.map(ep => (
                <div
                    key={ep.id}
                    className="absolute w-[280px] bg-slate-900/90 backdrop-blur border border-pink-500/30 rounded-lg shadow-xl group hover:border-pink-500 transition-colors"
                    style={{ 
                        left: nodePositions[ep.id]?.x || 0, 
                        top: nodePositions[ep.id]?.y || 0,
                        cursor: 'grab' 
                    }}
                    onMouseDown={(e) => startDragNode(e, 'endpoint', ep.id)}
                    onClick={(e) => { e.stopPropagation(); onSelect('endpoint', ep.id); }}
                    onContextMenu={(e) => { e.preventDefault(); setContextMenu({ visible: true, x: e.clientX, y: e.clientY, type: 'endpoint', id: ep.id }); }}
                >
                    <div className="p-3 border-b border-slate-800 flex justify-between items-center bg-slate-800/50 rounded-t-lg">
                        <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${ep.method === 'GET' ? 'bg-blue-900 text-blue-300' : 'bg-green-900 text-green-300'}`}>{ep.method}</span>
                        <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <Edit size={14} className="text-slate-400 hover:text-white cursor-pointer" onClick={() => onSelect('endpoint', ep.id)}/>
                        </div>
                    </div>
                    <div className="p-4">
                        <div className="font-mono text-sm text-pink-200 truncate font-semibold mb-2" title={ep.route}>{ep.route}</div>
                        {ep.storage?.enabled && (
                            <div className="text-xs text-green-400 flex items-center gap-1 mb-1">
                                <Database size={10} /> Auto-Save Enabled
                            </div>
                        )}
                        {ep.customPhp && (
                            <div className="text-xs text-blue-400 flex items-center gap-1">
                                <Code size={10} /> Custom Logic
                            </div>
                        )}
                        {ep.hookName && (
                            <div className="mt-2 text-[10px] bg-slate-800 p-1 rounded border border-slate-700 text-slate-400 font-mono text-center">
                                do_action('{ep.hookName}')
                            </div>
                        )}
                    </div>
                </div>
            ))}

            {/* Post Types */}
            {postTypes.map(pt => (
                <div
                    key={pt.id}
                    className="absolute w-[250px] bg-slate-900/90 backdrop-blur border border-indigo-500/30 rounded-lg shadow-xl group hover:border-indigo-500 transition-colors"
                    style={{ 
                        left: nodePositions[pt.id]?.x || 0, 
                        top: nodePositions[pt.id]?.y || 0,
                        cursor: 'grab' 
                    }}
                    onMouseDown={(e) => startDragNode(e, 'postType', pt.id)}
                    onClick={(e) => { e.stopPropagation(); onSelect('postType', pt.id); }}
                    onContextMenu={(e) => { e.preventDefault(); setContextMenu({ visible: true, x: e.clientX, y: e.clientY, type: 'postType', id: pt.id }); }}
                >
                    <div className="p-3 border-b border-slate-800 flex justify-between items-center bg-indigo-900/20 rounded-t-lg">
                        <div className="flex items-center gap-2 font-bold text-indigo-300 text-sm">
                             <Box size={16} /> {pt.singularName}
                        </div>
                        <span className="text-[10px] text-slate-500 font-mono">{pt.slug}</span>
                    </div>
                    <div className="p-3 space-y-1">
                        {pt.metaFields.slice(0, 4).map(mf => (
                            <div key={mf.id} className="text-xs flex justify-between items-center text-slate-400">
                                <span>{mf.key}</span>
                                <span className={`text-[10px] px-1 rounded ${
                                    mf.type === FieldType.RELATIONSHIP ? 'bg-cyan-900/50 text-cyan-300' : 
                                    mf.type === FieldType.REPEATER ? 'bg-purple-900/50 text-purple-300' : 'text-slate-600'
                                }`}>
                                    {mf.type}
                                </span>
                            </div>
                        ))}
                        {pt.metaFields.length > 4 && <div className="text-[10px] text-slate-600 italic text-center pt-1">+{pt.metaFields.length - 4} more</div>}
                    </div>
                </div>
            ))}

         </div>
      </div>

       {/* Context Menu */}
       {contextMenu.visible && (
        <div 
          className="fixed bg-[#252526] border border-[#444] rounded-lg shadow-2xl py-1 z-[100] min-w-[160px]"
          style={{ top: contextMenu.y, left: contextMenu.x }}
          onClick={(e) => e.stopPropagation()}
        >
          <button 
            onClick={() => { onSelect(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
            className="w-full text-left px-4 py-2 text-sm text-slate-200 hover:bg-blue-600 hover:text-white flex items-center gap-2"
          >
            <Edit size={14} /> Edit
          </button>
          <button 
             onClick={() => { onDuplicate(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
             className="w-full text-left px-4 py-2 text-sm text-slate-200 hover:bg-blue-600 hover:text-white flex items-center gap-2"
          >
            <Copy size={14} /> Duplicate
          </button>
          <div className="h-px bg-[#444] my-1"></div>
          <button 
             onClick={() => { onDelete(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
             className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-red-900/50 flex items-center gap-2"
          >
            <Trash2 size={14} /> Delete
          </button>
        </div>
      )}
    </div>
  );
};

