import React, { useRef, useEffect, useState } from 'react';
import { ProjectState, ResourceType, ContextMenuState, FieldType } from '../types';
import { Network, Database, Activity, Box, Edit, Trash2, Copy, Plus, Code, Link as LinkIcon, Move, Zap } from 'lucide-react';

interface FlowDesignerProps {
  project: ProjectState;
  onSelect: (type: ResourceType, id: string) => void;
  onDelete: (type: ResourceType, id: string) => void;
  onDuplicate: (type: ResourceType, id: string) => void;
  onAdd: (type: ResourceType) => void;
}

const getBezierPath = (x1: number, y1: number, x2: number, y2: number) => {
  const dx = Math.abs(x2 - x1);
  const curvature = Math.max(dx * 0.4, 50);
  return `M ${x1} ${y1} C ${x1 + curvature} ${y1}, ${x2 - curvature} ${y2}, ${x2} ${y2}`;
};

export const FlowDesigner: React.FC<FlowDesignerProps> = ({ project, onSelect, onDelete, onDuplicate, onAdd }) => {
  const { postTypes, customEndpoints } = project;
  const containerRef = useRef<HTMLDivElement>(null);

  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDraggingCanvas, setIsDraggingCanvas] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const [draggingNode, setDraggingNode] = useState<{ type: ResourceType, id: string } | null>(null);
  const [nodePositions, setNodePositions] = useState<Record<string, { x: number, y: number }>>({});
  const [contextMenu, setContextMenu] = useState<ContextMenuState>({ visible: false, x: 0, y: 0, type: null, id: null });

  useEffect(() => {
    const newPositions = { ...nodePositions };
    let hasChanges = false;

    // Auto-layout simple grid if positions missing
    customEndpoints.forEach((ep, i) => {
      if (!newPositions[ep.id]) {
        newPositions[ep.id] = { x: 100, y: 100 + (i * 180) };
        hasChanges = true;
      }
    });

    postTypes.forEach((pt, i) => {
      if (!newPositions[pt.id]) {
        newPositions[pt.id] = { x: 600, y: 100 + (i * 240) };
        hasChanges = true;
      }
    });

    if (hasChanges) setNodePositions(newPositions);
  }, [project.postTypes.length, project.customEndpoints.length]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.target === containerRef.current || (e.target as HTMLElement).tagName === 'svg') {
      setIsDraggingCanvas(true);
      setDragStart({ x: e.clientX - offset.x, y: e.clientY - offset.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDraggingCanvas) {
      setOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
    } else if (draggingNode) {
      const rect = containerRef.current?.getBoundingClientRect();
      if (!rect) return;

      const newX = (e.clientX - rect.left - offset.x) / scale;
      const newY = (e.clientY - rect.top - offset.y) / scale;

      // Snap to grid (20px)
      const snappedX = Math.round(newX / 20) * 20;
      const snappedY = Math.round(newY / 20) * 20;

      setNodePositions(prev => ({
        ...prev,
        [draggingNode.id]: { x: snappedX - 140, y: snappedY - 40 } // Center offset
      }));
    }
  };

  const handleMouseUp = () => {
    setIsDraggingCanvas(false);
    setDraggingNode(null);
  };

  const handleWheel = (e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
       e.preventDefault();
       const s = Math.min(Math.max(0.4, scale + e.deltaY * -0.001), 2);
       setScale(s);
    }
  };

  const startDragNode = (e: React.MouseEvent, type: ResourceType, id: string) => {
    e.stopPropagation();
    setDraggingNode({ type, id });
  };

  const renderConnections = () => {
    const lines: React.ReactElement[] = [];

    // Endpoint -> Storage Logic -> CPT
    customEndpoints.forEach(ep => {
      const startPos = nodePositions[ep.id];
      if (!startPos) return;

      const endpointRight = { x: startPos.x + 280, y: startPos.y + 60 }; 

      if (ep.storage?.enabled && ep.storage.targetCptSlug) {
        const targetCpt = postTypes.find(pt => pt.slug === ep.storage?.targetCptSlug);
        if (targetCpt && nodePositions[targetCpt.id]) {
           const targetPos = nodePositions[targetCpt.id];
           const targetLeft = { x: targetPos.x, y: targetPos.y + 60 };

           lines.push(
             <g key={`flow_${ep.id}_${targetCpt.id}`}>
               <path 
                 d={getBezierPath(endpointRight.x, endpointRight.y, targetLeft.x, targetLeft.y)}
                 fill="none"
                 stroke="#10b981" 
                 strokeWidth="2"
                 strokeDasharray="4,4"
                 className="animate-dash-flow opacity-60"
               />
               <circle cx={targetLeft.x} cy={targetLeft.y} r="3" fill="#10b981" />
               <circle cx={endpointRight.x} cy={endpointRight.y} r="3" fill="#10b981" />
             </g>
           );
        }
      }
    });

    // CPT Relationships
    postTypes.forEach(pt => {
        const startPos = nodePositions[pt.id];
        if (!startPos) return;

        pt.metaFields.forEach(field => {
            if (field.type === FieldType.RELATIONSHIP && field.targetPostType) {
                const targetCpt = postTypes.find(p => p.slug === field.targetPostType);
                if (targetCpt && nodePositions[targetCpt.id] && targetCpt.id !== pt.id) {
                    const targetPos = nodePositions[targetCpt.id];
                    const startRight = { x: startPos.x + 280, y: startPos.y + 60 };
                    const targetLeft = { x: targetPos.x, y: targetPos.y + 60 };

                    lines.push(
                        <g key={`rel_${pt.id}_${targetCpt.id}`}>
                            <path 
                                d={getBezierPath(startRight.x, startRight.y, targetLeft.x, targetLeft.y)}
                                fill="none"
                                stroke="#6366f1" 
                                strokeWidth="2"
                                className="opacity-40"
                            />
                        </g>
                    );
                }
            }
        });
    });

    return lines;
  };

  return (
    <div 
      className="h-full w-full bg-[#09090b] relative overflow-hidden select-none" 
      ref={containerRef}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      onClick={() => setContextMenu({ ...contextMenu, visible: false })}
      style={{ cursor: isDraggingCanvas ? 'grabbing' : 'default' }}
    >
      <style>{`
        @keyframes dash-flow {
          to { stroke-dashoffset: -20; }
        }
        .animate-dash-flow {
          animation: dash-flow 1s linear infinite;
        }
      `}</style>

      {/* Modern Dot Grid Background */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-[0.07]"
        style={{
           backgroundImage: 'radial-gradient(#ffffff 1px, transparent 1px)',
           backgroundSize: `${20 * scale}px ${20 * scale}px`,
           backgroundPosition: `${offset.x}px ${offset.y}px`
        }}
      />

      {/* Controls Bar */}
      <div className="absolute top-6 left-6 z-50 flex flex-col gap-4">
          <div className="bg-zinc-900/90 backdrop-blur border border-zinc-800 rounded-xl p-1 flex shadow-2xl">
              <button onClick={() => onAdd('endpoint')} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="New Endpoint">
                <Network size={20} />
              </button>
              <button onClick={() => onAdd('postType')} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="New Model">
                <Box size={20} />
              </button>
              <div className="w-px bg-zinc-800 mx-1 my-2"></div>
              <button onClick={() => { setScale(1); setOffset({x:0,y:0}); }} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="Reset View">
                <Move size={20} />
              </button>
          </div>
      </div>

      {/* Canvas */}
      <div 
        className="absolute inset-0 origin-top-left"
        style={{
            transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`
        }}
      >
         <svg className="absolute inset-0 overflow-visible w-full h-full pointer-events-none z-0">
             {renderConnections()}
         </svg>

         <div className="relative z-10">
            {/* Endpoint Nodes */}
            {customEndpoints.map(ep => (
                <div
                    key={ep.id}
                    className="absolute w-[280px] bg-[#121214] rounded-xl shadow-2xl border border-zinc-800 group hover:border-pink-500/50 transition-all duration-200"
                    style={{ 
                        left: nodePositions[ep.id]?.x || 0, 
                        top: nodePositions[ep.id]?.y || 0,
                    }}
                    onMouseDown={(e) => startDragNode(e, 'endpoint', ep.id)}
                    onClick={(e) => { e.stopPropagation(); onSelect('endpoint', ep.id); }}
                    onContextMenu={(e) => { e.preventDefault(); setContextMenu({ visible: true, x: e.clientX, y: e.clientY, type: 'endpoint', id: ep.id }); }}
                >
                    <div className="h-full w-full rounded-xl overflow-hidden relative">
                        {/* Header */}
                        <div className="px-4 py-3 bg-zinc-900/50 border-b border-zinc-800 flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border ${
                                    ep.method === 'GET' ? 'bg-blue-500/10 text-blue-400 border-blue-500/20' : 
                                    ep.method === 'POST' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                                    'bg-orange-500/10 text-orange-400 border-orange-500/20'
                                }`}>
                                    {ep.method}
                                </span>
                                <span className="text-xs font-mono text-zinc-400">Endpoint</span>
                            </div>
                            <Network size={14} className="text-pink-500" />
                        </div>

                        {/* Body */}
                        <div className="p-4">
                            <div className="font-mono text-sm text-zinc-100 font-medium truncate mb-3" title={ep.route}>{ep.route}</div>

                            <div className="space-y-2">
                                {ep.storage?.enabled && (
                                    <div className="flex items-center gap-2 text-[10px] text-zinc-400 bg-zinc-800/50 p-1.5 rounded border border-zinc-700/50">
                                        <Database size={12} className="text-green-500"/>
                                        <span>Saves to: <span className="text-green-400 font-mono">{ep.storage.targetCptSlug}</span></span>
                                    </div>
                                )}
                                {ep.hookName && (
                                    <div className="flex items-center gap-2 text-[10px] text-zinc-400 bg-zinc-800/50 p-1.5 rounded border border-zinc-700/50">
                                        <Zap size={12} className="text-yellow-500"/>
                                        <span>Hook: <span className="text-yellow-400 font-mono">{ep.hookName}</span></span>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Footer (Params count) */}
                        <div className="px-4 py-2 bg-zinc-900/30 border-t border-zinc-800 flex justify-between items-center text-[10px] text-zinc-500">
                             <span>{ep.parameters.length} Parameters</span>
                             {ep.customPhp && <span className="text-blue-400 flex items-center gap-1"><Code size={10}/> Custom PHP</span>}
                        </div>
                    </div>
                </div>
            ))}

            {/* Post Type Nodes */}
            {postTypes.map(pt => (
                <div
                    key={pt.id}
                    className="absolute w-[280px] bg-[#121214] rounded-xl shadow-2xl border border-zinc-800 group hover:border-indigo-500/50 transition-all duration-200"
                    style={{ 
                        left: nodePositions[pt.id]?.x || 0, 
                        top: nodePositions[pt.id]?.y || 0,
                    }}
                    onMouseDown={(e) => startDragNode(e, 'postType', pt.id)}
                    onClick={(e) => { e.stopPropagation(); onSelect('postType', pt.id); }}
                    onContextMenu={(e) => { e.preventDefault(); setContextMenu({ visible: true, x: e.clientX, y: e.clientY, type: 'postType', id: pt.id }); }}
                >
                    <div className="h-full w-full rounded-xl overflow-hidden relative">
                         <div className="px-4 py-3 bg-zinc-900/50 border-b border-zinc-800 flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <Box size={14} className="text-indigo-500" />
                                <span className="text-sm font-bold text-zinc-100">{pt.singularName}</span>
                            </div>
                            <span className="text-[10px] font-mono text-zinc-500 bg-zinc-800 px-1.5 rounded">{pt.slug}</span>
                        </div>

                        <div className="p-4 space-y-1.5">
                            {pt.metaFields.slice(0, 5).map(mf => (
                                <div key={mf.id} className="flex items-center justify-between text-xs group/field">
                                    <span className="text-zinc-400 font-mono">{mf.key}</span>
                                    <span className={`text-[10px] px-1.5 py-px rounded ${
                                        mf.type === FieldType.RELATIONSHIP ? 'bg-indigo-500/10 text-indigo-400' : 'text-zinc-600 bg-zinc-800'
                                    }`}>
                                        {mf.type}
                                    </span>
                                </div>
                            ))}
                            {pt.metaFields.length > 5 && (
                                <div className="text-[10px] text-zinc-600 pt-2 text-center italic">
                                    +{pt.metaFields.length - 5} more fields
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            ))}
         </div>
      </div>

       {contextMenu.visible && (
        <div 
          className="fixed bg-[#18181b] border border-zinc-700 rounded-lg shadow-xl py-1 z-[100] min-w-[160px] animate-in fade-in zoom-in-95 duration-100"
          style={{ top: contextMenu.y, left: contextMenu.x }}
          onClick={(e) => e.stopPropagation()}
        >
          <button 
            onClick={() => { onSelect(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
            className="w-full text-left px-4 py-2 text-sm text-zinc-300 hover:bg-indigo-600 hover:text-white flex items-center gap-2"
          >
            <Edit size={14} /> Edit
          </button>
          <button 
             onClick={() => { onDuplicate(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
             className="w-full text-left px-4 py-2 text-sm text-zinc-300 hover:bg-indigo-600 hover:text-white flex items-center gap-2"
          >
            <Copy size={14} /> Duplicate
          </button>
          <div className="h-px bg-zinc-700 my-1"></div>
          <button 
             onClick={() => { onDelete(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
             className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-red-900/30 flex items-center gap-2"
          >
            <Trash2 size={14} /> Delete
          </button>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { CustomPostType, FieldType, MetaField, Taxonomy } from '../types';
import { DEFAULT_SUPPORTS_OPTIONS } from '../constants';
import { Plus, Trash2, Settings, Link as LinkIcon, Layers, ChevronRight, ChevronDown, AlignLeft, Type, Hash, ToggleLeft, List, Box } from 'lucide-react';

interface ResourceEditorProps {
  cpt: CustomPostType;
  allTaxonomies: Taxonomy[];
  allPostTypes?: CustomPostType[];
  onChange: (updatedCpt: CustomPostType) => void;
  onDelete: () => void;
}

const getIconForType = (type: FieldType) => {
  switch(type) {
    case FieldType.STRING: return <Type size={14} className="text-zinc-500"/>;
    case FieldType.INTEGER: 
    case FieldType.NUMBER: return <Hash size={14} className="text-blue-500"/>;
    case FieldType.BOOLEAN: return <ToggleLeft size={14} className="text-green-500"/>;
    case FieldType.RELATIONSHIP: return <LinkIcon size={14} className="text-indigo-500"/>;
    case FieldType.REPEATER: return <Layers size={14} className="text-purple-500"/>;
    case FieldType.ARRAY: return <List size={14} className="text-orange-500"/>;
    default: return <AlignLeft size={14} className="text-zinc-500"/>;
  }
};

export const ResourceEditor: React.FC<ResourceEditorProps> = ({ cpt, allTaxonomies, allPostTypes = [], onChange, onDelete }) => {
  const [expandedRepeater, setExpandedRepeater] = useState<string | null>(null);

  const handleFieldChange = (fieldId: string, changes: Partial<MetaField>) => {
    const updateFieldsRecursive = (fields: MetaField[]): MetaField[] => {
      return fields.map(f => {
        if (f.id === fieldId) return { ...f, ...changes };
        if (f.subFields) return { ...f, subFields: updateFieldsRecursive(f.subFields) };
        return f;
      });
    };
    onChange({ ...cpt, metaFields: updateFieldsRecursive(cpt.metaFields) });
  };

  const addField = (parentFieldId?: string) => {
    const newField: MetaField = {
      id: `field_${Date.now()}`,
      key: 'new_field',
      label: 'New Field',
      type: FieldType.STRING,
      description: '',
      required: false,
      showInRest: true,
      subFields: [],
    };

    if (parentFieldId) {
       const addSubField = (fields: MetaField[]): MetaField[] => {
         return fields.map(f => {
           if (f.id === parentFieldId) {
             return { ...f, subFields: [...(f.subFields || []), newField] };
           }
           if (f.subFields) return { ...f, subFields: addSubField(f.subFields) };
           return f;
         });
       };
       onChange({ ...cpt, metaFields: addSubField(cpt.metaFields) });
    } else {
       onChange({ ...cpt, metaFields: [...cpt.metaFields, newField] });
    }
  };

  const removeField = (id: string) => {
    const removeRecursive = (fields: MetaField[]): MetaField[] => {
      return fields.filter(f => f.id !== id).map(f => ({
        ...f,
        subFields: f.subFields ? removeRecursive(f.subFields) : undefined
      }));
    };
    onChange({ ...cpt, metaFields: removeRecursive(cpt.metaFields) });
  };

  const toggleSupport = (option: string) => {
    const newSupports = cpt.supports.includes(option)
      ? cpt.supports.filter(s => s !== option)
      : [...cpt.supports, option];
    onChange({ ...cpt, supports: newSupports });
  };

  const toggleTaxonomy = (taxSlug: string) => {
    const newTaxonomies = cpt.taxonomies.includes(taxSlug)
      ? cpt.taxonomies.filter(t => t !== taxSlug)
      : [...cpt.taxonomies, taxSlug];
    onChange({ ...cpt, taxonomies: newTaxonomies });
  };

  const renderFields = (fields: MetaField[], level = 0) => {
    return fields.map((field) => (
        <div key={field.id} className={`group relative flex flex-col gap-2 bg-[#121214] hover:bg-[#18181b] border border-zinc-800 rounded-md p-3 mb-2 transition-colors ${level > 0 ? 'ml-6 border-l-2 border-l-purple-500/30' : ''}`}>

          <div className="flex items-start gap-3">
             {/* Icon Handle */}
             <div className="mt-2 text-zinc-600 cursor-grab active:cursor-grabbing">
                {getIconForType(field.type)}
             </div>

             {/* Main Inputs */}
             <div className="flex-1 grid grid-cols-12 gap-3">
                <div className="col-span-3">
                    <input 
                      type="text" 
                      value={field.key}
                      onChange={e => handleFieldChange(field.id, { key: e.target.value })}
                      className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-xs text-zinc-200 font-mono focus:border-indigo-500 focus:outline-none placeholder-zinc-600"
                      placeholder="field_key"
                    />
                </div>
                <div className="col-span-3">
                   <select 
                     value={field.type}
                     onChange={e => handleFieldChange(field.id, { type: e.target.value as FieldType })}
                     className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-xs text-zinc-300 focus:border-indigo-500 focus:outline-none"
                   >
                     {Object.values(FieldType).map(t => <option key={t} value={t}>{t}</option>)}
                   </select>
                </div>
                <div className="col-span-6">
                    <input 
                      type="text" 
                      value={field.description}
                      onChange={e => handleFieldChange(field.id, { description: e.target.value })}
                      className="w-full bg-transparent border-b border-zinc-800 focus:border-indigo-500 rounded-none px-0 py-1.5 text-xs text-zinc-400 focus:outline-none placeholder-zinc-700 transition-colors"
                      placeholder="Field description..."
                    />
                </div>
             </div>

             <button onClick={() => removeField(field.id)} className="text-zinc-600 hover:text-red-400 p-1 opacity-0 group-hover:opacity-100 transition-opacity">
                <Trash2 size={14} />
             </button>
          </div>

          {/* Conditional Row */}
          {(field.type === FieldType.RELATIONSHIP || field.type === FieldType.REPEATER || field.required || field.showInRest) && (
             <div className="pl-7 flex items-center gap-4 mt-1">
                {field.type === FieldType.RELATIONSHIP && (
                   <div className="flex items-center gap-2">
                      <span className="text-[10px] text-zinc-500 uppercase font-bold">Connects to</span>
                      <select 
                        value={field.targetPostType || ''}
                        onChange={e => handleFieldChange(field.id, { targetPostType: e.target.value })}
                        className="bg-indigo-500/10 border border-indigo-500/20 text-indigo-300 rounded px-2 py-0.5 text-[10px] focus:outline-none"
                      >
                        <option value="">Select Model...</option>
                        {allPostTypes.filter(p => p.id !== cpt.id).map(p => (
                          <option key={p.slug} value={p.slug}>{p.singularName}</option>
                        ))}
                      </select>
                   </div>
                )}

                <div className="flex gap-3">
                   <label className="flex items-center gap-1.5 cursor-pointer select-none">
                     <input type="checkbox" checked={field.required} onChange={e => handleFieldChange(field.id, { required: e.target.checked })} className="rounded bg-zinc-800 border-zinc-600 text-indigo-500 focus:ring-0 w-3 h-3"/>
                     <span className="text-[10px] text-zinc-400">Required</span>
                   </label>
                   <label className="flex items-center gap-1.5 cursor-pointer select-none">
                     <input type="checkbox" checked={field.showInRest} onChange={e => handleFieldChange(field.id, { showInRest: e.target.checked })} className="rounded bg-zinc-800 border-zinc-600 text-indigo-500 focus:ring-0 w-3 h-3"/>
                     <span className="text-[10px] text-zinc-400">Show in API</span>
                   </label>
                </div>

                {field.type === FieldType.REPEATER && (
                    <button 
                      onClick={() => setExpandedRepeater(expandedRepeater === field.id ? null : field.id)}
                      className="ml-auto text-[10px] flex items-center gap-1 text-purple-400 hover:text-purple-300"
                    >
                        {expandedRepeater === field.id ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
                        {expandedRepeater === field.id ? 'Hide Sub-fields' : `Edit Sub-fields (${field.subFields?.length || 0})`}
                    </button>
                )}
             </div>
          )}

          {field.type === FieldType.REPEATER && expandedRepeater === field.id && (
             <div className="mt-2 pt-2 border-t border-zinc-800/50 pl-6">
                 {renderFields(field.subFields || [], level + 1)}
                 <button onClick={() => addField(field.id)} className="ml-8 mt-2 text-xs text-zinc-500 hover:text-zinc-300 flex items-center gap-1">
                    <Plus size={12}/> Add Sub-field to {field.key}
                 </button>
             </div>
          )}
        </div>
      ));
  }

  return (
    <div className="h-full overflow-y-auto p-6 md:p-10 custom-scrollbar">
      {/* Header */}
      <div className="flex justify-between items-start mb-10">
        <div className="flex items-center gap-4">
           <div className="w-12 h-12 bg-indigo-500/10 rounded-xl flex items-center justify-center border border-indigo-500/20">
              <Box className="text-indigo-500" size={24} />
           </div>
           <div>
             <h2 className="text-2xl font-bold text-white tracking-tight">{cpt.singularName}</h2>
             <p className="text-zinc-500 text-sm">Post Type Configuration</p>
           </div>
        </div>
        <button 
          onClick={onDelete}
          className="text-red-400 hover:bg-red-500/10 px-3 py-2 rounded-lg transition-colors flex items-center gap-2 text-sm font-medium border border-transparent hover:border-red-500/20"
        >
          <Trash2 size={16} />
          Delete
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">

        {/* Left Column: Fields */}
        <div className="lg:col-span-2 space-y-6">
           <div className="flex items-center justify-between mb-2">
              <h3 className="text-sm font-bold text-zinc-400 uppercase tracking-widest">Data Schema</h3>
              <button 
                onClick={() => addField()}
                className="flex items-center gap-1.5 text-xs bg-indigo-600 hover:bg-indigo-500 text-white px-3 py-1.5 rounded-full transition-all shadow-lg shadow-indigo-900/20 font-medium"
              >
                <Plus size={14} /> Add Field
              </button>
           </div>

           <div className="space-y-2">
              {cpt.metaFields.length === 0 ? (
                <div className="text-center py-12 border-2 border-dashed border-zinc-800 rounded-xl bg-zinc-900/30">
                   <p className="text-zinc-500 text-sm">No fields defined yet.</p>
                   <button onClick={() => addField()} className="text-indigo-400 text-xs mt-2 hover:underline">Add your first field</button>
                </div>
              ) : (
                renderFields(cpt.metaFields)
              )}
           </div>
        </div>

        {/* Right Column: Settings */}
        <div className="space-y-8">

           {/* General Config */}
           <div className="bg-[#121214] border border-zinc-800 rounded-xl p-5 shadow-sm">
              <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                 <Settings size={14} /> General Config
              </h3>

              <div className="space-y-4">
                 <div className="grid grid-cols-2 gap-3">
                    <div>
                        <label className="text-[10px] text-zinc-500 font-bold mb-1 block">SINGULAR</label>
                        <input type="text" value={cpt.singularName} onChange={e => onChange({...cpt, singularName: e.target.value})} className="w-full bg-zinc-900 border border-zinc-700 rounded p-2 text-xs text-white focus:border-indigo-500 outline-none" />
                    </div>
                    <div>
                        <label className="text-[10px] text-zinc-500 font-bold mb-1 block">PLURAL</label>
                        <input type="text" value={cpt.pluralName} onChange={e => onChange({...cpt, pluralName: e.target.value})} className="w-full bg-zinc-900 border border-zinc-700 rounded p-2 text-xs text-white focus:border-indigo-500 outline-none" />
                    </div>
                 </div>
                 <div>
                    <label className="text-[10px] text-zinc-500 font-bold mb-1 block">SLUG (DB KEY)</label>
                    <input type="text" value={cpt.slug} onChange={e => onChange({...cpt, slug: e.target.value})} className="w-full bg-zinc-900 border border-zinc-700 rounded p-2 text-xs text-white font-mono focus:border-indigo-500 outline-none" />
                 </div>
                 <div>
                    <label className="text-[10px] text-zinc-500 font-bold mb-1 block">REST BASE</label>
