import { ProjectState, CustomPostType, MetaField, FieldType } from '../types';

const getRandomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const getRandomText = (label: string) => {
  const adjecties = ['Awesome', 'Rapid', 'Dynamic', 'Global', 'Smart', 'Sustainable', 'Innovative'];
  const nouns = ['Solution', 'Project', 'Initiative', 'Platform', 'System', 'Strategy'];
  return `${adjecties[getRandomInt(0, adjecties.length - 1)]} ${nouns[getRandomInt(0, nouns.length - 1)]} - ${label}`;
};

const generateMetaValue = (field: MetaField): string | number | boolean => {
  switch (field.type) {
    case FieldType.INTEGER:
    case FieldType.NUMBER:
      if (field.key.includes('price') || field.key.includes('cost')) return getRandomInt(10, 500);
      if (field.key.includes('rating')) return getRandomInt(1, 5);
      return getRandomInt(1, 100);
    case FieldType.BOOLEAN:
      return Math.random() > 0.5;
    case FieldType.RELATIONSHIP:
      // We return 1 as a placeholder ID, or random int to simulate connection
      return getRandomInt(1, 5);
    case FieldType.REPEATER:
      // Return a JSON encoded string for repeater
      const items = [];
      for(let i=0; i<2; i++) {
        const item: any = {};
        field.subFields?.forEach(sf => {
            item[sf.key] = generateMetaValue(sf);
        });
        items.push(item);
      }
      return JSON.stringify(items);
    case FieldType.STRING:
    default:
      if (field.key.includes('email')) return `user${getRandomInt(1,999)}@example.com`;
      if (field.key.includes('url') || field.key.includes('link')) return 'https://example.com';
      if (field.key.includes('date')) return new Date().toISOString().split('T')[0];
      return `Sample ${field.label}`;
  }
};

export const generateSeederPHP = (project: ProjectState): string => {
  const { postTypes } = project;
  const projectSlug = project.name.toLowerCase().replace(/\s+/g, '_');

  let php = `<?php
/**
 * Seeder Script for ${project.name}
 * 
 * Instructions:
 * 1. Place this file in your WordPress root or theme folder.
 * 2. Include it in your functions.php temporarily, or run via WP-CLI:
 *    wp eval-file seeder.php
 */

if ( ! defined( 'ABSPATH' ) ) {
    /** Load WordPress Bootstrap */
    require_once( 'wp-load.php' );
}

function ${projectSlug}_seed_data() {
    $user_id = get_current_user_id();
    if ( ! $user_id ) $user_id = 1;

`;

  postTypes.forEach(cpt => {
    php += `
    // ---------------------------------------------------
    // Seed ${cpt.pluralName} (${cpt.slug})
    // ---------------------------------------------------
    echo "Seeding ${cpt.pluralName}...\n";

    for ( $i = 1; $i <= 5; $i++ ) {
        $post_data = array(
            'post_title'    => '${cpt.singularName} ' . $i . ' - ' . wp_generate_password(6, false),
            'post_content'  => 'Lorem ipsum dolor sit amet, consectetur adipiscing elit. Generated content for testing.',
            'post_status'   => 'publish',
            'post_type'     => '${cpt.slug}',
            'post_author'   => $user_id,
        );

        $post_id = wp_insert_post( $post_data );

        if ( ! is_wp_error( $post_id ) ) {
`;

    // Generate Meta
    cpt.metaFields.forEach(field => {
       const value = generateMetaValue(field);
       let phpValue = '';

       if (typeof value === 'string') {
           // Escape single quotes
           phpValue = `'${value.replace(/'/g, "\\'")}'`;
       } else if (typeof value === 'boolean') {
           phpValue = value ? 'true' : 'false';
       } else {
           phpValue = String(value);
       }

       // For Repeaters, we need to handle serialization slightly differently in PHP context usually, 
       // but sending a JSON string is often safer for raw storage or needs `maybe_serialize`.
       // Here we just insert the raw value.

       php += `            update_post_meta( $post_id, '${field.key}', ${phpValue} );\n`;
    });

    // Handle Taxonomy Assignment (Random)
    cpt.taxonomies.forEach(taxSlug => {
        const tax = project.taxonomies.find(t => t.slug === taxSlug);
        if (tax) {
            php += `            
            // Assign random terms for ${tax.singularName}
            $term_name = '${tax.singularName} ' . rand(1, 3);
            $term = term_exists( $term_name, '${tax.slug}' );
            if ( ! $term ) {
                $term = wp_insert_term( $term_name, '${tax.slug}' );
            }
            if ( ! is_wp_error( $term ) ) {
                wp_set_object_terms( $post_id, (int) $term['term_id'], '${tax.slug}' );
            }
`;
        }
    });

    php += `        }\n    }\n`;
  });

  php += `
    echo "Seeding Complete!";
}

// Run the seeder
${projectSlug}_seed_data();
`;

  return php;
};

import React, { useState } from 'react';
import { ProjectState } from '../types';
import { generateOpenAPI, generatePHP, generatePackageJSON, generateComposerJSON, generatePlaygroundBlueprint } from '../services/wpGenerator';
import { generateSeederPHP } from '../services/dataGenerator';
import { Copy, Check, FileCode, FileJson, Package, PlayCircle, Database } from 'lucide-react';

interface CodePreviewProps {
  project: ProjectState;
  initialTab?: 'openapi' | 'php' | 'pkg' | 'composer' | 'blueprint' | 'seeder';
}

export const CodePreview: React.FC<CodePreviewProps> = ({ project, initialTab = 'openapi' }) => {
  const [tab, setTab] = useState<'openapi' | 'php' | 'pkg' | 'composer' | 'blueprint' | 'seeder'>(initialTab);
  const [copied, setCopied] = useState(false);

  let content = "";
  switch(tab) {
    case 'openapi': content = generateOpenAPI(project); break;
    case 'php': content = generatePHP(project); break;
    case 'pkg': content = generatePackageJSON(project); break;
    case 'composer': content = generateComposerJSON(project); break;
    case 'blueprint': content = generatePlaygroundBlueprint(project); break;
    case 'seeder': content = generateSeederPHP(project); break;
  }

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePlaygroundLaunch = () => {
    const blueprint = generatePlaygroundBlueprint(project);
    const fragment = `#${JSON.stringify(JSON.parse(blueprint))}`;
    window.open(`https://playground.wordpress.net/${fragment}`, '_blank');
  };

  const tabs = [
    { id: 'openapi', label: 'openapi.json', icon: FileJson, color: 'text-blue-400', activeBg: 'bg-blue-500/10 border-blue-500/30' },
    { id: 'php', label: 'plugin.php', icon: FileCode, color: 'text-purple-400', activeBg: 'bg-purple-500/10 border-purple-500/30' },
    { id: 'pkg', label: 'package.json', icon: Package, color: 'text-green-400', activeBg: 'bg-green-500/10 border-green-500/30' },
    { id: 'composer', label: 'composer.json', icon: Package, color: 'text-yellow-400', activeBg: 'bg-yellow-500/10 border-yellow-500/30' },
    { id: 'seeder', label: 'seeder.php', icon: Database, color: 'text-pink-400', activeBg: 'bg-pink-500/10 border-pink-500/30' },
    { id: 'blueprint', label: 'blueprint.json', icon: PlayCircle, color: 'text-blue-500', activeBg: 'bg-blue-600/10 border-blue-600/30' },
  ];

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e]">
      <div className="flex items-center justify-between px-4 py-2 bg-[#252526] border-b border-[#333]">
        <div className="flex gap-1 overflow-x-auto">
          {tabs.map(t => (
            <button
              key={t.id}
              onClick={() => setTab(t.id as any)}
              className={`flex items-center gap-2 px-4 py-2 text-xs font-medium rounded-t-lg transition-all border border-transparent whitespace-nowrap ${
                tab === t.id 
                ? `${t.activeBg} ${t.color}` 
                : 'text-slate-400 hover:bg-[#333] hover:text-slate-200'
              }`}
            >
              <t.icon size={14} />
              {t.label}
            </button>
          ))}
        </div>
        <div className="flex gap-2">
           {tab === 'blueprint' && (
              <button
                onClick={handlePlaygroundLaunch}
                className="flex items-center gap-2 text-xs text-white bg-blue-600 hover:bg-blue-500 px-3 py-1.5 rounded transition-colors shadow-lg shadow-blue-500/20 font-medium"
              >
                <PlayCircle size={14} />
                Run in Playground
              </button>
           )}
          <button 
            onClick={handleCopy}
            className="flex items-center gap-2 text-xs text-slate-400 hover:text-white px-3 py-1.5 rounded bg-[#333] hover:bg-[#444] transition-colors"
          >
            {copied ? <Check size={14} className="text-green-500"/> : <Copy size={14} />}
            {copied ? 'Copied' : 'Copy'}
          </button>
        </div>
      </div>
