};

import React, { useState, useEffect } from 'react';
import { ProjectState, ViewMode, CustomPostType, CustomEndpoint, Taxonomy, ResourceType, AppSettings, AIProvider, MetaField, FieldType } from './types';
import { INITIAL_PROJECT_STATE } from './constants';
import { ResourceEditor } from './components/ResourceEditor';
import { EndpointEditor } from './components/EndpointEditor';
import { TaxonomyEditor } from './components/TaxonomyEditor';
import { CodePreview } from './components/CodePreview';
import { FlowDesigner } from './components/FlowDesigner';
import { BlueprintView } from './components/BlueprintView';
import { AIAssistant } from './components/AIAssistant';
import { SettingsScreen } from './components/SettingsScreen';
import { Terminal } from './components/Terminal';
import { Sidebar } from './components/Sidebar';
import { EditorModal } from './components/EditorModal';
import { logger } from './utils/logger';
import { LayoutTemplate } from 'lucide-react';

interface SelectionState {
  type: ResourceType;
  id: string;
}

const DEFAULT_SETTINGS: AppSettings = {
  provider: AIProvider.GEMINI,
  apiKey: '', 
  model: 'gemini-3-flash-preview',
  temperature: 0.7
};

const App = () => {
  const [project, setProject] = useState<ProjectState>(INITIAL_PROJECT_STATE);
  const [currentView, setCurrentView] = useState<ViewMode>('flow'); 
  const [isAIModalOpen, setAIModalOpen] = useState(false);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [isTerminalOpen, setIsTerminalOpen] = useState(false);

  const [editingResource, setEditingResource] = useState<SelectionState | null>(null);

  const handleUpdateResource = (updatedCpt: CustomPostType) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.map(pt => pt.id === updatedCpt.id ? updatedCpt : pt)
    }));
    logger.info(`Updated Post Type: ${updatedCpt.slug}`);
  };

  const handleUpdateEndpoint = (updatedEndpoint: CustomEndpoint) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.map(ep => ep.id === updatedEndpoint.id ? updatedEndpoint : ep)
    }));
    logger.info(`Updated Endpoint: ${updatedEndpoint.route}`);
  };

  const handleUpdateTaxonomy = (updatedTaxonomy: Taxonomy) => {
    setProject(prev => ({
      ...prev,
      taxonomies: prev.taxonomies.map(t => t.id === updatedTaxonomy.id ? updatedTaxonomy : t)
    }));
    logger.info(`Updated Taxonomy: ${updatedTaxonomy.slug}`);
  };

  const handleAddResource = () => {
    const newId = `cpt_${Date.now()}`;
    const newCpt: CustomPostType = {
      id: newId,
      slug: 'new_type',
      singularName: 'New Type',
      pluralName: 'New Types',
      description: '',
      icon: 'admin-post',
      supports: ['title', 'editor'],
      taxonomies: [],
      metaFields: [],
      showInRest: true,
      restBase: 'new_types'
    };
    setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, newCpt] }));
    setEditingResource({ type: 'postType', id: newId });
    logger.success('Added new Post Type');
  };

  const handleAddEndpoint = () => {
    const newId = `endpoint_${Date.now()}`;
    const newEndpoint: CustomEndpoint = {
       id: newId,
       route: '/new-route',
       method: 'POST',
       callbackFunction: 'my_callback_function',
       description: 'New custom endpoint',
       parameters: []
    };
    setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, newEndpoint] }));
    setEditingResource({ type: 'endpoint', id: newId });
    logger.success('Added new Endpoint');
  };

  const handleAddTaxonomy = () => {
    const newId = `tax_${Date.now()}`;
    const newTax: Taxonomy = {
      id: newId,
      slug: 'new_tax',
      singularName: 'New Taxonomy',
      pluralName: 'New Taxonomies',
      hierarchical: true,
      showInRest: true,
      connectedPostTypes: []
    };
    setProject(prev => ({ ...prev, taxonomies: [...prev.taxonomies, newTax] }));
    setEditingResource({ type: 'taxonomy', id: newId });
    logger.success('Added new Taxonomy');
  };

  const handleDeleteResource = (id: string) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.filter(pt => pt.id !== id)
    }));
    if (editingResource?.id === id) setEditingResource(null);
    logger.info(`Deleted Resource ID: ${id}`);
  };

  const handleDeleteEndpoint = (id: string) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.filter(ep => ep.id !== id)
    }));
    if (editingResource?.id === id) setEditingResource(null);
    logger.info(`Deleted Endpoint ID: ${id}`);
  };

  const handleDeleteTaxonomy = (id: string) => {
    setProject(prev => ({
      ...prev,
      taxonomies: prev.taxonomies.filter(t => t.id !== id)
    }));
    if (editingResource?.id === id) setEditingResource(null);
    logger.info(`Deleted Taxonomy ID: ${id}`);
  };

  const handleDuplicate = (type: ResourceType, id: string) => {
    if (type === 'postType') {
       const original = project.postTypes.find(pt => pt.id === id);
       if (original) {
         const newId = `cpt_${Date.now()}`;
         const copy = { ...original, id: newId, slug: `${original.slug}_copy`, singularName: `${original.singularName} Copy`, pluralName: `${original.pluralName} Copy` };
         setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, copy] }));
         setEditingResource({ type: 'postType', id: newId });
         logger.success(`Duplicated Post Type: ${original.slug}`);
       }
    } else if (type === 'endpoint') {
      const original = project.customEndpoints.find(ep => ep.id === id);
      if (original) {
        const newId = `endpoint_${Date.now()}`;
        const copy = { ...original, id: newId, route: `${original.route}-copy` };
        setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, copy] }));
        setEditingResource({ type: 'endpoint', id: newId });
        logger.success(`Duplicated Endpoint: ${original.route}`);
      }
    } else if (type === 'taxonomy') {
      const original = project.taxonomies.find(t => t.id === id);
      if (original) {
        const newId = `tax_${Date.now()}`;
        const copy = { ...original, id: newId, slug: `${original.slug}_copy` };
        setProject(prev => ({ ...prev, taxonomies: [...prev.taxonomies, copy] }));
        setEditingResource({ type: 'taxonomy', id: newId });
        logger.success(`Duplicated Taxonomy: ${original.slug}`);
      }
    }
  };

  const handleConnect = (source: { type: ResourceType, id: string }, target: { type: ResourceType, id: string }) => {
    // 1. Link Endpoint -> CPT (Enable Storage)
    if (source.type === 'endpoint' && target.type === 'postType') {
      const endpoint = project.customEndpoints.find(ep => ep.id === source.id);
      const targetCpt = project.postTypes.find(pt => pt.id === target.id);

      if (endpoint && targetCpt) {
         // Check if already connected to a different one? No, just overwrite for now or update
         const newStorage = {
            enabled: true,
            targetCptSlug: targetCpt.slug,
            fieldMapping: { ...endpoint.storage?.fieldMapping }
         };

         // Intelligent Auto-Mapping
         endpoint.parameters.forEach(param => {
             if (param.key === 'title' || param.key === 'name') newStorage.fieldMapping[param.key] = 'post_title';
             else if (param.key === 'content' || param.key === 'description' || param.key === 'body') newStorage.fieldMapping[param.key] = 'post_content';
             else {
                 // Try to match with meta field
                 const match = targetCpt.metaFields.find(mf => mf.key === param.key);
                 if (match) newStorage.fieldMapping[param.key] = match.key;
             }
         });

         handleUpdateEndpoint({ ...endpoint, storage: newStorage });
         logger.success(`Linked Route ${endpoint.route} to Model ${targetCpt.singularName}`);
      }
    }

    // 2. Link CPT -> CPT (Create Relationship Field)
    if (source.type === 'postType' && target.type === 'postType' && source.id !== target.id) {
       const sourceCpt = project.postTypes.find(pt => pt.id === source.id);
       const targetCpt = project.postTypes.find(pt => pt.id === target.id);

       if (sourceCpt && targetCpt) {
          // Check if field already exists
          const existing = sourceCpt.metaFields.find(f => f.type === FieldType.RELATIONSHIP && f.targetPostType === targetCpt.slug);
          if (existing) {
             logger.warn('Relationship already exists.');
             return;
          }

          const newField: MetaField = {
             id: `field_${Date.now()}`,
             key: `${targetCpt.slug}_id`,
             label: `Related ${targetCpt.singularName}`,
             type: FieldType.RELATIONSHIP,
             description: `Link to a ${targetCpt.singularName}`,
             required: false,
             showInRest: true,
             targetPostType: targetCpt.slug
          };

          handleUpdateResource({
             ...sourceCpt,
             metaFields: [...sourceCpt.metaFields, newField]
          });
          logger.success(`Created Relationship: ${sourceCpt.singularName} -> ${targetCpt.singularName}`);
       }
    }
  };

  const handleAIApply = (partial: Partial<ProjectState>) => {
    setProject(prev => ({
      ...prev,
      postTypes: [...prev.postTypes, ...(partial.postTypes || [])],
      taxonomies: [...prev.taxonomies, ...(partial.taxonomies || [])],
      customEndpoints: [...prev.customEndpoints, ...(partial.customEndpoints || [])]
    }));
    logger.success('Applied AI generated structure');
  };

  const handleViewChange = (view: ViewMode) => {
    setCurrentView(view);
  };

  const handleSelect = (type: ResourceType, id: string) => {
    setEditingResource({ type, id });
  };

  const renderMainContent = () => {
    switch (currentView) {
      case 'openapi':
        return <CodePreview project={project} initialTab="openapi" />;
      case 'php':
        return <CodePreview project={project} initialTab="php" />;
      case 'flow':
        return (
           <FlowDesigner 
             project={project} 
             onSelect={handleSelect}
             onDelete={(type, id) => {
               if (type === 'postType') handleDeleteResource(id);
               else if (type === 'endpoint') handleDeleteEndpoint(id);
               else if (type === 'taxonomy') handleDeleteTaxonomy(id);
             }}
             onDuplicate={handleDuplicate}
             onAdd={(type) => {
               if (type === 'postType') handleAddResource();
               else if (type === 'endpoint') handleAddEndpoint();
               else if (type === 'taxonomy') handleAddTaxonomy();
             }}
             onConnect={handleConnect}
           />
        );
      case 'blueprint':
        return <BlueprintView project={project} />;
      case 'settings':
        return <SettingsScreen settings={settings} onSave={setSettings} />;
      default:
        return (
          <div className="flex flex-col items-center justify-center h-full text-zinc-500">
             <div className="p-8 bg-zinc-900/50 rounded-full mb-4">
               <LayoutTemplate size={48} className="text-zinc-700" />
             </div>
             <p className="text-lg font-medium mb-2">Welcome to WP API Architect</p>
             <p className="text-sm">Quick editing is available via sidebar or visual designers.</p>
          </div>
        );
    }
  };

  const editingCpt = editingResource?.type === 'postType' ? project.postTypes.find(pt => pt.id === editingResource.id) : null;
  const editingEndpoint = editingResource?.type === 'endpoint' ? project.customEndpoints.find(ep => ep.id === editingResource.id) : null;
  const editingTaxonomy = editingResource?.type === 'taxonomy' ? project.taxonomies.find(t => t.id === editingResource.id) : null;

  return (
    <div className="flex h-screen bg-zinc-950 text-zinc-100 overflow-hidden font-sans selection:bg-indigo-500/30">

      <Sidebar 
        project={project}
        currentView={currentView}
        selection={editingResource || { type: 'postType', id: '' }}
        isTerminalOpen={isTerminalOpen}
        onSelect={handleSelect}
        onViewChange={handleViewChange}
        onAddResource={handleAddResource}
        onAddEndpoint={handleAddEndpoint}
        onAddTaxonomy={handleAddTaxonomy}
        onToggleTerminal={() => setIsTerminalOpen(!isTerminalOpen)}
        onOpenAI={() => setAIModalOpen(true)}
      />

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#09090b] relative">
        <div className="absolute inset-0 bg-gradient-to-br from-zinc-900 via-black to-zinc-950 pointer-events-none opacity-50 z-0"/>
        <div className="relative z-10 flex-1 flex flex-col min-h-0">
           {renderMainContent()}
        </div>
        {isTerminalOpen && <Terminal onClose={() => setIsTerminalOpen(false)} />}
      </div>

      {/* Editor Modal Overlay */}
      <EditorModal 
        isOpen={!!editingResource} 
        onClose={() => setEditingResource(null)}
        title={
          editingCpt ? `Edit Model: ${editingCpt.singularName}` : 
          editingEndpoint ? `Edit Route: ${editingEndpoint.route}` : 
          editingTaxonomy ? `Edit Taxonomy: ${editingTaxonomy.singularName}` : 
          "Editor"
        }
      >
        {editingCpt && (
          <ResourceEditor 
            cpt={editingCpt} 
            allTaxonomies={project.taxonomies}
            allPostTypes={project.postTypes}
            onChange={handleUpdateResource}
            onDelete={() => handleDeleteResource(editingCpt.id)}
          />
        )}
        {editingEndpoint && (
          <EndpointEditor
            endpoint={editingEndpoint}
            namespace={project.namespace}
            postTypes={project.postTypes}
            onChange={handleUpdateEndpoint}
            onDelete={() => handleDeleteEndpoint(editingEndpoint.id)}
          />
        )}
        {editingTaxonomy && (
          <TaxonomyEditor
            taxonomy={editingTaxonomy}
            postTypes={project.postTypes}
            onChange={handleUpdateTaxonomy}
            onDelete={() => handleDeleteTaxonomy(editingTaxonomy.id)}
          />
        )}
      </EditorModal>

      {isAIModalOpen && (
        <AIAssistant 
          project={project}
          settings={settings}
          onApply={handleAIApply} 
          onClose={() => setAIModalOpen(false)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { ProjectState, ResourceType, ContextMenuState, FieldType } from '../types';
import { Network, Database, Box, Edit, Trash2, Copy, Move, Zap, Link as LinkIcon, Key, Table, List } from 'lucide-react';

interface FlowDesignerProps {
  project: ProjectState;
  onSelect: (type: ResourceType, id: string) => void;
  onDelete: (type: ResourceType, id: string) => void;
  onDuplicate: (type: ResourceType, id: string) => void;
  onAdd: (type: ResourceType) => void;
  onConnect: (source: { type: ResourceType, id: string }, target: { type: ResourceType, id: string }) => void;
}

const getBezierPath = (x1: number, y1: number, x2: number, y2: number) => {
  const dx = Math.abs(x2 - x1);
  const curvature = Math.max(dx * 0.5, 80);
  return `M ${x1} ${y1} C ${x1 + curvature} ${y1}, ${x2 - curvature} ${y2}, ${x2} ${y2}`;
};

interface ConnectionDragState {
    isActive: boolean;
    sourceType: ResourceType | null;
    sourceId: string | null;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
}

export const FlowDesigner: React.FC<FlowDesignerProps> = ({ project, onSelect, onDelete, onDuplicate, onAdd, onConnect }) => {
  const { postTypes, customEndpoints } = project;
  const containerRef = useRef<HTMLDivElement>(null);

  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDraggingCanvas, setIsDraggingCanvas] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const [draggingNode, setDraggingNode] = useState<{ type: ResourceType, id: string } | null>(null);
  const [nodePositions, setNodePositions] = useState<Record<string, { x: number, y: number }>>({});

  const [connectionDrag, setConnectionDrag] = useState<ConnectionDragState>({
      isActive: false, sourceType: null, sourceId: null, startX: 0, startY: 0, currX: 0, currY: 0
  });

  const [contextMenu, setContextMenu] = useState<ContextMenuState>({ visible: false, x: 0, y: 0, type: null, id: null });

  useEffect(() => {
    const newPositions = { ...nodePositions };
    let hasChanges = false;

    customEndpoints.forEach((ep, i) => {
      if (!newPositions[ep.id]) {
        newPositions[ep.id] = { x: 100, y: 100 + (i * 220) };
        hasChanges = true;
      }
    });

    postTypes.forEach((pt, i) => {
      if (!newPositions[pt.id]) {
        newPositions[pt.id] = { x: 600, y: 100 + (i * 300) };
        hasChanges = true;
      }
    });

    if (hasChanges) setNodePositions(newPositions);
  }, [project.postTypes.length, project.customEndpoints.length]);

  const screenToCanvas = (sx: number, sy: number) => {
     const rect = containerRef.current?.getBoundingClientRect();
     if (!rect) return { x: 0, y: 0 };
     return {
         x: (sx - rect.left - offset.x) / scale,
         y: (sy - rect.top - offset.y) / scale
     };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    // Only drag canvas if clicking directly on background or svg
    if (e.target === containerRef.current || (e.target as HTMLElement).tagName === 'svg') {
      setIsDraggingCanvas(true);
      setDragStart({ x: e.clientX - offset.x, y: e.clientY - offset.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDraggingCanvas) {
      setOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
    } else if (draggingNode) {
      const pos = screenToCanvas(e.clientX, e.clientY);
      // Snap to grid (20px)
      const snappedX = Math.round(pos.x / 20) * 20;
      const snappedY = Math.round(pos.y / 20) * 20;

      setNodePositions(prev => ({
        ...prev,
        [draggingNode.id]: { x: snappedX - 150, y: snappedY - 20 } // Offset to center on mouse roughly
      }));
    } else if (connectionDrag.isActive) {
        const pos = screenToCanvas(e.clientX, e.clientY);
        setConnectionDrag(prev => ({ ...prev, currX: pos.x, currY: pos.y }));
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    if (connectionDrag.isActive) {
        // We need to check if we dropped on a valid target port
        // The drop target logic is handled by the mouseUp on the Port element
        setConnectionDrag(prev => ({ ...prev, isActive: false }));
    }
    setIsDraggingCanvas(false);
    setDraggingNode(null);
  };

  const handleWheel = (e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
       e.preventDefault();
       const s = Math.min(Math.max(0.4, scale + e.deltaY * -0.001), 2);
       setScale(s);
    }
  };

  const startDragNode = (e: React.MouseEvent, type: ResourceType, id: string) => {
    if (e.button !== 0) return; // Only left click
    e.stopPropagation();
    setDraggingNode({ type, id });
  };

  const startConnection = (e: React.MouseEvent, type: ResourceType, id: string, portType: 'source' | 'target') => {
      e.stopPropagation();
      e.preventDefault();
      if (portType === 'target') return; // Cannot drag FROM a target port

      const pos = screenToCanvas(e.clientX, e.clientY);
      setConnectionDrag({
          isActive: true,
          sourceType: type,
          sourceId: id,
          startX: pos.x,
          startY: pos.y,
          currX: pos.x,
          currY: pos.y
      });
  };

  const endConnection = (e: React.MouseEvent, type: ResourceType, id: string) => {
      e.stopPropagation();
      if (!connectionDrag.isActive) return;
      if (connectionDrag.sourceId === id) return; // Cannot connect to self

      onConnect(
          { type: connectionDrag.sourceType!, id: connectionDrag.sourceId! },
          { type, id }
      );
      setConnectionDrag(prev => ({ ...prev, isActive: false }));
  };

  const renderConnections = () => {
    const lines: React.ReactElement[] = [];

    // Endpoint -> Storage -> CPT
    customEndpoints.forEach(ep => {
      const startPos = nodePositions[ep.id];
      if (!startPos) return;
      const endpointRight = { x: startPos.x + 300, y: startPos.y + 60 }; 

      if (ep.storage?.enabled && ep.storage.targetCptSlug) {
        const targetCpt = postTypes.find(pt => pt.slug === ep.storage?.targetCptSlug);
        if (targetCpt && nodePositions[targetCpt.id]) {
           const targetPos = nodePositions[targetCpt.id];
           const targetLeft = { x: targetPos.x, y: targetPos.y + 30 }; // Connect to header roughly

           lines.push(
             <g key={`flow_${ep.id}_${targetCpt.id}`}>
               <path 
                 d={getBezierPath(endpointRight.x, endpointRight.y, targetLeft.x, targetLeft.y)}
                 fill="none"
                 stroke="#10b981" 
                 strokeWidth="3"
                 className="opacity-70"
               />
               <circle cx={endpointRight.x} cy={endpointRight.y} r="4" fill="#10b981" />
               <circle cx={targetLeft.x} cy={targetLeft.y} r="4" fill="#10b981" />
             </g>
           );
        }
      }
    });

    // CPT Relationships
    postTypes.forEach(pt => {
        const startPos = nodePositions[pt.id];
        if (!startPos) return;

        pt.metaFields.forEach((field, idx) => {
            if (field.type === FieldType.RELATIONSHIP && field.targetPostType) {
                const targetCpt = postTypes.find(p => p.slug === field.targetPostType);
                if (targetCpt && nodePositions[targetCpt.id] && targetCpt.id !== pt.id) {
                    const targetPos = nodePositions[targetCpt.id];

                    // Calculate exact position of the field row
                    const fieldY = startPos.y + 90 + (idx * 28); 
                    const startRight = { x: startPos.x + 300, y: fieldY };
                    const targetLeft = { x: targetPos.x, y: targetPos.y + 30 };

                    lines.push(
                        <g key={`rel_${pt.id}_${targetCpt.id}_${field.id}`}>
                            <path 
                                d={getBezierPath(startRight.x, startRight.y, targetLeft.x, targetLeft.y)}
                                fill="none"
                                stroke="#6366f1" 
                                strokeWidth="2"
                                className="opacity-60"
                            />
                            <circle cx={startRight.x} cy={startRight.y} r="3" fill="#6366f1" />
                            <circle cx={targetLeft.x} cy={targetLeft.y} r="3" fill="#6366f1" />
                        </g>
                    );
                }
            }
        });
    });

    // Temp Dragging Line
    if (connectionDrag.isActive) {
        lines.push(
            <path 
                key="temp_drag"
                d={getBezierPath(connectionDrag.startX, connectionDrag.startY, connectionDrag.currX, connectionDrag.currY)}
                fill="none"
                stroke="#fff" 
                strokeWidth="2"
                strokeDasharray="5,5"
                className="opacity-80 pointer-events-none"
            />
        );
    }

    return lines;
  };

  const NodePort = ({ type, id, portType, style }: { type: ResourceType, id: string, portType: 'source' | 'target', style?: React.CSSProperties }) => (
      <div 
        className={`absolute w-4 h-4 rounded-full border-2 border-[#09090b] flex items-center justify-center cursor-crosshair hover:scale-125 transition-transform z-50 ${portType === 'source' ? 'bg-zinc-400 hover:bg-white -right-2' : 'bg-zinc-600 hover:bg-white -left-2'}`}
        style={style}
        onMouseDown={(e) => startConnection(e, type, id, portType)}
        onMouseUp={(e) => endConnection(e, type, id)}
      />
  );

  return (
    <div 
      className="h-full w-full bg-[#09090b] relative overflow-hidden select-none" 
      ref={containerRef}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      onClick={() => setContextMenu({ ...contextMenu, visible: false })}
      style={{ cursor: isDraggingCanvas ? 'grabbing' : 'default' }}
    >
      <div 
        className="absolute inset-0 pointer-events-none opacity-[0.05]"
        style={{
           backgroundImage: 'linear-gradient(#444 1px, transparent 1px), linear-gradient(90deg, #444 1px, transparent 1px)',
           backgroundSize: `${40 * scale}px ${40 * scale}px`,
           backgroundPosition: `${offset.x}px ${offset.y}px`
        }}
      />

      {/* Controls Bar */}
      <div className="absolute top-6 left-6 z-50 flex flex-col gap-4">
          <div className="bg-zinc-900/90 backdrop-blur border border-zinc-800 rounded-xl p-1 flex shadow-2xl">
              <button onClick={() => onAdd('endpoint')} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="New Endpoint">
                <Network size={20} />
              </button>
              <button onClick={() => onAdd('postType')} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="New Model">
                <Box size={20} />
              </button>
              <div className="w-px bg-zinc-800 mx-1 my-2"></div>
              <button onClick={() => { setScale(1); setOffset({x:0,y:0}); }} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="Reset View">
                <Move size={20} />
              </button>
          </div>

          <div className="bg-zinc-900/80 backdrop-blur p-4 rounded-xl border border-zinc-800 text-xs text-zinc-500 max-w-xs pointer-events-none">
             <p className="font-bold text-zinc-300 mb-1">Interactive Schema</p>
             <ul className="list-disc pl-4 space-y-1">
                 <li>Drag handle on Endpoint → CPT to create storage mapping.</li>
                 <li>Drag handle on CPT → CPT to create relationship field.</li>
                 <li>Double click node to edit.</li>
             </ul>
          </div>
      </div>

      {/* Canvas */}
      <div 
        className="absolute inset-0 origin-top-left"
        style={{
            transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`
        }}
      >
         <svg className="absolute inset-0 overflow-visible w-full h-full pointer-events-none z-0">
             {renderConnections()}
         </svg>

         <div className="relative z-10">
            {/* Endpoint Nodes */}
            {customEndpoints.map(ep => (
                <div
                    key={ep.id}
                    className="absolute w-[300px] bg-[#121214] rounded-lg shadow-[0_10px_40px_-10px_rgba(0,0,0,0.5)] border border-zinc-800 group hover:border-pink-500/50 transition-all duration-200"
                    style={{ 
                        left: nodePositions[ep.id]?.x || 0, 
                        top: nodePositions[ep.id]?.y || 0,
                    }}
                    onMouseDown={(e) => startDragNode(e, 'endpoint', ep.id)}
                    onDoubleClick={(e) => { e.stopPropagation(); onSelect('endpoint', ep.id); }}
                    onContextMenu={(e) => { e.preventDefault(); setContextMenu({ visible: true, x: e.clientX, y: e.clientY, type: 'endpoint', id: ep.id }); }}
                >
                    {/* Source Port */}
                    <NodePort type="endpoint" id={ep.id} portType="source" style={{ top: 60 }} />

                    {/* Header */}
                    <div className="px-3 py-2 bg-zinc-900 border-b border-zinc-800 flex items-center justify-between rounded-t-lg">
                        <div className="flex items-center gap-2">
                             <span className={`text-[10px] font-bold px-1 rounded ${
                                    ep.method === 'GET' ? 'bg-blue-500/20 text-blue-400' : 
                                    ep.method === 'POST' ? 'bg-green-500/20 text-green-400' : 
                                    'bg-orange-500/20 text-orange-400'
                                }`}>
                                    {ep.method}
                            </span>
                            <span className="text-xs font-bold text-zinc-200 font-mono truncate max-w-[180px]" title={ep.route}>{ep.route}</span>
                        </div>
                        <Network size={14} className="text-pink-500" />
                    </div>

                    {/* Body */}
                    <div className="p-2 space-y-1">
                        <div className="text-[10px] text-zinc-500 font-mono pl-1 uppercase mb-1">Params</div>
                        {ep.parameters.length === 0 && <div className="pl-2 text-[10px] text-zinc-600 italic">No params</div>}
                        {ep.parameters.slice(0,4).map(p => (
                            <div key={p.id} className="flex justify-between items-center px-2 py-1 bg-zinc-900/30 rounded">
                                <span className="text-xs text-pink-300 font-mono">{p.key}</span>
                                <span className="text-[10px] text-zinc-500">{p.type}</span>
                            </div>
                        ))}

                        {ep.storage?.enabled && (
                            <div className="mt-2 pt-2 border-t border-zinc-800">
                                <div className="flex items-center gap-2 text-[10px] text-green-400 bg-green-900/10 p-1.5 rounded border border-green-900/20">
                                    <Database size={10} />
                                    Writes to: <span className="font-bold">{ep.storage.targetCptSlug}</span>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            ))}

            {/* Post Type Nodes */}
            {postTypes.map(pt => (
                <div
                    key={pt.id}
                    className="absolute w-[300px] bg-[#121214] rounded-lg shadow-[0_10px_40px_-10px_rgba(0,0,0,0.5)] border border-zinc-800 group hover:border-indigo-500/50 transition-all duration-200"
                    style={{ 
                        left: nodePositions[pt.id]?.x || 0, 
                        top: nodePositions[pt.id]?.y || 0,
                    }}
                    onMouseDown={(e) => startDragNode(e, 'postType', pt.id)}
                    onDoubleClick={(e) => { e.stopPropagation(); onSelect('postType', pt.id); }}
                    onContextMenu={(e) => { e.preventDefault(); setContextMenu({ visible: true, x: e.clientX, y: e.clientY, type: 'postType', id: pt.id }); }}
                >
                    {/* Ports */}
                    <NodePort type="postType" id={pt.id} portType="target" style={{ top: 30 }} />
                    <NodePort type="postType" id={pt.id} portType="source" style={{ top: 30 }} />

                    <div className="px-3 py-2 bg-zinc-900 border-b border-zinc-800 flex items-center justify-between rounded-t-lg">
                        <div className="flex items-center gap-2">
                             <Table size={14} className="text-indigo-500" />
                             <span className="text-sm font-bold text-zinc-100">{pt.singularName}</span>
                        </div>
                        <span className="text-[10px] text-zinc-500 font-mono">{pt.slug}</span>
                    </div>

                    <div className="p-0">
                         {/* Native Fields (Simulated) */}
                         <div className="px-3 py-1.5 border-b border-zinc-800/50 flex justify-between items-center bg-zinc-900/20">
                             <div className="flex items-center gap-2">
                                 <Key size={10} className="text-yellow-600" />
                                 <span className="text-xs text-zinc-400 font-mono">ID</span>
                             </div>
                             <span className="text-[10px] text-zinc-600">int</span>
                         </div>
                         <div className="px-3 py-1.5 border-b border-zinc-800/50 flex justify-between items-center bg-zinc-900/20">
                             <span className="text-xs text-zinc-400 font-mono pl-4">post_title</span>
                             <span className="text-[10px] text-zinc-600">string</span>
                         </div>

                         {/* Meta Fields */}
                         {pt.metaFields.map(mf => (
                             <div key={mf.id} className="px-3 py-1.5 border-b border-zinc-800/30 flex justify-between items-center hover:bg-zinc-800/30 transition-colors relative group/field">
                                 <div className="flex items-center gap-2">
                                     {mf.type === FieldType.RELATIONSHIP ? <LinkIcon size={10} className="text-indigo-500"/> : <List size={10} className="text-zinc-600"/>}
                                     <span className={`text-xs font-mono ${mf.type === FieldType.RELATIONSHIP ? 'text-indigo-300' : 'text-zinc-300'}`}>{mf.key}</span>
                                 </div>
                                 <span className="text-[10px] text-zinc-500">{mf.type}</span>

                                 {/* Source handle for field if needed, simplified to whole node for now */}
                             </div>
                         ))}

                         <div onClick={() => onSelect('postType', pt.id)} className="px-3 py-2 text-xs text-zinc-500 hover:text-indigo-400 cursor-pointer hover:bg-zinc-800/50 rounded-b-lg flex items-center gap-1 transition-colors">
                             <Edit size={12} /> Edit Schema
                         </div>
                    </div>
                </div>
            ))}
         </div>
      </div>

       {contextMenu.visible && (
        <div 
          className="fixed bg-[#18181b] border border-zinc-700 rounded-lg shadow-xl py-1 z-[100] min-w-[160px] animate-in fade-in zoom-in-95 duration-100"
          style={{ top: contextMenu.y, left: contextMenu.x }}
          onClick={(e) => e.stopPropagation()}
        >
          <button 
            onClick={() => { onSelect(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
            className="w-full text-left px-4 py-2 text-sm text-zinc-300 hover:bg-indigo-600 hover:text-white flex items-center gap-2"
          >
            <Edit size={14} /> Edit
          </button>
          <button 
             onClick={() => { onDuplicate(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
             className="w-full text-left px-4 py-2 text-sm text-zinc-300 hover:bg-indigo-600 hover:text-white flex items-center gap-2"
          >
            <Copy size={14} /> Duplicate
          </button>
          <div className="h-px bg-zinc-700 my-1"></div>
          <button 
             onClick={() => { onDelete(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
             className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-red-900/30 flex items-center gap-2"
          >
            <Trash2 size={14} /> Delete
          </button>
        </div>
      )}
    </div>
  );
};

export enum FieldType {
  STRING = 'string',
  INTEGER = 'integer',
  NUMBER = 'number',
  BOOLEAN = 'boolean',
  ARRAY = 'array',
  RELATIONSHIP = 'relationship',
  REPEATER = 'repeater',
}

export interface MetaField {
  id: string;
  key: string;
  label: string;
  type: FieldType;
  description: string;
  required: boolean;
  showInRest: boolean;
  targetPostType?: string; // For relationship types
  subFields?: MetaField[]; // For repeater types
}

export interface Taxonomy {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  hierarchical: boolean;
  showInRest: boolean;
  connectedPostTypes: string[]; // CPT slugs
  ui?: { x: number; y: number };
}

export interface CustomPostType {
  id: string;
  slug: string;
  singularName: string;
  pluralName: string;
  description: string;
  icon: string; 
  supports: string[];
  taxonomies: string[]; 
  metaFields: MetaField[];
  showInRest: boolean;
  restBase: string;
  ui?: { x: number; y: number };
}

export type EndpointMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';

export interface EndpointParameter {
  id: string;
  key: string;
  required: boolean;
  type: string;
  description: string;
}

export interface StorageMapping {
  enabled: boolean;
  targetCptSlug: string;
  fieldMapping: Record<string, string>;
}

export interface CustomEndpoint {
  id: string;
  route: string;
  method: EndpointMethod;
  callbackFunction: string;
  description: string;
  parameters: EndpointParameter[];
  hookName?: string;
  storage?: StorageMapping;
  customPhp?: string;
  ui?: { x: number; y: number };
}

export interface GlobalHelper {
  id: string;
  name: string;
  parameters: string; // Comma separated string for simplicity in UI
  phpCode: string;
  description: string;
}

export interface ProjectState {
  name: string;
  namespace: string;
  postTypes: CustomPostType[];
  taxonomies: Taxonomy[];
  customEndpoints: CustomEndpoint[];
  globalHelpers: GlobalHelper[];
}

export type ViewMode = 'editor' | 'openapi' | 'php' | 'flow' | 'settings' | 'blueprint' | 'code';
export type ResourceType = 'postType' | 'endpoint' | 'taxonomy' | 'helper';

export interface ContextMenuState {
  visible: boolean;
  x: number;
  y: number;
  type: ResourceType | null;
  id: string | null;
}

export enum AIProvider {
  GEMINI = 'gemini',
  CHROME_LOCAL = 'chrome_local'
}

export interface AppSettings {
  provider: AIProvider;
  apiKey: string;
  model: string;
  temperature: number;
}

export type LogLevel = 'info' | 'success' | 'warning' | 'error';

export interface LogEntry {
  id: string;
  timestamp: Date;
  level: LogLevel;
  message: string;
  details?: any;
}

import React from 'react';
import { ProjectState, ResourceType, ViewMode } from '../types';
import { 
  Box, 
  Code, 
  GitBranch, 
  Plus, 
  FileJson,
  Network,
  Settings as SettingsIcon,
  Terminal as TerminalIcon,
  Map,
  Tag,
  Zap,
  Braces
} from 'lucide-react';

interface SidebarProps {
  project: ProjectState;
  currentView: ViewMode;
  selection: { type: ResourceType; id: string };
  isTerminalOpen: boolean;
  onSelect: (type: ResourceType, id: string) => void;
  onViewChange: (view: ViewMode) => void;
  onAddResource: () => void;
  onAddEndpoint: () => void;
  onAddTaxonomy: () => void;
  onToggleTerminal: () => void;
  onOpenAI: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({
  project,
  currentView,
  selection,
  isTerminalOpen,
  onSelect,
  onViewChange,
  onAddResource,
  onAddEndpoint,
  onAddTaxonomy,
  onToggleTerminal,
  onOpenAI
}) => {

  const SectionHeader = ({ label }: { label: string }) => (
    <div className="px-4 mt-6 mb-2 text-[10px] font-bold text-zinc-500 uppercase tracking-widest">{label}</div>
  );

  const NavItem = ({ 
    active, 
    onClick, 
    icon: Icon, 
    label, 
    subLabel 
  }: { 
    active: boolean; 
    onClick: () => void; 
    icon: any; 
    label: string; 
    subLabel?: string 
  }) => (
    <button
      onClick={onClick}
      className={`w-full text-left px-3 py-1.5 mx-2 rounded-md flex items-center gap-3 transition-all group ${
        active 
          ? 'bg-zinc-800 text-white shadow-sm' 
          : 'text-zinc-400 hover:bg-zinc-900 hover:text-zinc-200'
      }`}
      style={{ width: 'calc(100% - 16px)' }}
    >
      <Icon size={16} className={`${active ? 'text-indigo-400' : 'text-zinc-500 group-hover:text-zinc-400'}`} />
      <div className="flex flex-col leading-none">
        <span className="text-sm font-medium">{label}</span>
        {subLabel && <span className="text-[10px] text-zinc-500 mt-0.5 font-mono">{subLabel}</span>}
      </div>
    </button>
  );

  const AddButton = ({ onClick, label }: { onClick: () => void, label: string }) => (
    <button 
      onClick={onClick}
      className="ml-4 mt-1 text-xs text-zinc-500 hover:text-indigo-400 flex items-center gap-1.5 transition-colors px-2 py-1 rounded hover:bg-zinc-900 w-fit"
    >
      <Plus size={12} /> {label}
    </button>
  );

  return (
    <div className="w-64 bg-[#121214] flex flex-col border-r border-zinc-800 h-full">
      {/* Brand Header */}
      <div className="h-14 flex items-center px-4 border-b border-zinc-800/50">
        <div className="w-6 h-6 bg-indigo-600 rounded flex items-center justify-center mr-3 shadow-lg shadow-indigo-500/20">
          <Zap size={14} className="text-white fill-white" />
        </div>
        <span className="font-bold text-sm tracking-wide text-zinc-100">API Architect</span>
      </div>

      <div className="flex-1 overflow-y-auto py-2 custom-scrollbar">

        <SectionHeader label="Core Architecture" />
        <NavItem 
          active={currentView === 'flow'} 
          onClick={() => onViewChange('flow')} 
          icon={GitBranch} 
          label="Flow Designer" 
        />
        <NavItem 
          active={currentView === 'blueprint'} 
          onClick={() => onViewChange('blueprint')} 
          icon={Map} 
          label="Blueprint" 
        />
        <NavItem 
          active={currentView === 'code'} 
          onClick={() => onViewChange('code')} 
          icon={Braces} 
          label="Global Logic"
          subLabel="Helper Functions"
        />

        <SectionHeader label="Content Models" />
        <div className="space-y-0.5">
          {project.postTypes.map(pt => (
            <NavItem 
              key={pt.id}
              active={selection.id === pt.id && selection.type === 'postType'} 
              onClick={() => onSelect('postType', pt.id)} 
              icon={Box} 
              label={pt.pluralName}
              subLabel={pt.slug}
            />
          ))}
          <AddButton onClick={onAddResource} label="New Model" />
        </div>

        <SectionHeader label="Endpoints" />
        <div className="space-y-0.5">
          {project.customEndpoints.map(ep => (
            <NavItem 
              key={ep.id}
              active={selection.id === ep.id && selection.type === 'endpoint'} 
              onClick={() => onSelect('endpoint', ep.id)} 
              icon={Network} 
              label={ep.route}
              subLabel={ep.method}
            />
          ))}
          <AddButton onClick={onAddEndpoint} label="New Route" />
        </div>

        <SectionHeader label="Taxonomies" />
        <div className="space-y-0.5">
           {project.taxonomies.map(tax => (
             <NavItem
               key={tax.id}
               active={selection.id === tax.id && selection.type === 'taxonomy'}
               onClick={() => onSelect('taxonomy', tax.id)}
               icon={Tag}
               label={tax.pluralName}
             />
           ))}
           <AddButton onClick={onAddTaxonomy} label="New Taxonomy" />
        </div>

        <SectionHeader label="Build" />
        <NavItem active={currentView === 'openapi'} onClick={() => onViewChange('openapi')} icon={FileJson} label="OpenAPI Spec" />
        <NavItem active={currentView === 'php'} onClick={() => onViewChange('php')} icon={Code} label="Code Export" />
        <NavItem active={currentView === 'settings'} onClick={() => onViewChange('settings')} icon={SettingsIcon} label="Settings" />

      </div>

      {/* Footer Controls */}
      <div className="p-3 border-t border-zinc-800 bg-[#0e0e11] space-y-2">
        <button 
          onClick={onToggleTerminal}
          className={`w-full py-2 px-3 rounded-md flex items-center gap-2 text-xs font-mono transition-all border ${
            isTerminalOpen 
              ? 'bg-zinc-800 text-green-400 border-zinc-700' 
              : 'text-zinc-500 border-transparent hover:bg-zinc-800/50'
          }`}
        >
          <TerminalIcon size={14} /> 
          <span className="flex-1 text-left">{isTerminalOpen ? 'Hide Console' : 'Show Console'}</span>
        </button>

        <button 
          onClick={onOpenAI}
          className="w-full bg-indigo-600 hover:bg-indigo-500 text-white py-2 px-3 rounded-md shadow-lg shadow-indigo-900/20 flex items-center justify-center gap-2 text-xs font-bold tracking-wide transition-all border border-indigo-500/50"
        >
          <Zap size={14} className="fill-white" /> AI GENERATE
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ProjectState, GlobalHelper } from '../types';
