const Minimap = React.memo(({ nodes, viewport }: any) => {
    const bounds = useMemo(() => {
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        if (Object.keys(nodes).length === 0) return { x: 0, y: 0, w: 100, h: 100 };
        Object.values(nodes).forEach((n: any) => {
            minX = Math.min(minX, n.x);
            minY = Math.min(minY, n.y);
            maxX = Math.max(maxX, n.x + 280);
            maxY = Math.max(maxY, n.y + 200);
        });
        return { x: minX - 100, y: minY - 100, w: (maxX - minX) + 200, h: (maxY - minY) + 200 };
    }, [nodes]);

    const MM_WIDTH = 160;
    const MM_HEIGHT = 100;

    const mapX = (x: number) => ((x - bounds.x) / bounds.w) * MM_WIDTH;
    const mapY = (y: number) => ((y - bounds.y) / bounds.h) * MM_HEIGHT;

    const vpW = 1000 / viewport.scale;
    const vpH = 800 / viewport.scale;
    const vpX = -viewport.x / viewport.scale;
    const vpY = -viewport.y / viewport.scale;

    return (
        <div className="absolute bottom-6 right-6 w-[160px] h-[100px] bg-zinc-900 border border-zinc-700 rounded-lg shadow-2xl overflow-hidden opacity-80 hover:opacity-100 transition-opacity z-50 pointer-events-none">
            {Object.entries(nodes).map(([id, pos]: any) => (
                <div 
                    key={id}
                    className="absolute bg-zinc-600 rounded-sm"
                    style={{
                        left: mapX(pos.x),
                        top: mapY(pos.y),
                        width: (280 / bounds.w) * MM_WIDTH,
                        height: (100 / bounds.h) * MM_HEIGHT,
                    }}
                />
            ))}
            <div 
                className="absolute border border-indigo-500 bg-indigo-500/10"
                style={{
                    left: mapX(vpX),
                    top: mapY(vpY),
                    width: (vpW / bounds.w) * MM_WIDTH,
                    height: (vpH / bounds.h) * MM_HEIGHT,
                }}
            />
        </div>
    );
});


export const FlowDesigner: React.FC<FlowDesignerProps> = ({ project, onSelect, onDelete, onDuplicate, onAdd, onConnect }) => {
  const { postTypes, customEndpoints, taxonomies } = project;
  const containerRef = useRef<HTMLDivElement>(null);

  const [viewport, setViewport] = useState({ x: 0, y: 0, scale: 1 });
  const [isDraggingCanvas, setIsDraggingCanvas] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [showGrid, setShowGrid] = useState(true);

  const [draggingNode, setDraggingNode] = useState<{ type: ResourceType, id: string } | null>(null);
  const [nodePositions, setNodePositions] = useState<Record<string, { x: number, y: number }>>({});

  const [connectionDrag, setConnectionDrag] = useState<{
      isActive: boolean;
      sourceType: ResourceType | null;
      sourceId: string | null;
      startX: number;
      startY: number;
      currX: number;
      currY: number;
  }>({
      isActive: false, sourceType: null, sourceId: null, startX: 0, startY: 0, currX: 0, currY: 0
  });

  const [contextMenu, setContextMenu] = useState<ContextMenuState>({ visible: false, x: 0, y: 0, type: null, id: null });

  // SMART AUTO-LAYOUT
  useEffect(() => {
    setNodePositions(prev => {
        // If positions already exist for all nodes, don't re-layout constantly
        const allKeys = [...postTypes.map(p=>p.id), ...customEndpoints.map(e=>e.id), ...taxonomies.map(t=>t.id)];
        if (allKeys.every(k => prev[k])) return prev;

        const next = { ...prev };

        // Constants for grid
        const START_X = 400;
        const START_Y = 150;
        const COL_GAP = 400;
        const ROW_GAP = 280;

        // 1. Place CPTs (Backbone)
        postTypes.forEach((pt, i) => {
            if (!next[pt.id]) {
                next[pt.id] = { x: START_X, y: START_Y + (i * ROW_GAP) };
            }
        });

        // 2. Place Endpoints (Left of CPTs)
        customEndpoints.forEach((ep, i) => {
            if (!next[ep.id]) {
                let y = START_Y + (i * 200); // Default stack
                let x = START_X - COL_GAP;

                // Smart: Align with Target CPT
                if (ep.storage?.enabled && ep.storage.targetCptSlug) {
                    const targetCpt = postTypes.find(p => p.slug === ep.storage?.targetCptSlug);
                    if (targetCpt && next[targetCpt.id]) {
                        y = next[targetCpt.id].y;
                        // Avoid direct overlap if multiple endpoints target same CPT
                        // Simple jitter
                        y += (Math.random() * 60 - 30);
                    }
                }
                next[ep.id] = { x, y };
            }
        });

        // 3. Place Taxonomies (Right of CPTs)
        taxonomies.forEach((tax, i) => {
            if (!next[tax.id]) {
                 let y = START_Y + (i * 150);
                 let x = START_X + COL_GAP;

                 // Smart: Align with connected CPT (first found)
                 if (tax.connectedPostTypes.length > 0) {
                     const connectedSlug = tax.connectedPostTypes[0];
                     const targetCpt = postTypes.find(p => p.slug === connectedSlug);
                     if (targetCpt && next[targetCpt.id]) {
                         y = next[targetCpt.id].y;
                         y += (Math.random() * 60 - 30);
                     }
                 }
                 next[tax.id] = { x, y };
            }
        });

        return next;
    });
  }, [postTypes.length, customEndpoints.length, taxonomies.length]); 

  const screenToCanvas = useCallback((sx: number, sy: number) => {
     const rect = containerRef.current?.getBoundingClientRect();
     if (!rect) return { x: 0, y: 0 };
     return {
         x: (sx - rect.left - viewport.x) / viewport.scale,
         y: (sy - rect.top - viewport.y) / viewport.scale
     };
  }, [viewport]);

  // Handlers
  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.target === containerRef.current || (e.target as HTMLElement).tagName === 'svg') {
      setIsDraggingCanvas(true);
      setDragStart({ x: e.clientX - viewport.x, y: e.clientY - viewport.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDraggingCanvas) {
      setViewport(prev => ({ ...prev, x: e.clientX - dragStart.x, y: e.clientY - dragStart.y }));
    } else if (draggingNode) {
      const pos = screenToCanvas(e.clientX, e.clientY);
      // Precision Snap
      const GRID_SIZE = showGrid ? 20 : 1;
      const snappedX = Math.round((pos.x - 140) / GRID_SIZE) * GRID_SIZE; // Center node (w=280)
      const snappedY = Math.round((pos.y - 20) / GRID_SIZE) * GRID_SIZE;

      setNodePositions(prev => ({
        ...prev,
        [draggingNode.id]: { x: snappedX, y: snappedY }
      }));
    } else if (connectionDrag.isActive) {
        const pos = screenToCanvas(e.clientX, e.clientY);
        setConnectionDrag(prev => ({ ...prev, currX: pos.x, currY: pos.y }));
    }
  };

  const handleMouseUp = () => {
    setIsDraggingCanvas(false);
    setDraggingNode(null);
    if (connectionDrag.isActive) {
        setConnectionDrag(prev => ({ ...prev, isActive: false }));
    }
  };

  const handleWheel = (e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
       e.preventDefault();
       const zoomSensitivity = 0.001;
       const newScale = Math.min(Math.max(0.2, viewport.scale - e.deltaY * zoomSensitivity), 3);
       setViewport(prev => ({ ...prev, scale: newScale }));
    } else {
        setViewport(prev => ({ ...prev, x: prev.x - e.deltaX, y: prev.y - e.deltaY }));
    }
  };

  // Node Interactions
  const startDragNode = useCallback((e: React.MouseEvent, type: ResourceType, id: string) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    setDraggingNode({ type, id });
  }, []);

  const handleStartConnection = useCallback((e: React.MouseEvent, type: ResourceType, id: string, portType: 'source' | 'target') => {
      e.stopPropagation();
      e.preventDefault();
      if (portType === 'target') return;

      const nodePos = nodePositions[id] || {x:0,y:0};

      setConnectionDrag({
          isActive: true,
          sourceType: type,
          sourceId: id,
          startX: nodePos.x + 280, // Approximate right side
          startY: nodePos.y + 50,
          currX: nodePos.x + 280,
          currY: nodePos.y + 50
      });
  }, [nodePositions]);

  const handleEndConnection = useCallback((e: React.MouseEvent, type: ResourceType, id: string) => {
      e.stopPropagation();
      setConnectionDrag(prev => {
          if (!prev.isActive) return prev;
          if (prev.sourceId === id) return prev;

          onConnect(
             { type: prev.sourceType!, id: prev.sourceId! },
             { type, id }
          );
          return { ...prev, isActive: false };
      });
  }, [onConnect]);

  const handleContextMenu = useCallback((e: React.MouseEvent, type: ResourceType, id: string) => {
      e.preventDefault();
      setContextMenu({ visible: true, x: e.clientX, y: e.clientY, type, id });
  }, []);

  // Render Connections
  const connections = useMemo(() => {
    const lines: React.ReactElement[] = [];

    // Endpoint -> Storage
    customEndpoints.forEach(ep => {
      const startPos = nodePositions[ep.id];
      if (!startPos) return;
      const epRight = { x: startPos.x + 280, y: startPos.y + 58 }; 

      if (ep.storage?.enabled && ep.storage.targetCptSlug) {
        const targetCpt = postTypes.find(pt => pt.slug === ep.storage?.targetCptSlug);
        if (targetCpt && nodePositions[targetCpt.id]) {
           const targetPos = nodePositions[targetCpt.id];
           const targetLeft = { x: targetPos.x, y: targetPos.y + 30 };

           lines.push(
             <g key={`link_${ep.id}_${targetCpt.id}`}>
               <path 
                 d={getBezierPath(epRight.x, epRight.y, targetLeft.x, targetLeft.y)}
                 fill="none"
                 stroke="#10b981" 
                 strokeWidth="2"
                 className="opacity-60"
               />
               <circle cx={epRight.x} cy={epRight.y} r="2" fill="#10b981" />
               <circle cx={targetLeft.x} cy={targetLeft.y} r="2" fill="#10b981" />
             </g>
           );
        }
      }
    });

    // CPT Relationships
    postTypes.forEach(pt => {
        const startPos = nodePositions[pt.id];
        if (!startPos) return;

        pt.metaFields.forEach((field, idx) => {
            if (field.type === FieldType.RELATIONSHIP && field.targetPostType) {
                const targetCpt = postTypes.find(p => p.slug === field.targetPostType);
                if (targetCpt && nodePositions[targetCpt.id] && targetCpt.id !== pt.id) {
                    const targetPos = nodePositions[targetCpt.id];
                    const fieldY = startPos.y + 76 + (idx * 29) + 14; 
                    const startRight = { x: startPos.x + 280, y: fieldY };
                    const targetLeft = { x: targetPos.x, y: targetPos.y + 30 };

                    lines.push(
                        <g key={`rel_${pt.id}_${targetCpt.id}_${field.id}`}>
                            <path 
                                d={getBezierPath(startRight.x, startRight.y, targetLeft.x, targetLeft.y)}
                                fill="none"
                                stroke="#6366f1" 
                                strokeWidth="2"
                                strokeDasharray="5,5"
                                className="opacity-50"
                            />
                            <circle cx={startRight.x} cy={startRight.y} r="2" fill="#6366f1" />
                        </g>
                    );
                }
            }
        });
    });

    // Taxonomy Connections (Visual only)
    taxonomies.forEach(tax => {
        const taxPos = nodePositions[tax.id];
        if (!taxPos) return;
        const taxLeft = { x: taxPos.x, y: taxPos.y + 30 };

        tax.connectedPostTypes.forEach(slug => {
            const cpt = postTypes.find(p => p.slug === slug);
            if (cpt && nodePositions[cpt.id]) {
                const cptPos = nodePositions[cpt.id];
                const cptRight = { x: cptPos.x + 280, y: cptPos.y + 30 };

                lines.push(
                     <g key={`tax_${tax.id}_${cpt.id}`}>
                        <path 
                            d={getBezierPath(cptRight.x, cptRight.y, taxLeft.x, taxLeft.y)}
                            fill="none"
                            stroke="#ec4899" 
                            strokeWidth="1"
                            strokeDasharray="2,2"
                            className="opacity-30"
                        />
                    </g>
                );
            }
        });
    });

    return lines;
  }, [project, nodePositions]);

  return (
    <div 
      className="h-full w-full bg-[#09090b] relative overflow-hidden select-none font-sans" 
      ref={containerRef}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      onWheel={handleWheel}
      onClick={() => setContextMenu({ ...contextMenu, visible: false })}
      style={{ cursor: isDraggingCanvas ? 'grabbing' : 'default' }}
    >
      {/* Grid Pattern */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-[0.07]"
        style={{
           backgroundImage: showGrid 
             ? 'linear-gradient(#444 1px, transparent 1px), linear-gradient(90deg, #444 1px, transparent 1px)'
             : 'radial-gradient(#444 1px, transparent 0)',
           backgroundSize: `${(showGrid ? 20 : 40) * viewport.scale}px ${(showGrid ? 20 : 40) * viewport.scale}px`,
           backgroundPosition: `${viewport.x}px ${viewport.y}px`
        }}
      />

      {/* Canvas Layer */}
      <div 
        className="absolute inset-0 origin-top-left will-change-transform"
        style={{
            transform: `translate(${viewport.x}px, ${viewport.y}px) scale(${viewport.scale})`
        }}
      >
         <svg className="absolute inset-0 overflow-visible w-full h-full pointer-events-none z-0">
             {connections}
             {connectionDrag.isActive && (
                <path 
                    d={getBezierPath(connectionDrag.startX, connectionDrag.startY, connectionDrag.currX, connectionDrag.currY)}
                    fill="none"
                    stroke="#fff" 
                    strokeWidth="2"
                    strokeDasharray="5,5"
                    className="opacity-80"
                />
             )}
         </svg>

         {/* Nodes Layer */}
         <div className="relative z-10">
            {customEndpoints.map(ep => (
                <EndpointNode 
                    key={ep.id}
                    id={ep.id}
                    data={ep}
                    x={nodePositions[ep.id]?.x || 0}
                    y={nodePositions[ep.id]?.y || 0}
                    onDragStart={startDragNode}
                    onSelect={onSelect}
                    onContextMenu={handleContextMenu}
                    onStartConnection={handleStartConnection}
                    onEndConnection={handleEndConnection}
                />
            ))}
            {postTypes.map(pt => (
                <CPTNode 
                    key={pt.id}
                    id={pt.id}
                    data={pt}
                    x={nodePositions[pt.id]?.x || 0}
                    y={nodePositions[pt.id]?.y || 0}
                    onDragStart={startDragNode}
                    onSelect={onSelect}
                    onContextMenu={handleContextMenu}
                    onStartConnection={handleStartConnection}
                    onEndConnection={handleEndConnection}
                />
            ))}
            {taxonomies.map(tax => (
                <TaxonomyNode 
                    key={tax.id}
                    id={tax.id}
                    data={tax}
                    x={nodePositions[tax.id]?.x || 0}
                    y={nodePositions[tax.id]?.y || 0}
                    onDragStart={startDragNode}
                    onSelect={onSelect}
                    onContextMenu={handleContextMenu}
                />
            ))}
         </div>
      </div>

      {/* Overlay UI Controls */}
      <div className="absolute top-6 left-6 z-50 flex flex-col gap-4">
          <div className="bg-zinc-900/90 backdrop-blur border border-zinc-800 rounded-xl p-1 flex shadow-2xl">
              <button onClick={() => onAdd('endpoint')} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="New Endpoint">
                <Network size={20} />
              </button>
              <button onClick={() => onAdd('postType')} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="New Model">
                <Box size={20} />
              </button>
              <button onClick={() => onAdd('taxonomy')} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="New Taxonomy">
                <Tag size={20} />
              </button>
              <div className="w-px bg-zinc-800 mx-1 my-2"></div>
              <button onClick={() => setViewport({x:0,y:0,scale:1})} className="p-2.5 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="Reset View">
                <Maximize size={20} />
              </button>
          </div>
      </div>

      <div className="absolute bottom-6 left-6 z-50 flex items-center gap-2">
         <div className="bg-zinc-900/90 backdrop-blur border border-zinc-800 rounded-lg p-1 flex items-center">
            <button onClick={() => setViewport(v => ({...v, scale: v.scale - 0.1}))} className="p-2 hover:bg-zinc-800 rounded text-zinc-400"><ZoomOut size={16} /></button>
            <span className="text-xs text-zinc-500 w-12 text-center font-mono">{Math.round(viewport.scale * 100)}%</span>
            <button onClick={() => setViewport(v => ({...v, scale: v.scale + 0.1}))} className="p-2 hover:bg-zinc-800 rounded text-zinc-400"><ZoomIn size={16} /></button>
         </div>
         <button 
           onClick={() => setShowGrid(!showGrid)} 
           className={`p-2 rounded-lg border ${showGrid ? 'bg-indigo-500/20 border-indigo-500/50 text-indigo-400' : 'bg-zinc-900 border-zinc-800 text-zinc-500'}`}
         >
            <Grid size={18} />
         </button>
         <div className="bg-zinc-900/80 px-3 py-1.5 rounded-lg border border-zinc-800 text-[10px] text-zinc-500 font-mono">
            X: {Math.round(-viewport.x)} Y: {Math.round(-viewport.y)}
         </div>
      </div>

      <Minimap nodes={nodePositions} viewport={viewport} />

      {/* Context Menu */}
      {contextMenu.visible && (
        <div 
          className="fixed bg-[#18181b] border border-zinc-700 rounded-lg shadow-xl py-1 z-[100] min-w-[160px] animate-in fade-in zoom-in-95 duration-100"
          style={{ top: contextMenu.y, left: contextMenu.x }}
          onClick={(e) => e.stopPropagation()}
        >
          <button 
            onClick={() => { onSelect(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
            className="w-full text-left px-4 py-2 text-sm text-zinc-300 hover:bg-indigo-600 hover:text-white flex items-center gap-2"
          >
            <Edit size={14} /> Edit
          </button>
          <button 
             onClick={() => { onDuplicate(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
             className="w-full text-left px-4 py-2 text-sm text-zinc-300 hover:bg-indigo-600 hover:text-white flex items-center gap-2"
          >
            <Copy size={14} /> Duplicate
          </button>
          <div className="h-px bg-zinc-700 my-1"></div>
          <button 
             onClick={() => { onDelete(contextMenu.type!, contextMenu.id!); setContextMenu({ ...contextMenu, visible: false }); }}
             className="w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-red-900/30 flex items-center gap-2"
          >
            <Trash2 size={14} /> Delete
          </button>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { CustomEndpoint, EndpointMethod, EndpointParameter, CustomPostType } from '../types';
import { Trash2, Settings, Plus, Network, Database, ArrowRight, Code } from 'lucide-react';
import { CodeEditor } from './CodeEditor';

interface EndpointEditorProps {
  endpoint: CustomEndpoint;
  namespace: string;
  postTypes: CustomPostType[];
  onChange: (updated: CustomEndpoint) => void;
  onDelete: () => void;
}

export const EndpointEditor: React.FC<EndpointEditorProps> = ({ endpoint, namespace, postTypes, onChange, onDelete }) => {

  const handleParamChange = (id: string, changes: Partial<EndpointParameter>) => {
    const updatedParams = endpoint.parameters.map(p => p.id === id ? { ...p, ...changes } : p);
    onChange({ ...endpoint, parameters: updatedParams });
  };

  const addParam = () => {
    const newParam: EndpointParameter = {
      id: `param_${Date.now()}`,
      key: 'new_param',
      type: 'string',
      required: false,
      description: ''
    };
    onChange({ ...endpoint, parameters: [...endpoint.parameters, newParam] });
  };

  const removeParam = (id: string) => {
    onChange({ ...endpoint, parameters: endpoint.parameters.filter(p => p.id !== id) });
  };

  const handleStorageToggle = (enabled: boolean) => {
    // Default to first available CPT if enabling
    const defaultSlug = endpoint.storage?.targetCptSlug || (postTypes[0]?.slug || '');

    // Trigger auto-map immediately if enabling
    let initialMapping: Record<string, string> = endpoint.storage?.fieldMapping || {};

    if (enabled && Object.keys(initialMapping).length === 0 && defaultSlug) {
        initialMapping = generateAutoMapping(defaultSlug);
    }

    onChange({
      ...endpoint,
      storage: {
        enabled,
        targetCptSlug: defaultSlug,
        fieldMapping: initialMapping
      }
    });
  };

  const generateAutoMapping = (cptSlug: string): Record<string, string> => {
    const target = postTypes.find(pt => pt.slug === cptSlug);
    const newMapping: Record<string, string> = {};

    if (target) {
        endpoint.parameters.forEach(param => {
            const pKey = param.key.toLowerCase();

            // 1. Native WP Field Heuristics
            if (['title', 'name', 'subject', 'headline', 'label'].includes(pKey)) {
                newMapping[param.key] = 'post_title';
            } 
            else if (['content', 'body', 'description', 'message', 'text', 'bio'].includes(pKey)) {
                newMapping[param.key] = 'post_content';
            }
            // 2. Exact Meta Field Match
            else {
                const metaMatch = target.metaFields.find(mf => mf.key === param.key);
                if (metaMatch) {
                    newMapping[param.key] = metaMatch.key;
                }
            }
        });
    }
    return newMapping;
  };

  const handleTargetCptChange = (newSlug: string) => {
      const newMapping = generateAutoMapping(newSlug);
      onChange({
          ...endpoint,
          storage: {
              ...endpoint.storage!,
              targetCptSlug: newSlug,
              fieldMapping: newMapping
          }
      });
  };

  const handleMappingChange = (paramKey: string, metaKey: string) => {
    if (!endpoint.storage) return;
    const newMapping = { ...endpoint.storage.fieldMapping };
    if (metaKey === '' || metaKey === '(None)') {
      delete newMapping[paramKey];
    } else {
      newMapping[paramKey] = metaKey;
    }
    onChange({
      ...endpoint,
      storage: {
        ...endpoint.storage,
        fieldMapping: newMapping
      }
    });
  };

  const methods: EndpointMethod[] = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'];
  const targetCpt = postTypes.find(pt => pt.slug === endpoint.storage?.targetCptSlug);

  return (
    <div className="h-full overflow-y-auto p-6 md:p-10 custom-scrollbar">
      {/* Header */}
      <div className="flex justify-between items-start mb-10">
        <div className="flex items-center gap-4">
           <div className="w-12 h-12 bg-pink-500/10 rounded-xl flex items-center justify-center border border-pink-500/20">
              <Network className="text-pink-500" size={24} />
           </div>
           <div>
             <h2 className="text-2xl font-bold text-white tracking-tight font-mono">{endpoint.route}</h2>
             <p className="text-zinc-500 text-sm">Endpoint Configuration</p>
           </div>
        </div>
        <button 
          onClick={onDelete}
          className="text-red-400 hover:bg-red-500/10 px-3 py-2 rounded-lg transition-colors flex items-center gap-2 text-sm font-medium border border-transparent hover:border-red-500/20"
        >
          <Trash2 size={16} />
          Delete
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">

        {/* Left Column: Configuration */}
        <div className="lg:col-span-2 space-y-8">

           {/* Basic Info */}
           <div className="bg-[#121214] border border-zinc-800 rounded-xl p-6">
              <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-widest mb-6">Route Settings</h3>

              <div className="grid grid-cols-2 gap-6">
                 <div className="col-span-2">
                    <label className="text-[10px] text-zinc-500 font-bold mb-1 block">ROUTE PATH</label>
                    <div className="flex items-center">
                        <span className="bg-zinc-900 border border-r-0 border-zinc-700 text-zinc-400 px-3 py-2 rounded-l text-sm font-mono">/{namespace}/</span>
                        <input 
                            type="text" 
                            value={endpoint.route.startsWith('/') ? endpoint.route.substring(1) : endpoint.route} 
                            onChange={e => onChange({...endpoint, route: '/' + e.target.value})}
                            className="flex-1 bg-zinc-900 border border-zinc-700 rounded-r px-3 py-2 text-white font-mono text-sm focus:border-pink-500 outline-none"
                        />
                    </div>
                 </div>

                 <div>
                    <label className="text-[10px] text-zinc-500 font-bold mb-2 block">HTTP METHOD</label>
                    <div className="flex flex-wrap gap-2">
                        {methods.map(m => (
                            <button
                            key={m}
                            onClick={() => onChange({ ...endpoint, method: m })}
                            className={`px-3 py-1.5 rounded text-[10px] font-bold transition-all border ${endpoint.method === m 
                                ? 'bg-pink-600 border-pink-500 text-white shadow-lg shadow-pink-500/20' 
                                : 'bg-zinc-900 border-zinc-800 text-zinc-500 hover:border-zinc-700'}`}
                            >
                            {m}
                            </button>
                        ))}
                    </div>
                 </div>

                 <div>
                    <label className="text-[10px] text-zinc-500 font-bold mb-1 block">CALLBACK FUNCTION</label>
                    <input 
                        type="text" 
                        value={endpoint.callbackFunction} 
                        onChange={e => onChange({...endpoint, callbackFunction: e.target.value})}
                        className="w-full bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-white font-mono text-xs focus:border-pink-500 outline-none"
                    />
                 </div>
              </div>
           </div>

           {/* Parameters */}
           <div className="bg-[#121214] border border-zinc-800 rounded-xl p-6">
              <div className="flex justify-between items-center mb-6">
                 <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-widest">Input Parameters</h3>
                 <button 
                    onClick={addParam}
                    className="flex items-center gap-1.5 text-xs bg-pink-600 hover:bg-pink-500 text-white px-3 py-1.5 rounded-full transition-all shadow-lg shadow-pink-900/20 font-medium"
                 >
                    <Plus size={14} /> Add Parameter
                 </button>
              </div>

              <div className="space-y-2">
                 {endpoint.parameters.length === 0 && (
                     <div className="text-center py-8 bg-zinc-900/30 rounded border border-dashed border-zinc-800">
                         <span className="text-xs text-zinc-600">No parameters defined.</span>
                     </div>
                 )}
                 {endpoint.parameters.map((param) => (
                    <div key={param.id} className="grid grid-cols-12 gap-3 items-center bg-zinc-900/50 p-2 rounded border border-zinc-800/50 hover:border-zinc-700 transition-colors">
                        <div className="col-span-3">
                            <input 
                                type="text" placeholder="key" value={param.key} onChange={e => handleParamChange(param.id, { key: e.target.value })}
                                className="w-full bg-transparent text-xs text-pink-300 font-mono focus:outline-none placeholder-zinc-700"
                            />
                        </div>
                        <div className="col-span-2">
                            <select value={param.type} onChange={e => handleParamChange(param.id, { type: e.target.value })} className="bg-zinc-800 text-xs text-zinc-400 rounded px-1 py-0.5 border-none outline-none">
                                <option value="string">string</option>
                                <option value="integer">integer</option>
                                <option value="boolean">boolean</option>
                            </select>
                        </div>
                        <div className="col-span-5">
                            <input type="text" placeholder="Description..." value={param.description} onChange={e => handleParamChange(param.id, { description: e.target.value })} className="w-full bg-transparent text-xs text-zinc-500 focus:outline-none placeholder-zinc-800"/>
                        </div>
                        <div className="col-span-2 flex items-center justify-end gap-3">
                            <input type="checkbox" checked={param.required} onChange={e => handleParamChange(param.id, { required: e.target.checked })} className="rounded bg-zinc-800 border-zinc-700 text-pink-500 w-3 h-3"/>
                            <button onClick={() => removeParam(param.id)} className="text-zinc-600 hover:text-red-400"><Trash2 size={12} /></button>
                        </div>
                    </div>
                 ))}
              </div>
           </div>

           {/* Custom PHP */}
           <div className="space-y-2">
              <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                 <Code size={14} /> Custom Logic
              </h3>
              <CodeEditor 
                value={endpoint.customPhp || ''}
                onChange={(val) => onChange({...endpoint, customPhp: val})}
                parameters={endpoint.parameters}
                targetCptSlug={endpoint.storage?.enabled ? endpoint.storage.targetCptSlug : undefined}
                postTypes={postTypes}
              />
           </div>

        </div>

        {/* Right Column: Flow Logic */}
        <div className="space-y-6">

            {/* Hooks */}
            <div className="bg-[#121214] border border-zinc-800 rounded-xl p-5 shadow-sm">
                <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-4">Hooks & Actions</h3>
                <div>
                    <label className="text-[10px] text-zinc-500 font-bold mb-1 block">WP ACTION HOOK</label>
                    <div className="flex items-center gap-2">
                        <span className="text-zinc-600 font-mono text-xs">do_action('</span>
                        <input 
                            type="text" 
                            value={endpoint.hookName || ''} 
                            onChange={e => onChange({...endpoint, hookName: e.target.value})}
                            placeholder="my_action"
                            className="bg-transparent border-b border-zinc-700 text-yellow-400 font-mono text-xs focus:outline-none focus:border-yellow-500 px-1 py-0.5 w-full"
                        />
                        <span className="text-zinc-600 font-mono text-xs">')</span>
                    </div>
                </div>
            </div>

            {/* Storage Automator */}
            <div className={`bg-[#121214] border transition-all rounded-xl p-5 shadow-sm relative overflow-hidden ${endpoint.storage?.enabled ? 'border-green-500/30' : 'border-zinc-800'}`}>
                 <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                     <Database size={80} />
                 </div>

                 <div className="flex items-center justify-between mb-4">
                     <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider">Storage Automator</h3>
                     <label className="relative inline-flex items-center cursor-pointer">
                        <input 
                        type="checkbox" 
                        className="sr-only peer" 
                        checked={endpoint.storage?.enabled || false}
                        onChange={e => handleStorageToggle(e.target.checked)}
                        />
                        <div className="w-8 h-4 bg-zinc-800 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-zinc-400 after:border-gray-300 after:border after:rounded-full after:h-3 after:w-3 after:transition-all peer-checked:bg-green-600 peer-checked:after:bg-white"></div>
                    </label>
                 </div>

                 {endpoint.storage?.enabled ? (
                     <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
                         <div>
                            <label className="text-[10px] text-zinc-500 font-bold mb-1 block">TARGET MODEL</label>
                            <select
                                value={endpoint.storage.targetCptSlug}
                                onChange={e => handleTargetCptChange(e.target.value)}
                                className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-xs text-white focus:outline-none"
                            >
                                {postTypes.map(pt => (
                                    <option key={pt.slug} value={pt.slug}>{pt.singularName}</option>
                                ))}
                            </select>
                         </div>

                         {targetCpt && (
                             <div className="bg-zinc-900/50 rounded p-3 border border-zinc-800">
                                 <div className="flex justify-between items-center mb-2">
                                     <p className="text-[10px] text-zinc-400 font-bold uppercase">Field Mapping</p>
                                     <span className="text-[9px] text-green-500 font-mono">Auto-matched</span>
                                 </div>
                                 <div className="space-y-1">
                                    {endpoint.parameters.map(param => (
                                        <div key={param.id} className="flex items-center justify-between gap-2">
                                            <span className="text-[10px] font-mono text-pink-300 w-1/3 truncate">{param.key}</span>
                                            <ArrowRight size={10} className="text-zinc-600" />
                                            <select
                                                value={endpoint.storage?.fieldMapping[param.key] || ''}
                                                onChange={e => handleMappingChange(param.key, e.target.value)}
                                                className="w-1/2 bg-zinc-800 border-none rounded px-1 py-1 text-[10px] text-zinc-300 outline-none focus:ring-1 focus:ring-green-500/50"
                                            >
                                                <option value="">(None)</option>
                                                <option value="post_title">Title</option>
                                                <option value="post_content">Content</option>
                                                {targetCpt.metaFields.map(mf => (
                                                    <option key={mf.key} value={mf.key}>{mf.key}</option>
                                                ))}
                                            </select>
                                        </div>
                                    ))}
                                 </div>
                             </div>
                         )}
                     </div>
                 ) : (
                     <p className="text-[10px] text-zinc-600 leading-relaxed">
                        Enable to automatically map incoming parameters to a Custom Post Type without writing PHP.
                     </p>
                 )}
            </div>

        </div>

      </div>
    </div>
  );
};

import React from 'react';
import { CustomEndpoint, EndpointMethod, EndpointParameter, CustomPostType } from '../types';
import { Trash2, Settings, Plus, Network, Database, ArrowRight, Code } from 'lucide-react';
import { CodeEditor } from './CodeEditor';

interface EndpointEditorProps {
  endpoint: CustomEndpoint;
  namespace: string;
  postTypes: CustomPostType[];
  onChange: (updated: CustomEndpoint) => void;
  onDelete: () => void;
}

export const EndpointEditor: React.FC<EndpointEditorProps> = ({ endpoint, namespace, postTypes, onChange, onDelete }) => {

  const handleParamChange = (id: string, changes: Partial<EndpointParameter>) => {
    const updatedParams = endpoint.parameters.map(p => p.id === id ? { ...p, ...changes } : p);
    onChange({ ...endpoint, parameters: updatedParams });
  };

  const addParam = () => {
    const newParam: EndpointParameter = {
      id: `param_${Date.now()}`,
      key: 'new_param',
      type: 'string',
      required: false,
      description: ''
    };
    onChange({ ...endpoint, parameters: [...endpoint.parameters, newParam] });
  };

  const removeParam = (id: string) => {
    onChange({ ...endpoint, parameters: endpoint.parameters.filter(p => p.id !== id) });
  };

  const handleStorageToggle = (enabled: boolean) => {
    // Default to first available CPT if enabling
    const defaultSlug = endpoint.storage?.targetCptSlug || (postTypes[0]?.slug || '');

    // Trigger auto-map immediately if enabling
    let initialMapping: Record<string, string> = endpoint.storage?.fieldMapping || {};

    // Only auto-map if mapping is empty to avoid overwriting existing config on toggle
    if (enabled && Object.keys(initialMapping).length === 0 && defaultSlug) {
        initialMapping = generateAutoMapping(defaultSlug);
    }

    onChange({
      ...endpoint,
      storage: {
        enabled,
        targetCptSlug: defaultSlug,
        fieldMapping: initialMapping
      }
    });
  };

  const generateAutoMapping = (cptSlug: string): Record<string, string> => {
    const target = postTypes.find(pt => pt.slug === cptSlug);
    const newMapping: Record<string, string> = {};

    if (target) {
        endpoint.parameters.forEach(param => {
            const pKey = param.key.toLowerCase();

            // 1. Native WP Field Heuristics
            if (['title', 'name', 'subject', 'headline', 'label'].includes(pKey)) {
                newMapping[param.key] = 'post_title';
                return;
            } 
            if (['content', 'body', 'description', 'message', 'text', 'bio'].includes(pKey)) {
                newMapping[param.key] = 'post_content';
                return;
            }

            // 2. Exact Meta Field Match
            const exactMatch = target.metaFields.find(mf => mf.key === param.key);
            if (exactMatch) {
                newMapping[param.key] = exactMatch.key;
                return;
            }

            // 3. Fuzzy / Smart Meta Match (Enhanced)
            // e.g. param 'email' -> meta 'user_email' or 'contact_email'
            // e.g. param 'url' -> meta 'website_url'
            const fuzzyMatch = target.metaFields.find(mf => {
                const mKey = mf.key.toLowerCase();
                // Check for common suffixes/prefixes (e.g. user_email matching email)
                if (mKey.endsWith(`_${pKey}`) || mKey.startsWith(`${pKey}_`)) return true;
                // Check if param key is substantially inside meta key (e.g. email in contact_email)
                if (pKey.length > 3 && mKey.includes(pKey)) return true;
                return false;
            });

            if (fuzzyMatch) {
                newMapping[param.key] = fuzzyMatch.key;
            }
        });
    }
    return newMapping;
  };

  const handleTargetCptChange = (newSlug: string) => {
      const newMapping = generateAutoMapping(newSlug);
      onChange({
          ...endpoint,
          storage: {
              ...endpoint.storage!,
              targetCptSlug: newSlug,
              fieldMapping: newMapping
          }
      });
  };

  const handleMappingChange = (paramKey: string, metaKey: string) => {
    if (!endpoint.storage) return;
    const newMapping = { ...endpoint.storage.fieldMapping };

    // Explicitly handle 'None' by removing the key
    if (metaKey === '' || metaKey === '(None)') {
      delete newMapping[paramKey];
    } else {
      newMapping[paramKey] = metaKey;
    }

    onChange({
      ...endpoint,
      storage: {
        ...endpoint.storage,
        fieldMapping: newMapping
      }
    });
  };

  const methods: EndpointMethod[] = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'];
  const targetCpt = postTypes.find(pt => pt.slug === endpoint.storage?.targetCptSlug);

  return (
    <div className="h-full overflow-y-auto p-6 md:p-10 custom-scrollbar">
      {/* Header */}
      <div className="flex justify-between items-start mb-10">
        <div className="flex items-center gap-4">
           <div className="w-12 h-12 bg-pink-500/10 rounded-xl flex items-center justify-center border border-pink-500/20">
              <Network className="text-pink-500" size={24} />
           </div>
           <div>
             <h2 className="text-2xl font-bold text-white tracking-tight font-mono">{endpoint.route}</h2>
             <p className="text-zinc-500 text-sm">Endpoint Configuration</p>
           </div>
        </div>
        <button 
          onClick={onDelete}
          className="text-red-400 hover:bg-red-500/10 px-3 py-2 rounded-lg transition-colors flex items-center gap-2 text-sm font-medium border border-transparent hover:border-red-500/20"
        >
          <Trash2 size={16} />
          Delete
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">

        {/* Left Column: Configuration */}
        <div className="lg:col-span-2 space-y-8">

           {/* Basic Info */}
           <div className="bg-[#121214] border border-zinc-800 rounded-xl p-6">
              <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-widest mb-6">Route Settings</h3>

              <div className="grid grid-cols-2 gap-6">
                 <div className="col-span-2">
                    <label className="text-[10px] text-zinc-500 font-bold mb-1 block">ROUTE PATH</label>
                    <div className="flex items-center">
                        <span className="bg-zinc-900 border border-r-0 border-zinc-700 text-zinc-400 px-3 py-2 rounded-l text-sm font-mono">/{namespace}/</span>
                        <input 
                            type="text" 
                            value={endpoint.route.startsWith('/') ? endpoint.route.substring(1) : endpoint.route} 
                            onChange={e => onChange({...endpoint, route: '/' + e.target.value})}
                            className="flex-1 bg-zinc-900 border border-zinc-700 rounded-r px-3 py-2 text-white font-mono text-sm focus:border-pink-500 outline-none"
                        />
                    </div>
                 </div>

                 <div>
                    <label className="text-[10px] text-zinc-500 font-bold mb-2 block">HTTP METHOD</label>
                    <div className="flex flex-wrap gap-2">
                        {methods.map(m => (
                            <button
                            key={m}
                            onClick={() => onChange({ ...endpoint, method: m })}
                            className={`px-3 py-1.5 rounded text-[10px] font-bold transition-all border ${endpoint.method === m 
                                ? 'bg-pink-600 border-pink-500 text-white shadow-lg shadow-pink-500/20' 
                                : 'bg-zinc-900 border-zinc-800 text-zinc-500 hover:border-zinc-700'}`}
                            >
                            {m}
                            </button>
                        ))}
                    </div>
                 </div>

                 <div>
                    <label className="text-[10px] text-zinc-500 font-bold mb-1 block">CALLBACK FUNCTION</label>
                    <input 
                        type="text" 
                        value={endpoint.callbackFunction} 
                        onChange={e => onChange({...endpoint, callbackFunction: e.target.value})}
                        className="w-full bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-white font-mono text-xs focus:border-pink-500 outline-none"
                    />
                 </div>
              </div>
           </div>

           {/* Parameters */}
           <div className="bg-[#121214] border border-zinc-800 rounded-xl p-6">
              <div className="flex justify-between items-center mb-6">
                 <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-widest">Input Parameters</h3>
                 <button 
                    onClick={addParam}
                    className="flex items-center gap-1.5 text-xs bg-pink-600 hover:bg-pink-500 text-white px-3 py-1.5 rounded-full transition-all shadow-lg shadow-pink-900/20 font-medium"
                 >
                    <Plus size={14} /> Add Parameter
                 </button>
              </div>

              <div className="space-y-2">
                 {endpoint.parameters.length === 0 && (
                     <div className="text-center py-8 bg-zinc-900/30 rounded border border-dashed border-zinc-800">
                         <span className="text-xs text-zinc-600">No parameters defined.</span>
                     </div>
                 )}
                 {endpoint.parameters.map((param) => (
                    <div key={param.id} className="grid grid-cols-12 gap-3 items-center bg-zinc-900/50 p-2 rounded border border-zinc-800/50 hover:border-zinc-700 transition-colors">
                        <div className="col-span-3">
                            <input 
                                type="text" placeholder="key" value={param.key} onChange={e => handleParamChange(param.id, { key: e.target.value })}
                                className="w-full bg-transparent text-xs text-pink-300 font-mono focus:outline-none placeholder-zinc-700"
                            />
                        </div>
                        <div className="col-span-2">
                            <select value={param.type} onChange={e => handleParamChange(param.id, { type: e.target.value })} className="bg-zinc-800 text-xs text-zinc-400 rounded px-1 py-0.5 border-none outline-none">
                                <option value="string">string</option>
                                <option value="integer">integer</option>
                                <option value="boolean">boolean</option>
                            </select>
                        </div>
                        <div className="col-span-5">
                            <input type="text" placeholder="Description..." value={param.description} onChange={e => handleParamChange(param.id, { description: e.target.value })} className="w-full bg-transparent text-xs text-zinc-500 focus:outline-none placeholder-zinc-800"/>
                        </div>
                        <div className="col-span-2 flex items-center justify-end gap-3">
                            <input type="checkbox" checked={param.required} onChange={e => handleParamChange(param.id, { required: e.target.checked })} className="rounded bg-zinc-800 border-zinc-700 text-pink-500 w-3 h-3"/>
                            <button onClick={() => removeParam(param.id)} className="text-zinc-600 hover:text-red-400"><Trash2 size={12} /></button>
                        </div>
                    </div>
                 ))}
              </div>
           </div>

           {/* Custom PHP */}
           <div className="space-y-2">
              <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                 <Code size={14} /> Custom Logic
              </h3>
              <CodeEditor 
                value={endpoint.customPhp || ''}
                onChange={(val) => onChange({...endpoint, customPhp: val})}
                parameters={endpoint.parameters}
                targetCptSlug={endpoint.storage?.enabled ? endpoint.storage.targetCptSlug : undefined}
                postTypes={postTypes}
              />
           </div>

        </div>

        {/* Right Column: Flow Logic */}
        <div className="space-y-6">

            {/* Hooks */}
            <div className="bg-[#121214] border border-zinc-800 rounded-xl p-5 shadow-sm">
                <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-4">Hooks & Actions</h3>
                <div>
                    <label className="text-[10px] text-zinc-500 font-bold mb-1 block">WP ACTION HOOK</label>
                    <div className="flex items-center gap-2">
                        <span className="text-zinc-600 font-mono text-xs">do_action('</span>
                        <input 
                            type="text" 
                            value={endpoint.hookName || ''} 
                            onChange={e => onChange({...endpoint, hookName: e.target.value})}
                            placeholder="my_action"
                            className="bg-transparent border-b border-zinc-700 text-yellow-400 font-mono text-xs focus:outline-none focus:border-yellow-500 px-1 py-0.5 w-full"
                        />
                        <span className="text-zinc-600 font-mono text-xs">')</span>
                    </div>
                </div>
            </div>

            {/* Storage Automator */}
            <div className={`bg-[#121214] border transition-all rounded-xl p-5 shadow-sm relative overflow-hidden ${endpoint.storage?.enabled ? 'border-green-500/30' : 'border-zinc-800'}`}>
                 <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                     <Database size={80} />
                 </div>

                 <div className="flex items-center justify-between mb-4">
                     <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider">Storage Automator</h3>
                     <label className="relative inline-flex items-center cursor-pointer">
                        <input 
                        type="checkbox" 
                        className="sr-only peer" 
                        checked={endpoint.storage?.enabled || false}
                        onChange={e => handleStorageToggle(e.target.checked)}
                        />
                        <div className="w-8 h-4 bg-zinc-800 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-zinc-400 after:border-gray-300 after:border after:rounded-full after:h-3 after:w-3 after:transition-all peer-checked:bg-green-600 peer-checked:after:bg-white"></div>
                    </label>
                 </div>

                 {endpoint.storage?.enabled ? (
                     <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
                         <div>
                            <label className="text-[10px] text-zinc-500 font-bold mb-1 block">TARGET MODEL</label>
                            <select
                                value={endpoint.storage.targetCptSlug}
                                onChange={e => handleTargetCptChange(e.target.value)}
                                className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-xs text-white focus:outline-none"
                            >
                                {postTypes.map(pt => (
                                    <option key={pt.slug} value={pt.slug}>{pt.singularName}</option>
                                ))}
                            </select>
                         </div>

                         {targetCpt && (
                             <div className="bg-zinc-900/50 rounded p-3 border border-zinc-800">
                                 <div className="flex justify-between items-center mb-2">
                                     <p className="text-[10px] text-zinc-400 font-bold uppercase">Field Mapping</p>
                                     <span className="text-[9px] text-green-500 font-mono">Auto-matched</span>
                                 </div>
                                 <div className="space-y-1">
                                    {endpoint.parameters.map(param => (
                                        <div key={param.id} className="flex items-center justify-between gap-2">
                                            <span className="text-[10px] font-mono text-pink-300 w-1/3 truncate">{param.key}</span>
                                            <ArrowRight size={10} className="text-zinc-600" />
                                            <select
                                                value={endpoint.storage?.fieldMapping[param.key] || ''}
                                                onChange={e => handleMappingChange(param.key, e.target.value)}
                                                className="w-1/2 bg-zinc-800 border-none rounded px-1 py-1 text-[10px] text-zinc-300 outline-none focus:ring-1 focus:ring-green-500/50"
                                            >
                                                <option value="">(None)</option>
                                                <option value="post_title">Title</option>
                                                <option value="post_content">Content</option>
                                                {targetCpt.metaFields.map(mf => (
                                                    <option key={mf.key} value={mf.key}>{mf.key}</option>
                                                ))}
                                            </select>
                                        </div>
                                    ))}
                                 </div>
                             </div>
                         )}
                     </div>
                 ) : (
                     <p className="text-[10px] text-zinc-600 leading-relaxed">
                        Enable to automatically map incoming parameters to a Custom Post Type without writing PHP.
                     </p>
                 )}
            </div>

        </div>

      </div>
    </div>
  );
};

