      connectedPostTypes: []
    };
    setProject(prev => ({ ...prev, taxonomies: [...prev.taxonomies, newTax] }));
    setEditingResource({ type: 'taxonomy', id: newId });
    logger.success('Added new Taxonomy');
  };

  const handleDeleteResource = (id: string) => {
    setProject(prev => ({
      ...prev,
      postTypes: prev.postTypes.filter(pt => pt.id !== id)
    }));
    if (editingResource?.id === id) setEditingResource(null);
    logger.info(`Deleted Resource ID: ${id}`);
  };

  const handleDeleteEndpoint = (id: string) => {
    setProject(prev => ({
      ...prev,
      customEndpoints: prev.customEndpoints.filter(ep => ep.id !== id)
    }));
    if (editingResource?.id === id) setEditingResource(null);
    logger.info(`Deleted Endpoint ID: ${id}`);
  };

  const handleDeleteTaxonomy = (id: string) => {
    setProject(prev => ({
      ...prev,
      taxonomies: prev.taxonomies.filter(t => t.id !== id)
    }));
    if (editingResource?.id === id) setEditingResource(null);
    logger.info(`Deleted Taxonomy ID: ${id}`);
  };

  const handleDuplicate = (type: ResourceType, id: string) => {
    if (type === 'postType') {
       const original = project.postTypes.find(pt => pt.id === id);
       if (original) {
         const newId = `cpt_${Date.now()}`;
         const copy = { ...original, id: newId, slug: `${original.slug}_copy`, singularName: `${original.singularName} Copy`, pluralName: `${original.pluralName} Copy` };
         setProject(prev => ({ ...prev, postTypes: [...prev.postTypes, copy] }));
         setEditingResource({ type: 'postType', id: newId });
         logger.success(`Duplicated Post Type: ${original.slug}`);
       }
    } else if (type === 'endpoint') {
      const original = project.customEndpoints.find(ep => ep.id === id);
      if (original) {
        const newId = `endpoint_${Date.now()}`;
        const copy = { ...original, id: newId, route: `${original.route}-copy` };
        setProject(prev => ({ ...prev, customEndpoints: [...prev.customEndpoints, copy] }));
        setEditingResource({ type: 'endpoint', id: newId });
        logger.success(`Duplicated Endpoint: ${original.route}`);
      }
    } else if (type === 'taxonomy') {
      const original = project.taxonomies.find(t => t.id === id);
      if (original) {
        const newId = `tax_${Date.now()}`;
        const copy = { ...original, id: newId, slug: `${original.slug}_copy` };
        setProject(prev => ({ ...prev, taxonomies: [...prev.taxonomies, copy] }));
        setEditingResource({ type: 'taxonomy', id: newId });
        logger.success(`Duplicated Taxonomy: ${original.slug}`);
      }
    }
  };

  const handleConnect = (source: { type: ResourceType, id: string }, target: { type: ResourceType, id: string }) => {
    // 1. Link Endpoint -> CPT (Enable Storage)
    if (source.type === 'endpoint' && target.type === 'postType') {
      const endpoint = project.customEndpoints.find(ep => ep.id === source.id);
      const targetCpt = project.postTypes.find(pt => pt.id === target.id);

      if (endpoint && targetCpt) {
         const newStorage = {
            enabled: true,
            targetCptSlug: targetCpt.slug,
            fieldMapping: { ...endpoint.storage?.fieldMapping }
         };
         // Intelligent Auto-Mapping
         endpoint.parameters.forEach(param => {
             if (param.key === 'title' || param.key === 'name') newStorage.fieldMapping[param.key] = 'post_title';
             else if (param.key === 'content' || param.key === 'description' || param.key === 'body') newStorage.fieldMapping[param.key] = 'post_content';
             else {
                 const match = targetCpt.metaFields.find(mf => mf.key === param.key);
                 if (match) newStorage.fieldMapping[param.key] = match.key;
             }
         });
         handleUpdateEndpoint({ ...endpoint, storage: newStorage });
         logger.success(`Linked Route ${endpoint.route} to Model ${targetCpt.singularName}`);
      }
    }
    // 2. Link CPT -> CPT (Create Relationship Field)
    if (source.type === 'postType' && target.type === 'postType' && source.id !== target.id) {
       const sourceCpt = project.postTypes.find(pt => pt.id === source.id);
       const targetCpt = project.postTypes.find(pt => pt.id === target.id);
       if (sourceCpt && targetCpt) {
          const existing = sourceCpt.metaFields.find(f => f.type === FieldType.RELATIONSHIP && f.targetPostType === targetCpt.slug);
          if (existing) {
             logger.warn('Relationship already exists.');
             return;
          }
          const newField: MetaField = {
             id: `field_${Date.now()}`,
             key: `${targetCpt.slug}_id`,
             label: `Related ${targetCpt.singularName}`,
             type: FieldType.RELATIONSHIP,
             description: `Link to a ${targetCpt.singularName}`,
             required: false,
             showInRest: true,
             targetPostType: targetCpt.slug
          };
          handleUpdateResource({
             ...sourceCpt,
             metaFields: [...sourceCpt.metaFields, newField]
          });
          logger.success(`Created Relationship: ${sourceCpt.singularName} -> ${targetCpt.singularName}`);
       }
    }
  };

  const handleAIApply = (partial: Partial<ProjectState>) => {
    setProject(prev => ({
      ...prev,
      postTypes: [...prev.postTypes, ...(partial.postTypes || [])],
      taxonomies: [...prev.taxonomies, ...(partial.taxonomies || [])],
      customEndpoints: [...prev.customEndpoints, ...(partial.customEndpoints || [])]
    }));
    logger.success('Applied AI generated structure');
  };

  const handleViewChange = (view: ViewMode) => {
    setCurrentView(view);
  };

  const handleSelect = (type: ResourceType, id: string) => {
    setEditingResource({ type, id });
  };

  const renderMainContent = () => {
    switch (currentView) {
      case 'openapi':
        return <CodePreview project={project} initialTab="openapi" />;
      case 'php':
        return <CodePreview project={project} initialTab="php" />;
      case 'playground':
        return <CodePreview project={project} initialTab="playground" />;
      case 'flow':
        return (
           <FlowDesigner 
             project={project} 
             onSelect={handleSelect}
             onDelete={(type, id) => {
               if (type === 'postType') handleDeleteResource(id);
               else if (type === 'endpoint') handleDeleteEndpoint(id);
               else if (type === 'taxonomy') handleDeleteTaxonomy(id);
             }}
             onDuplicate={handleDuplicate}
             onAdd={(type) => {
               if (type === 'postType') handleAddResource();
               else if (type === 'endpoint') handleAddEndpoint();
               else if (type === 'taxonomy') handleAddTaxonomy();
             }}
             onConnect={handleConnect}
           />
        );
      case 'blueprint':
        return <BlueprintView project={project} />;
      case 'settings':
        return <SettingsScreen settings={settings} onSave={setSettings} />;
      case 'code':
        return (
          <GlobalLogicEditor 
            project={project}
            onUpdate={handleUpdateHelper}
            onAdd={handleAddHelper}
            onDelete={handleDeleteHelper}
          />
        );
      default:
        return (
          <div className="flex flex-col items-center justify-center h-full text-zinc-500">
             <div className="p-8 bg-zinc-900/50 rounded-full mb-4">
               <LayoutTemplate size={48} className="text-zinc-700" />
             </div>
             <p className="text-lg font-medium mb-2">Welcome to WP API Architect</p>
             <p className="text-sm">Quick editing is available via sidebar or visual designers.</p>
          </div>
        );
    }
  };

  const editingCpt = editingResource?.type === 'postType' ? project.postTypes.find(pt => pt.id === editingResource.id) : null;
  const editingEndpoint = editingResource?.type === 'endpoint' ? project.customEndpoints.find(ep => ep.id === editingResource.id) : null;
  const editingTaxonomy = editingResource?.type === 'taxonomy' ? project.taxonomies.find(t => t.id === editingResource.id) : null;

  return (
    <div className="flex h-screen bg-zinc-950 text-zinc-100 overflow-hidden font-sans selection:bg-indigo-500/30">

      <Sidebar 
        project={project}
        currentView={currentView}
        selection={editingResource || { type: 'postType', id: '' }}
        isTerminalOpen={isTerminalOpen}
        onSelect={handleSelect}
        onViewChange={handleViewChange}
        onAddResource={handleAddResource}
        onAddEndpoint={handleAddEndpoint}
        onAddTaxonomy={handleAddTaxonomy}
        onToggleTerminal={() => setIsTerminalOpen(!isTerminalOpen)}
        onOpenAI={() => setAIModalOpen(true)}
      />

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#09090b] relative">
        <div className="absolute inset-0 bg-gradient-to-br from-zinc-900 via-black to-zinc-950 pointer-events-none opacity-50 z-0"/>
        <div className="relative z-10 flex-1 flex flex-col min-h-0">
           {renderMainContent()}
        </div>
        {isTerminalOpen && <Terminal onClose={() => setIsTerminalOpen(false)} />}
      </div>

      {/* Editor Modal Overlay */}
      <EditorModal 
        isOpen={!!editingResource} 
        onClose={() => setEditingResource(null)}
        title={
          editingCpt ? `Edit Model: ${editingCpt.singularName}` : 
          editingEndpoint ? `Edit Route: ${editingEndpoint.route}` : 
          editingTaxonomy ? `Edit Taxonomy: ${editingTaxonomy.singularName}` : 
          "Editor"
        }
      >
        {editingCpt && (
          <ResourceEditor 
            cpt={editingCpt} 
            allTaxonomies={project.taxonomies}
            allPostTypes={project.postTypes}
            onChange={handleUpdateResource}
            onDelete={() => handleDeleteResource(editingCpt.id)}
          />
        )}
        {editingEndpoint && (
          <EndpointEditor
            endpoint={editingEndpoint}
            namespace={project.namespace}
            postTypes={project.postTypes}
            onChange={handleUpdateEndpoint}
            onDelete={() => handleDeleteEndpoint(editingEndpoint.id)}
          />
        )}
        {editingTaxonomy && (
          <TaxonomyEditor
            taxonomy={editingTaxonomy}
            postTypes={project.postTypes}
            onChange={handleUpdateTaxonomy}
            onDelete={() => handleDeleteTaxonomy(editingTaxonomy.id)}
          />
        )}
      </EditorModal>

      {isAIModalOpen && (
        <AIAssistant 
          project={project}
          settings={settings}
          onApply={handleAIApply} 
          onClose={() => setAIModalOpen(false)} 
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { EndpointParameter, CustomPostType } from '../types';
import { Code, Copy, Box, Variable, Play, Check } from 'lucide-react';
import Editor from 'react-simple-code-editor';
import Prism from 'prismjs';
import 'prismjs/components/prism-clike';
import 'prismjs/components/prism-markup';
import 'prismjs/components/prism-php';

interface CodeEditorProps {
  value: string;
  onChange: (value: string) => void;
  parameters: EndpointParameter[];
  targetCptSlug?: string;
  postTypes: CustomPostType[];
}

export const CodeEditor: React.FC<CodeEditorProps> = ({ value, onChange, parameters, targetCptSlug, postTypes }) => {
  const [copied, setCopied] = React.useState(false);

  const insertSnippet = (snippet: string) => {
    // Basic insertion at end - in a full IDE we would insert at cursor, 
    // but simple editor is sufficient here.
    const newVal = value + (value ? '\n' : '') + snippet;
    onChange(newVal);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const highlightCode = (code: string) => {
    return Prism.highlight(code, Prism.languages.php, 'php')
      .split('\n')
      .map((line, i) => `<span class='line-number text-zinc-700 select-none mr-4 text-xs w-4 inline-block text-right'>${i + 1}</span>${line}`)
      .join('\n');
  };

  const targetCpt = postTypes.find(p => p.slug === targetCptSlug);

  return (
    <div className="flex h-[500px] border border-slate-700 rounded-lg overflow-hidden bg-[#1e1e1e]">
      {/* Editor Area */}
      <div className="flex-1 flex flex-col relative min-w-0">
        <div className="bg-[#252526] px-4 py-2 border-b border-slate-700 flex justify-between items-center z-10">
            <div className="flex items-center gap-2 text-xs font-mono text-slate-400">
                <Code size={14} className="text-blue-400" />
                <span>custom_logic.php</span>
            </div>
            <div className="flex items-center gap-3">
                <span className="text-[10px] text-slate-500 uppercase bg-slate-800 px-2 py-0.5 rounded">PHP 7.4+</span>
                <button onClick={handleCopy} className="text-slate-400 hover:text-white transition-colors">
                    {copied ? <Check size={14} className="text-green-500"/> : <Copy size={14} />}
                </button>
            </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar bg-[#1d1f21] relative">
            <Editor
                value={value}
                onValueChange={code => onChange(code)}
                highlight={code => Prism.highlight(code, Prism.languages.php, 'php')}
                padding={20}
                style={{
                    fontFamily: '"Fira Code", "Consolas", monospace',
                    fontSize: 13,
                    backgroundColor: '#1d1f21',
                    minHeight: '100%',
                    color: '#c5c8c6'
                }}
                className="min-h-full"
                textareaClassName="focus:outline-none"
            />
        </div>
      </div>

      {/* Context Sidebar */}
      <div className="w-64 bg-[#252526] border-l border-slate-700 flex flex-col shrink-0 z-20">
        <div className="p-3 border-b border-slate-700 font-semibold text-xs text-slate-300 uppercase tracking-wider bg-[#2d2d30]">
            Context Variables
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-4">

            {/* Request Params */}
            <div>
                <div className="text-[10px] text-slate-500 mb-2 font-bold flex items-center gap-1">
                    <Variable size={10} /> INCOMING PARAMS
                </div>
                {parameters.map(param => (
                    <button
                        key={param.id}
                        onClick={() => insertSnippet(`$${param.key} = $request->get_param('${param.key}');`)}
                        className="w-full text-left text-xs font-mono text-pink-300 hover:bg-[#37373d] p-1.5 rounded truncate transition-colors group border border-transparent hover:border-slate-600"
                        title={`Click to insert $${param.key}`}
                    >
                        <span className="text-pink-500">$</span>{param.key}
                    </button>
                ))}
                {parameters.length === 0 && <span className="text-xs text-slate-600 italic px-2">No parameters</span>}
            </div>

            {/* Storage Context */}
            {targetCpt && (
                <div>
                    <div className="text-[10px] text-slate-500 mb-2 font-bold flex items-center gap-1">
                        <Box size={10} /> TARGET OBJECT ({targetCpt.slug})
                    </div>
                    <div className="px-2 mb-2 text-[10px] text-slate-400 leading-tight">
                        Storage enabled. <code>$post_id</code> is available.
                    </div>
                    <button
                        onClick={() => insertSnippet(`if ( $post_id ) {\n    // Additional logic for post $post_id\n}`)}
                        className="w-full text-left text-xs font-mono text-indigo-300 hover:bg-[#37373d] p-1.5 rounded truncate transition-colors border border-transparent hover:border-slate-600 mb-1"
                    >
                        Check $post_id
                    </button>
                    {targetCpt.metaFields.map(field => (
                        <button
                            key={field.id}
                            onClick={() => insertSnippet(`update_post_meta($post_id, '${field.key}', $value);`)}
                            className="w-full text-left text-xs font-mono text-slate-400 hover:bg-[#37373d] p-1.5 rounded truncate transition-colors border border-transparent hover:border-slate-600"
                        >
                            meta: {field.key}
                        </button>
                    ))}
                </div>
            )}

            {/* Snippets */}
            <div>
                <div className="text-[10px] text-slate-500 mb-2 font-bold flex items-center gap-1">
                    <Play size={10} /> SNIPPETS
                </div>
                <button
                    onClick={() => insertSnippet(`if ( is_wp_error( $result ) ) {\n    return new WP_Error( 'error', 'Message', array( 'status' => 500 ) );\n}`)}
                    className="w-full text-left text-xs text-slate-300 hover:bg-[#37373d] p-1.5 rounded transition-colors mb-1 border border-transparent hover:border-slate-600"
                >
                    Error Handling
                </button>
                <button
                    onClick={() => insertSnippet(`$user_id = get_current_user_id();`)}
                    className="w-full text-left text-xs text-slate-300 hover:bg-[#37373d] p-1.5 rounded transition-colors mb-1 border border-transparent hover:border-slate-600"
                >
                    Get User ID
                </button>
                <button
                    onClick={() => insertSnippet(`$headers = array('Content-Type: text/html; charset=UTF-8');\nwp_mail( $to, $subject, $body, $headers );`)}
                    className="w-full text-left text-xs text-slate-300 hover:bg-[#37373d] p-1.5 rounded transition-colors border border-transparent hover:border-slate-600"
                >
                    WP Mail
                </button>
            </div>

        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ProjectState } from '../types';
import { generateOpenAPI, generatePHP, generatePackageJSON, generateComposerJSON, generatePlaygroundBlueprint } from '../services/wpGenerator';
import { generateSeederPHP } from '../services/dataGenerator';
import { Copy, Check, FileCode, FileJson, Package, PlayCircle, Database, ExternalLink, Globe } from 'lucide-react';
import Prism from 'prismjs';
import 'prismjs/components/prism-json';
import 'prismjs/components/prism-php';
import 'prismjs/components/prism-bash';

interface CodePreviewProps {
  project: ProjectState;
  initialTab?: 'openapi' | 'php' | 'pkg' | 'composer' | 'blueprint' | 'seeder' | 'playground';
}

export const CodePreview: React.FC<CodePreviewProps> = ({ project, initialTab = 'openapi' }) => {
  const [tab, setTab] = useState<'openapi' | 'php' | 'pkg' | 'composer' | 'blueprint' | 'seeder' | 'playground'>(initialTab);
  const [copied, setCopied] = useState(false);
  const codeRef = useRef<HTMLElement>(null);

  let content = "";
  let language = "json";
  let playgroundUrl = "";

  if (tab === 'playground') {
      const blueprint = generatePlaygroundBlueprint(project);
      const encoded = JSON.stringify(JSON.parse(blueprint)); // minified
      playgroundUrl = `https://playground.wordpress.net/#${encoded}`;
  } else {
    switch(tab) {
        case 'openapi': 
            content = generateOpenAPI(project); 
            language = "json";
            break;
        case 'php': 
            content = generatePHP(project); 
            language = "php";
            break;
        case 'pkg': 
            content = generatePackageJSON(project); 
            language = "json";
            break;
        case 'composer': 
            content = generateComposerJSON(project); 
            language = "json";
            break;
        case 'blueprint': 
            content = generatePlaygroundBlueprint(project); 
            language = "json";
            break;
        case 'seeder': 
            content = generateSeederPHP(project); 
            language = "php";
            break;
    }
  }

  useEffect(() => {
      if (codeRef.current && tab !== 'playground') {
          // Reset class for Prism
          codeRef.current.className = `language-${language}`;
          Prism.highlightElement(codeRef.current);
      }
  }, [content, tab, language]);

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePlaygroundLaunch = () => {
     if (tab === 'playground') {
         window.open(playgroundUrl, '_blank');
     } else {
        const blueprint = generatePlaygroundBlueprint(project);
        const fragment = `#${JSON.stringify(JSON.parse(blueprint))}`;
        window.open(`https://playground.wordpress.net/${fragment}`, '_blank');
     }
  };

  const tabs = [
    { id: 'playground', label: 'Live Preview', icon: Globe, color: 'text-white', activeBg: 'bg-indigo-600' },
    { id: 'openapi', label: 'openapi.json', icon: FileJson, color: 'text-blue-400', activeBg: 'bg-blue-500/10 border-blue-500/30' },
    { id: 'php', label: 'plugin.php', icon: FileCode, color: 'text-purple-400', activeBg: 'bg-purple-500/10 border-purple-500/30' },
    { id: 'pkg', label: 'package.json', icon: Package, color: 'text-green-400', activeBg: 'bg-green-500/10 border-green-500/30' },
    { id: 'composer', label: 'composer.json', icon: Package, color: 'text-yellow-400', activeBg: 'bg-yellow-500/10 border-yellow-500/30' },
    { id: 'seeder', label: 'seeder.php', icon: Database, color: 'text-pink-400', activeBg: 'bg-pink-500/10 border-pink-500/30' },
    { id: 'blueprint', label: 'blueprint.json', icon: PlayCircle, color: 'text-blue-500', activeBg: 'bg-blue-600/10 border-blue-600/30' },
  ];

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e]">
      <div className="flex items-center justify-between px-4 py-2 bg-[#252526] border-b border-[#333]">
        <div className="flex gap-1 overflow-x-auto">
          {tabs.map(t => (
            <button
              key={t.id}
              onClick={() => setTab(t.id as any)}
              className={`flex items-center gap-2 px-4 py-2 text-xs font-medium rounded-t-lg transition-all border border-transparent whitespace-nowrap ${
                tab === t.id 
                ? `${t.activeBg} ${t.color}` 
                : 'text-slate-400 hover:bg-[#333] hover:text-slate-200'
              }`}
            >
              <t.icon size={14} />
              {t.label}
            </button>
          ))}
        </div>
        <div className="flex gap-2">
           {(tab === 'blueprint' || tab === 'playground') && (
              <button
                onClick={handlePlaygroundLaunch}
                className="flex items-center gap-2 text-xs text-white bg-blue-600 hover:bg-blue-500 px-3 py-1.5 rounded transition-colors shadow-lg shadow-blue-500/20 font-medium"
              >
                <ExternalLink size={14} />
                Open in New Tab
              </button>
           )}
          {tab !== 'playground' && (
            <button 
                onClick={handleCopy}
                className="flex items-center gap-2 text-xs text-slate-400 hover:text-white px-3 py-1.5 rounded bg-[#333] hover:bg-[#444] transition-colors"
            >
                {copied ? <Check size={14} className="text-green-500"/> : <Copy size={14} />}
                {copied ? 'Copied' : 'Copy'}
            </button>
          )}
        </div>
      </div>
      <div className="flex-1 overflow-hidden relative">
         {tab === 'playground' ? (
             <div className="w-full h-full bg-[#f0f0f1]">
                 <iframe 
                    src={playgroundUrl} 
                    className="w-full h-full border-0"
                    title="WordPress Playground"
                    loading="lazy"
                 />
             </div>
         ) : (
             <div className="w-full h-full overflow-auto p-0 custom-scrollbar bg-[#1d1f21]">
                {tab === 'blueprint' && (
                    <div className="absolute top-4 right-8 bg-[#252526] border border-[#444] p-3 rounded-lg max-w-sm text-xs text-slate-400 z-10 shadow-xl">
                    <p className="mb-2"><strong className="text-white">What is this?</strong></p>
                    <p>This blueprint allows you to instantly spin up a real WordPress instance in your browser running your generated plugin code.</p>
                    </div>
                )}
                {tab === 'seeder' && (
                    <div className="absolute top-4 right-8 bg-[#252526] border border-[#444] p-3 rounded-lg max-w-sm text-xs text-slate-400 z-10 shadow-xl">
                    <p className="mb-2"><strong className="text-pink-400">Data Seeder</strong></p>
                    <p>Drop this file into your WordPress root and run it via CLI to populate 5 dummy posts for each Custom Post Type.</p>
                    <code className="block mt-2 bg-black p-1 rounded border border-zinc-700 text-green-400">wp eval-file seeder.php</code>
                    </div>
                )}
                <pre className={`!m-0 !p-6 !bg-transparent text-sm leading-relaxed font-mono language-${language}`}>
                    <code ref={codeRef} className={`language-${language}`}>{content}</code>
                </pre>
             </div>
         )}
      </div>
    </div>
  );
};
